INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(8, 'Orang Kampung', 'Penduduk kampung Borneo yang ingin tahu apa untungnya Malaysia.', 'Mewakili suara rakyat biasa yang bertanya dan perlu diyakinkan.', 'orang_bajau.png'),
(17, 'Wartawan Akhbar', 'Wartawan yang melaporkan setiap peristiwa pembentukan Malaysia.', 'Bertanya soalan yang dijawab pemimpin dalam cerita.', 'jejaka_melayu.png'),
(18, 'Murid Sekolah', 'Murid yang ingin tahu mengapa Hari Malaysia disambut.', 'Bertanya soalan untuk menguji kefahaman pemain.', 'budak_gajet.png'),
(21, 'Tok Penglipur Lara', 'Penglipur lara tua yang mengembara dari kampung ke kampung menyampaikan cerita asal usul nama negeri.', 'Menyimpan dan menurunkan cerita asal usul nama negeri supaya warisan lisan tidak hilang.', 'orang_tradisi_lama.png'),
(26, 'Pengembara Warisan', 'Pengembara yang mencatat ibu negeri, bandar diraja dan lagu negeri di seluruh Malaysia.', 'Memperkenalkan lambang kebanggaan setiap negeri kepada generasi muda.', 'jejaka_melayu.png'),
(27, 'Nelayan Tua', 'Nelayan tua yang tinggal di pesisir pantai dan gemar bercerita tentang nama tempat.', 'Menyimpan cerita lisan tentang nama pulau dan pantai.', 'nelayan.png'),
(28, 'Pesawah Padi', 'Pesawah di utara Semenanjung yang ingin tahu asal nama negerinya.', 'Mewakili rakyat biasa yang menjaga cerita kampung.', 'pesawah_padi.png'),
(29, 'Pemburu', 'Penduduk pantai timur yang menemui catatan lama di rumah datuknya.', 'Mewakili rakyat yang menyimpan catatan lama keluarga.', 'pemburu.png'),
(30, 'Peniaga Rumah Kedai', 'Peniaga bandar yang sering ditanya pelanggan tentang nama tempat.', 'Mewakili rakyat bandar yang ingin tahu asal usul tempat tinggalnya.', 'peniaga_rumah_kedai.png'),
(31, 'Penjaga Cop', 'Penjaga cop pasport warisan di setiap wilayah.', 'Hanya memberi cop apabila Pengembara menjawab fakta dengan betul.', 'orang_tradisi_lama.png'),
(34, 'Pemuda Sarawak', 'Pemuda Sarawak yang bangga dengan nama negerinya.', 'Mewakili anak muda Sarawak yang ingin menjaga cerita asal usul negerinya.', 'sarawakian.png'),
(39, 'Pegawai Radio', 'Pegawai yang menjaga kaset dan siaran lagu negeri.', 'Memastikan lagu negeri yang betul dimainkan.', 'jejaka_melayu.png'),
(40, 'Pegawai Daerah', 'Pegawai pentadbiran yang menjaga fail ibu negeri dan bandar diraja.', 'Meminta dokumen yang betul bagi ibu negeri dan bandar diraja.', 'mageran_officer.png'),
(53, 'Pegawai Sabah', 'Pegawai dari Sabah yang bertugas di pejabat pusat.', 'Mewakili suara Sabah tentang ibu negeri dan lagu negeri.', 'perempuan_melayu.png'),
(54, 'Penghulu', 'Ketua kampung yang menjaga cerita sembilan luak.', 'Menjelaskan asal nama Selangor dan Negeri Sembilan.', 'orang_tradisi_lama.png'),
(55, 'Ahli Sejarah', 'Pencerita dan pengkaji sejarah tempatan.', 'Menyampaikan cerita lisan dan catatan tulisan tentang nama negeri.', 'ahli_antropologi_UNESCO.png'),
(56, 'Pelombong', 'Pelombong bijih timah dari Perak.', 'Mewakili cerita nama Perak dari bijih timah.', 'petani_lama.png'),
(57, 'Encik Zahar', 'Pegawai pesaing yang menukar kad, kaset dan fail istiadat.', 'Penjahat dalam cerita Tiga Hari Sebelum Istiadat.', 'pengarah_mageran.png'),
(58, 'Pegawai Istiadat Negara', 'Pegawai yang bertanggungjawab menyiapkan Istiadat Pembukaan Pesta Warisan Negara.', 'Menyusun kad gelaran, lagu dan lambang negeri dengan betul.', 'mageran_officer.png'),
(59, 'Juruteknik', 'Juruteknik pentas yang memasang papan nama.', 'Membantu memasang papan nama wilayah.', 'jejaka_melayu.png'),
(60, 'Pengacara Majlis', 'Pengacara yang mengendalikan majlis rasmi.', 'Mengumumkan majlis dan bertanya tentang lambang negeri.', 'gadis_melayu.png'),
(148, 'Pemandu Pelancong', 'Pemandu pelancong yang ramah dan bersemangat bercerita tentang negara (watak rekaan).', 'Mewakili industri pelancongan dan kempen Tahun Melawat Malaysia.', 'gadis_sarawak.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(201, 'Buku Asal Usul', 2, 'Masuki peranan Tok Penglipur Lara yang membawa Buku Asal Usul dari negeri ke negeri. Di setiap tempat kau mencatat nama, ibu negeri, lagu dan ketua negeri, hingga Pesta Warisan Negara.'),
(202, 'Tiga Hari Sebelum Istiadat', 2, 'Sebagai Pegawai Istiadat Negara, kau ada tiga hari untuk menyiapkan Istiadat Pembukaan Pesta Warisan Negara. Seseorang menukar kad, kaset dan fail. Kumpul bukti sebelum tirai dibuka.'),
(203, 'Pasport Warisan', 2, 'Sebagai Pengembara Warisan, kau membawa buku pasport dari Borneo ke Semenanjung dan mengumpul satu cop di setiap wilayah. Halaman terakhir koyak dan misterinya terungkap di Pesta Warisan Negara.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e2_n1_s1', 'Perlis, tepi sawah. Buku Asal Usul terbuka di atas pangkin. Seorang pesawah menyeret sebiji kelapa tua dari parit dan sebuah catatan lama separuh pudar terletak di sebelahnya.', 1, 201, 'negeri_perlis.png'),
('e2_n1_s2', 'Kedah, pasar lama. Pemandu gajah bertengkar dengan penjual cawan berkaki. Di dinding kedai ada tulisan Tamil yang kelihatan kuno.', 2, 201, 'negeri_kedah.png'),
('e2_n1_s3', 'Pulau Pinang, jeti sibuk dengan karung pinang. Pelombong dari Perak turun menjual bijih dan bertelagah dengan nelayan tempatan.', 3, 201, 'negeri_pulau_pinang.png'),
('e2_n1_s4', 'Pejabat daerah lama di utara. Peta Semenanjung terbentang di meja dan titik merah serta kuning bertaburan di atasnya.', 4, 201, 'bilik_mesyuarat.png'),
('e2_n1_s5', 'Anjung rumah di utara. Radio lama berbunyi perlahan. Seorang pegawai radio tidak jumpa kaset yang benar di atas rak.', 5, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s6', 'Selangor, kuala sungai. Pedagang bertemu penghulu Minangkabau. Nelayan dan penghulu bertelagah tentang nama negeri masing-masing.', 6, 201, 'negeri_selangor.png'),
('e2_n1_s7', 'Melaka, di bawah pokok tua dekat pelabuhan. Orang tua dan peniaga berbalah. Seorang pembaca naskhah menunggu dengan buku Sulalatus Salatin.', 7, 201, 'negeri_melaka.png'),
('e2_n1_s8', 'Bilik mesyuarat di tengah semenanjung. Seorang pegawai membawa fail ibu negeri dan bandar diraja yang bercampur.', 8, 201, 'bilik_mesyuarat_formal.png'),
('e2_n1_s9', 'Anjung rumah di selatan. Pegawai radio yang lebih tegang memandang dua kaset yang kelihatan serupa. Majlis bermula dalam dua jam.', 9, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s10', 'Terengganu, pantai selepas hujan. Pelangi melengkung di atas Pulau Duyong. Penduduk Pahang, Terengganu dan Kelantan berbalah.', 10, 201, 'negeri_terengganu.png'),
('e2_n1_s11', 'Bilik peta di pantai timur. Titik merah dan kuning di peta menanda Kuantan, Pekan, Kuala Terengganu dan Kota Bharu.', 11, 201, 'bilik_mesyuarat_modern.png'),
('e2_n1_s12', 'Anjung rumah di pantai timur. Radio berbunyi dan dua orang tua berbalah tentang negeri yang memiliki lagu itu.', 12, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s13', 'Sarawak, tebing sungai dengan bot dan bijih galian. Seorang ahli sejarah tempatan tercari-cari dokumen tentang nama dua negeri Borneo.', 13, 201, 'negeri_sarawak.png'),
('e2_n1_s14', 'Wilayah Persekutuan. Tiga pelawat dari Kuala Lumpur, Labuan dan Putrajaya bertanya serentak di hadapan pentas.', 14, 201, 'wilayah_persekutuan.png'),
('e2_n1_s15', 'Pejabat daerah Kuching, jendela menghadap sungai. Pegawai dari Sarawak dan Sabah membawa dua fail.', 15, 201, 'bilik_mesyuarat.png'),
('e2_n1_s16', 'Anjung rumah, radio terakhir sebelum Pesta Warisan. Pegawai radio berpeluh kerana tiga negeri belum dimainkan.', 16, 201, 'kampung_dan_pedalaman.png'),
('e2_n1_s17', 'Dewan istana. Kerusi bergelar disusun untuk majlis. Seorang pegawai istiadat yang cemas menyusun kad nama ketua-ketua negeri.', 17, 201, 'bilik_mesyuarat_formal.png'),
('e2_n1_s18', 'Pentas Pesta Warisan Negara di Wilayah Persekutuan. Bendera berkibar, jata terpampang di dinding dan radio berbunyi di atas meja. Buku Asal Usul terbuka di hadapan penonton.', 18, 201, 'wilayah_persekutuan.png'),
('e2_n2_s1', 'Putrajaya, Hari 3. Sebuah fail istiadat terbuka dan satu kad kosong terletak di tempat ketua Wilayah Persekutuan.', 1, 202, 'bilik_mesyuarat_modern.png'),
('e2_n2_s2', 'Wilayah Persekutuan, pentas. Tiga papan nama bertukar tempat dan seorang juruteknik kebingungan.', 2, 202, 'wilayah_persekutuan.png'),
('e2_n2_s3', 'Bilik mesyuarat, kad gelaran bertaburan di atas meja panjang. Ada kesan tapak kaki berlumpur di lantai.', 3, 202, 'bilik_mesyuarat_formal.png'),
('e2_n2_s4', 'Bilik mesyuarat. Seorang pembantu Yang di-Pertua Negeri meminta dokumen yang benar. Beberapa dokumen palsu bercampur di atas meja.', 4, 202, 'bilik_mesyuarat.png'),
('e2_n2_s5', 'Selangor, kuala sungai awal pagi. Jejak kasut berlumpur membawa ke sebuah balai penghulu. Sehelai piagam lama tergantung di dinding.', 5, 202, 'negeri_selangor.png'),
('e2_n2_s6', 'Melaka, di bawah pokok tua. Satu nota tersangkut di akar pokok.', 6, 202, 'negeri_melaka.png'),
('e2_n2_s7', 'Pejabat daerah. Fail ibu negeri dan bandar diraja bercampur selepas Encik Zahar datang. Satu fail hilang.', 7, 202, 'bilik_mesyuarat.png'),
('e2_n2_s8', 'Bilik radio. Empat kaset tanpa label tersusun di atas meja dan bau minyak pelincir masih segar.', 8, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s9', 'Perlis, sawah di pagi kedua. Peti pos tepi jalan menyimpan nota bersama empat kad.', 9, 202, 'negeri_perlis.png'),
('e2_n2_s10', 'Pulau Pinang, jeti. Karung pinang bertimbun dan pokok penaga di tepi pantai. Seorang penjual cawan dari Kedah menunggu.', 10, 202, 'negeri_pulau_pinang.png'),
('e2_n2_s11', 'Pejabat daerah utara. Seorang pegawai daerah memerlukan dokumen yang betul sebelum petang. Salah satu fail mempunyai cop Zahar.', 11, 202, 'bilik_mesyuarat_formal.png'),
('e2_n2_s12', 'Anjung rumah. Radio lama berbunyi dan satu nota tertulis menyebut Aamiin-Aamiin.', 12, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s13', 'Terengganu, pantai berpasir selepas hujan. Zahar meninggalkan sehelai peta bertanda di sini.', 13, 202, 'negeri_terengganu.png'),
('e2_n2_s14', 'Bilik peta pantai timur dengan titik merah dan kuning. Kad ibu negeri bercampur di atas meja.', 14, 202, 'bilik_mesyuarat_modern.png'),
('e2_n2_s15', 'Bilik radio pantai timur. Jururadio bingung dengan dua kaset yang kelihatan serupa.', 15, 202, 'kampung_dan_pedalaman.png'),
('e2_n2_s16', 'Sarawak, tebing sungai. Sepucuk surat dari Sabah tiba bersama bot.', 16, 202, 'negeri_sarawak.png'),
('e2_n2_s17', 'Bilik mesyuarat, malam sebelum istiadat. Pegawai dua negeri Borneo menunggu di talian telefon. Dua kaset dan dua kad bercampur.', 17, 202, 'bilik_mesyuarat_dunia.png'),
('e2_n2_s18', 'Dewan Pesta Warisan Negara, Wilayah Persekutuan. Bendera berkibar, jata di dinding dan radio di atas meja. Zahar berdiri di tepi pentas dengan sampul.', 18, 202, 'wilayah_persekutuan.png'),
('e2_n3_s1', 'Sabah, kebun pisang di pantai barat. Pasport baharu masih kosong dan seorang penjaga cop menunggu di pondok.', 1, 203, 'negeri_sabah.png'),
('e2_n3_s2', 'Sarawak, tebing sungai. Penjaga cop menyerahkan satu surat dengan tulisan kabur.', 2, 203, 'negeri_sarawak.png'),
('e2_n3_s3', 'Bilik mesyuarat. Dua pegawai Borneo, satu dari Kuching dan satu dari Kota Kinabalu, menyerahkan kad ke tangan Pengembara.', 3, 203, 'bilik_mesyuarat.png'),
('e2_n3_s4', 'Wilayah Persekutuan. Seorang pemandu pelancong membantu Pengembara namun dokumennya bercampur.', 4, 203, 'wilayah_persekutuan.png'),
('e2_n3_s5', 'Bilik mesyuarat di Putrajaya. Penjaga cop Wilayah Persekutuan menyerahkan satu nota tersembunyi di bawah kad.', 5, 203, 'bilik_mesyuarat_modern.png'),
('e2_n3_s6', 'Johor, tepi selat. Peniaga permata dan pembaca naskhah berbalah di sebelah sehelai nota.', 6, 203, 'negeri_johor.png'),
('e2_n3_s7', 'Johor, balai penerangan. Peta menandakan titik merah dan kuning.', 7, 203, 'negeri_johor.png'),
('e2_n3_s8', 'Melaka, di bawah pokok tua dekat pelabuhan. Satu nota tersangkut di akar.', 8, 203, 'negeri_melaka.png'),
('e2_n3_s9', 'Bilik radio. Pegawai radio Melaka hilang kaset lagu negeri.', 9, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s10', 'Negeri Sembilan, balai penghulu dengan sembilan kerusi di dalam dewan.', 10, 203, 'negeri_sembilan.png'),
('e2_n3_s11', 'Negeri Sembilan, anjung istana lama. Peta menandakan titik merah dan kuning.', 11, 203, 'negeri_sembilan.png'),
('e2_n3_s12', 'Selangor, kuala sungai dengan pokok dan serangga. Tebing seberang berkait dengan Pahang.', 12, 203, 'negeri_selangor.png'),
('e2_n3_s13', 'Bilik mesyuarat. Dua peta, satu Selangor dan satu Pahang, dengan titik merah dan kuning.', 13, 203, 'bilik_mesyuarat_formal.png'),
('e2_n3_s14', 'Terengganu, pantai selepas hujan. Pelangi melengkung di atas Pulau Duyong. Pencerita Patani menunggu di tepi pantai.', 14, 203, 'negeri_terengganu.png'),
('e2_n3_s15', 'Anjung rumah. Radio berbunyi dan satu nota tersembunyi di bawah radio.', 15, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s16', 'Pulau Pinang, jeti dengan karung pinang. Pelombong dari Perak turun menjual bijih.', 16, 203, 'negeri_pulau_pinang.png'),
('e2_n3_s17', 'Pejabat daerah. Seorang pegawai daerah memerlukan dokumen yang betul bagi Perak dan Pulau Pinang.', 17, 203, 'bilik_mesyuarat.png'),
('e2_n3_s18', 'Kedah, pasar lama. Sawah di seberang menuju Perlis.', 18, 203, 'negeri_kedah.png'),
('e2_n3_s19', 'Bilik radio terakhir di utara. Dua kaset serupa menunggu di atas meja.', 19, 203, 'kampung_dan_pedalaman.png'),
('e2_n3_s20', 'Pentas Pesta Warisan Negara di Wilayah Persekutuan. Halaman terakhir pasport koyak. Bendera berkibar, jata terpampang dan radio berbunyi.', 20, 203, 'wilayah_persekutuan.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(201, 'e2_n1_s1', 'Catatan Pudar di Atas Pangkin', 'Baca catatan pudar itu dan tentukan maksud perkataan Siam yang dikaitkan dengan nama Perlis.', '5', 'Mengetahui asal nama Perlis: prow-lowy (kelapa hanyut) dan peristiwa Raja Syed Hussin Jamalullail.', '{"clueText": "Catatan lama: Nama Perlis dipercayai berasal daripada perkataan Siam, prow-lowy. Ia dikaitkan dengan sesuatu yang dilihat hanyut di air dan ditemui di parit.", "options": [{"text": "Kelapa hanyut", "isCorrect": true}, {"text": "Air jernih", "isCorrect": false, "consequence": "Papan kampung ditulis dengan maksud yang salah dan kanak-kanak menghafalnya."}, {"text": "Pokok tinggi", "isCorrect": false, "consequence": "Pesawah mencari pokok tinggi di sawah dan ketawakan catatan itu."}, {"text": "Sungai besar", "isCorrect": false, "consequence": "Pelawat bertanya di mana sungai besar itu dan pesawah tidak dapat menjawab."}], "aftermath": "Catatan tidak dapat dibaca dan pesawah menyimpulkan Tok tidak tahu apa-apa tentang negerinya.", "turns": [{"after": 6, "options": [{"text": "Dari ''peroleh'': mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.", "isCorrect": true, "reaction": "Pesawah tersenyum. Dua cerita itu akan ditulis bersebelahan."}, {"text": "Pada pendapat aku, tiada cerita lain, jadi tidak payah difikirkan panjang dan itu lebih senang.", "isCorrect": false, "reaction": "Pesawah menunjuk orang sebelah. Mereka berkeras ada cerita lain."}, {"text": "Perlis dari nama sungai, jadi cukup dibiarkan begitu sahaja dan lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Murid menyemak buku. Tiada catatan sungai."}], "clue": "Selain prow-lowy, ada cerita ''peroleh'' dan mandat Raja Syed Hussin."}]}'),
(202, 'e2_n1_s2', 'Tiga Nama, Tiga Bahasa', 'Padankan setiap nama Kedah dengan maksudnya.', '4', 'Memadankan Kheddah, Qadah dan Kadaram atau kalagam dengan maksud asal nama Kedah.', '{"pairs": [{"text": "Kheddah", "pair": 1}, {"text": "Perangkap gajah", "pair": 1}, {"text": "Qadah", "pair": 2}, {"text": "Cawan atau gelas berkaki yang dijual pedagang Arab", "pair": 2}, {"text": "Kadaram atau kalagam", "pair": 3}, {"text": "Nama Kedah dalam tulisan Tamil", "pair": 3}], "aftermath": "Padanan tersilap dan dua lelaki bertengkar lebih kuat kerana catatan mereka dipadankan dengan salah.", "turns": [{"after": 6, "options": [{"text": "Kadaram atau kalagam, kata tulisan Tamil itu.", "isCorrect": true, "reaction": "Pemandu gajah mengangguk. Tiga bahasa kini dicatat."}, {"text": "Pada pendapat aku, qadah, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Penjual cawan menggeleng. Itu nama Arab, bukan Tamil."}, {"text": "Kheddah, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pemandu gajah mengaku itu nama untuk perangkap, bukan tulisan Tamil."}], "clue": "Tulisan Tamil mencatat Kedah sebagai kadaram atau kalagam."}]}'),
(203, 'e2_n1_s3', 'Dua Negeri di Jeti', 'Padankan setiap nama atau sebab dengan negerinya.', '4', 'Memadankan Pulo Ka Satu, Tanjong Penaga, buah pinang, kilatan ikan dan bijih timah dengan Pulau Pinang atau Perak.', '{"pairs": [{"text": "Pulo Ka Satu", "pair": 1}, {"text": "Nama asal Pulau Pinang", "pair": 1}, {"text": "Tanjong Penaga", "pair": 2}, {"text": "Gelaran orang Melayu Kedah kerana banyak pokok penaga", "pair": 2}, {"text": "Buah pinang", "pair": 3}, {"text": "Bahan dagangan penting yang dikaitkan dengan Pulau Pinang", "pair": 3}, {"text": "Kilatan ikan di dalam air", "pair": 4}, {"text": "Nama Perak, berkilau seperti perak", "pair": 4}, {"text": "Bijih timah putih berkilat", "pair": 5}, {"text": "Pandangan lain tentang nama Perak", "pair": 5}], "aftermath": "Padanan tersilap dan nelayan menuduh Tok mencampuradukkan dua negeri.", "turns": [{"after": 6, "options": [{"text": "''Tak kenal maka tak cinta.''", "isCorrect": true, "reaction": "Nelayan tersenyum. Mengenali negeri menjadikan kita lebih sayang."}, {"text": "''Alah bisa tegal biasa.''", "isCorrect": false, "reaction": "Murid menggeleng. Peribahasa itu bukan tentang cinta negeri."}, {"text": "''Sediakan payung sebelum hujan.''", "isCorrect": false, "reaction": "Murid menggeleng. Itu bukan peribahasa buku ini."}], "clue": "Peribahasa dalam buku teks: Tak kenal maka tak cinta."}]}'),
(204, 'e2_n1_s4', 'Pusat dan Kota Warisan Utara', 'Padankan setiap ibu negeri dengan bandar dirajanya.', '4', 'Memadankan ibu negeri dan bandar diraja: Kangar dan Arau, Alor Setar dan Anak Bukit, Ipoh dan Kuala Kangsar, George Town dan tiada bandar diraja.', '{"pairs": [{"text": "Kangar (Perlis)", "pair": 1}, {"text": "Arau", "pair": 1}, {"text": "Alor Setar (Kedah)", "pair": 2}, {"text": "Anak Bukit", "pair": 2}, {"text": "Ipoh (Perak)", "pair": 3}, {"text": "Kuala Kangsar", "pair": 3}, {"text": "George Town (Pulau Pinang)", "pair": 4}, {"text": "Tiada bandar diraja ditanda pada peta", "pair": 4}], "aftermath": "Pegawai menegur dan murid ketawa kerana Tok menukar bandar diraja dengan ibu negeri.", "turns": [{"after": 7, "options": [{"text": "Bagi aku, memelihara dan memulihara serta menghargai warisan sejarah di situ.", "isCorrect": true, "reaction": "Pegawai mengangguk. Istana lama itu akan dijaga."}, {"text": "Bagi aku, meruntuhkan bangunan lama, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Warisan perlu dijaga."}, {"text": "Menurut aku, membiarkan sahaja, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Murid berkata warisan akan rosak jika dibiarkan."}], "clue": "Warisan sejarah perlu dipelihara dan dipulihara."}]}'),
(205, 'e2_n1_s5', 'Kaset Lagu Kedah', 'Bantu pegawai radio memilih kaset lagu negeri Kedah.', '3', 'Membantu NPC memilih kaset lagu negeri Kedah: Allah Selamatkan Sultan Mahkota.', '{"npcName": "Pegawai Radio", "prompt": "Majlis hampir bermula. Saya perlukan kaset lagu negeri Kedah. Yang mana satu?", "options": [{"text": "Allah Selamatkan Sultan Mahkota", "item": "kaset", "isCorrect": true}, {"text": "Aamiin-Aamiin", "item": "kaset", "isCorrect": false, "consequence": "Lagu Perlis dimainkan di hadapan tetamu Kedah dan mereka berpandangan."}, {"text": "Allah Lanjutkan Usia Sultan", "item": "kaset", "isCorrect": false, "consequence": "Lagu Perak bergema dan majlis Kedah tersasar."}, {"text": "Untuk Negeri Kita", "item": "kaset", "isCorrect": false, "consequence": "Lagu Pulau Pinang dimainkan dan tetamu Kedah menunduk malu."}], "aftermath": "Kaset yang salah dimainkan dan tetamu mula berbisik.", "turns": [{"after": 6, "options": [{"text": "Aamiin-Aamiin (Perlis), Allah Lanjutkan Usia Sultan (Perak), Untuk Negeri Kita (Pulau Pinang).", "isCorrect": true, "reaction": "Pegawai mengangguk dan mencatat semua tajuk di buku."}, {"text": "Semua sama, Allah Selamatkan Sultan, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Setiap negeri ada tajuk sendiri."}, {"text": "Sebenarnya, tiada lagu untuk tiga negeri itu, kerana tiada siapa yang akan peduli dan lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai menunjuk senarai lagu negeri dalam buku teks."}], "clue": "Setiap negeri ada lagu tersendiri."}]}'),
(206, 'e2_n1_s6', 'Kuala dan Luak', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan mentagau, selangur, nagari dan 1773.', '{"pairs": [{"text": "Mentagau", "pair": 1}, {"text": "Pokok di kuala sungai yang melahirkan ''kuala selangau''", "pair": 1}, {"text": "Selangur atau sangur", "pair": 2}, {"text": "Serangga yang banyak di sungai Selangor", "pair": 2}, {"text": "Nagari", "pair": 3}, {"text": "Wilayah dalam dialek Minangkabau", "pair": 3}, {"text": "1773", "pair": 4}, {"text": "Tahun sembilan luak asal Negeri Sembilan", "pair": 4}], "aftermath": "Penghulu dan nelayan menegur Tok kerana kekeliruan itu.", "turns": [{"after": 7, "options": [{"text": "Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.", "isCorrect": true, "reaction": "Penghulu mengangguk. Sembilan luak dicatat."}, {"text": "Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.", "isCorrect": false, "reaction": "Penghulu menggeleng. Itu negeri, bukan luak."}, {"text": "Sembilan pulau di Selat Melaka, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Penghulu ketawa. Itu bukan luak."}], "clue": "Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(207, 'e2_n1_s7', 'Dua Negeri di Pelabuhan', 'Padankan setiap nama atau cerita dengan negerinya.', '4', 'Memadankan Malakat, pokok Parameswara, Jauhar dan Ujong Tanah dengan Melaka atau Johor.', '{"pairs": [{"text": "Malakat", "pair": 1}, {"text": "Perhimpunan para pedagang (sumber Arab) bagi Melaka", "pair": 1}, {"text": "Pokok tempat Parameswara berehat", "pair": 2}, {"text": "Pelanduk putih menendang anjing, cerita Melaka", "pair": 2}, {"text": "Jauhar", "pair": 3}, {"text": "Perkataan Arab bagi batu permata bernilai, cerita Johor", "pair": 3}, {"text": "Ujong Tanah", "pair": 4}, {"text": "Nama Johor dalam Sulalatus Salatin", "pair": 4}], "aftermath": "Padanan tersilap dan pembaca naskhah menuduh Tok mengarang.", "turns": [{"after": 6, "options": [{"text": "Bahasa Arab. Malakat bermaksud perhimpunan para pedagang.", "isCorrect": true, "reaction": "Pembaca naskhah mengangguk. Catatan Arab itu dihormati."}, {"text": "Bahasa Tamil, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pembaca naskhah menggeleng. Tamil tiada kaitan dengan Malakat."}, {"text": "Bahasa Siam, jadi cukup dibiarkan begitu sahaja dan biarkan sahaja.", "isCorrect": false, "reaction": "Pembaca naskhah menggeleng. Siam berkait dengan Perlis."}], "clue": "Malakat ialah sebutan Arab."}]}'),
(208, 'e2_n1_s8', 'Pusat dan Istana Tengah', 'Padankan ibu negeri dengan bandar dirajanya.', '4', 'Memadankan Shah Alam-Klang, Seremban-Seri Menanti, Johor Bahru-Bandar Maharani dan Bandar Melaka dengan tiada bandar diraja.', '{"pairs": [{"text": "Shah Alam (Selangor)", "pair": 1}, {"text": "Klang", "pair": 1}, {"text": "Seremban (Negeri Sembilan)", "pair": 2}, {"text": "Seri Menanti", "pair": 2}, {"text": "Johor Bahru (Johor)", "pair": 3}, {"text": "Bandar Maharani", "pair": 3}, {"text": "Bandar Melaka (Melaka)", "pair": 4}, {"text": "Tiada bandar diraja ditanda pada peta", "pair": 4}], "aftermath": "Fail dikirim ke pejabat yang salah dan pegawai terpaksa menulis semula.", "turns": [{"after": 7, "options": [{"text": "Kerana pembangunan pentadbiran, kemudahan asas, institusi pendidikan dan tumpuan pekerjaan.", "isCorrect": true, "reaction": "Pegawai mengangguk dan mencatat empat sebab itu."}, {"text": "Menurut aku, kerana ia dekat dengan pantai dan tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}, {"text": "Bagi aku, kerana ia mempunyai istana dan tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Istana ada di bandar diraja."}], "clue": "Ibu negeri berkembang kerana pentadbiran, kemudahan, pendidikan dan pekerjaan."}]}'),
(209, 'e2_n1_s9', 'Kaset Lagu Johor', 'Bantu pegawai radio memilih kaset lagu negeri Johor.', '3', 'Membantu NPC memilih kaset lagu Johor: Lagu Bangsa Johor.', '{"npcName": "Pegawai Radio", "prompt": "Majlis Johor dua jam lagi. Kaset mana yang betul untuk lagu negeri Johor?", "options": [{"text": "Lagu Bangsa Johor", "item": "kaset", "isCorrect": true}, {"text": "Duli Yang Maha Mulia", "item": "kaset", "isCorrect": false, "consequence": "Lagu Selangor bergema dan Sultan Johor mengerutkan dahi."}, {"text": "Berkatlah Yang di-Pertuan Besar", "item": "kaset", "isCorrect": false, "consequence": "Lagu Negeri Sembilan dimainkan dan majlis tergendala."}, {"text": "Melaka Maju Jaya", "item": "kaset", "isCorrect": false, "consequence": "Lagu Melaka dimainkan dan tetamu Johor berbisik tidak puas hati."}], "aftermath": "Lagu negeri lain dimainkan dan majlis tergendala.", "turns": [{"after": 6, "options": [{"text": "Selangor, Negeri Sembilan dan Melaka.", "isCorrect": true, "reaction": "Pegawai mengangguk dan mencatat tiga tajuk itu."}, {"text": "Semuanya negeri Johor, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Setiap negeri ada lagu sendiri."}, {"text": "Perak, Kedah dan Perlis, kerana itu lebih senang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu lagu utara."}], "clue": "Duli Yang Maha Mulia, Berkatlah Yang di-Pertuan Besar dan Melaka Maju Jaya."}]}'),
(210, 'e2_n1_s10', 'Enam Cerita di Pantai', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan mahang, Inderapura, taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs": [{"text": "Mahang", "pair": 1}, {"text": "Pokok yang melahirkan nama Pahang", "pair": 1}, {"text": "Inderapura atau Pura", "pair": 2}, {"text": "Nama Pahang dalam Sulalatus Salatin; pura ialah bandar", "pair": 2}, {"text": "Taring anu", "pair": 3}, {"text": "Taring besar seperti gading gajah di Pulau Duyong", "pair": 3}, {"text": "Terangnya ganu", "pair": 4}, {"text": "Pelangi", "pair": 4}, {"text": "Kilatan", "pair": 5}, {"text": "Cahaya terang yang dilihat orang Melayu Patani", "pair": 5}, {"text": "Gelam hutan atau kelam hutan", "pair": 6}, {"text": "Pokok di pesisir pantai Kelantan", "pair": 6}], "aftermath": "Tiga kumpulan bertelagah lebih kuat apabila padanan tersilap.", "turns": [{"after": 7, "options": [{"text": "Masyarakat Melayu Patani.", "isCorrect": true, "reaction": "Pencerita mengangguk. Cerita Patani dihormati."}, {"text": "Orang Minangkabau.", "isCorrect": false, "reaction": "Pencerita menggeleng. Minangkabau berkait dengan nagari."}, {"text": "Pedagang Arab, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pencerita menggeleng. Arab berkait dengan Malakat dan Jauhar."}], "clue": "Kilatan dilihat oleh masyarakat Melayu Patani."}]}'),
(211, 'e2_n1_s11', 'Peta Pantai Timur', 'Padankan kad dengan ibu negeri atau bandar diraja yang betul.', '4', 'Memadankan ibu negeri Pahang Kuantan, bandar diraja Pahang Pekan, ibu negeri Terengganu Kuala Terengganu dan ibu negeri Kelantan Kota Bharu.', '{"pairs": [{"text": "Ibu negeri Pahang", "pair": 1}, {"text": "Kuantan", "pair": 1}, {"text": "Bandar diraja Pahang", "pair": 2}, {"text": "Pekan", "pair": 2}, {"text": "Ibu negeri Terengganu", "pair": 3}, {"text": "Kuala Terengganu", "pair": 3}, {"text": "Ibu negeri Kelantan", "pair": 4}, {"text": "Kota Bharu", "pair": 4}], "aftermath": "Surat jemputan ke Pekan dihantar ke Kuantan dan pegawai terpaksa menulis semula.", "turns": [{"after": 6, "options": [{"text": "Istana, bangunan pembesar, kedai lama, muzium dan monumen.", "isCorrect": true, "reaction": "Pegawai mengangguk dan mencatat senarai itu."}, {"text": "Sebenarnya, hanya pelabuhan, kerana ramai orang buat begitu.", "isCorrect": false, "reaction": "Pegawai menggeleng. Pelabuhan bukan ciri bandar diraja."}, {"text": "Hanya bangunan baharu, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Bandar diraja ada warisan sejarah."}], "clue": "Bandar diraja ada warisan sejarah."}]}'),
(212, 'e2_n1_s12', 'Dua Negeri Satu Tajuk', 'Nyahkod nota dan tentukan dua negeri yang berkongsi tajuk lagu ''Selamat Sultan''.', '5', 'Mengenal pasti Terengganu dan Kelantan sebagai dua negeri yang menggunakan tajuk lagu Selamat Sultan.', '{"clueText": "Nota: dua negeri di pantai timur menggunakan tajuk lagu yang sama, ''Selamat Sultan''. Satu lagi negeri di pantai timur, Pahang, mempunyai tajuk lagu yang lain.", "options": [{"text": "Terengganu dan Kelantan", "isCorrect": true}, {"text": "Pahang dan Terengganu", "isCorrect": false, "consequence": "Pahang mempunyai tajuk lagu lain, iaitu Allah Selamatkan Sultan Kami."}, {"text": "Pahang dan Kelantan", "isCorrect": false, "consequence": "Pahang mempunyai tajuk lagu lain, jadi nota itu tidak menyebutnya."}, {"text": "Kedah dan Perak", "isCorrect": false, "consequence": "Dua negeri itu di utara dan lagu mereka lain."}], "aftermath": "Dua orang tua berhujah semula dan Tok terpaksa menulis semula halaman itu.", "turns": [{"after": 6, "options": [{"text": "Allah Selamatkan Sultan Kami.", "isCorrect": true, "reaction": "Orang tua mengangguk. Tajuk Pahang dicatat."}, {"text": "Selamat Sultan.", "isCorrect": false, "reaction": "Orang tua menggeleng. Itu tajuk Terengganu dan Kelantan."}, {"text": "Allah Lanjutkan Usia Sultan.", "isCorrect": false, "reaction": "Orang tua menggeleng. Itu lagu Perak."}], "clue": "Pahang: Allah Selamatkan Sultan Kami."}]}'),
(213, 'e2_n1_s13', 'Dokumen Nama Borneo', 'Bantu ahli sejarah memilih dokumen yang betul tentang nama Sarawak dan Sabah.', '3', 'Membantu NPC memilih dokumen: Sungai Serak, cerava, pisang saba dan Maharajah of Sabah 1877.', '{"npcName": "Ahli Sejarah", "prompt": "Yang mana dokumen yang betul tentang nama Sarawak dan Sabah?", "options": [{"text": "Sungai Serak dan cerava (Sarawak); pisang saba dan Maharajah of Sabah 1877 (Sabah)", "item": "dokumen", "isCorrect": true}, {"text": "Sungai Serak dan cerava (Sarawak); pisang saba dan Maharajah of Sabah 1773 (Sabah)", "item": "dokumen", "isCorrect": false, "consequence": "Tahun 1773 ialah tahun luak Negeri Sembilan, bukan dokumen Sabah."}, {"text": "Pulo Ka Satu (Sarawak); pisang saba (Sabah)", "item": "dokumen", "isCorrect": false, "consequence": "Pulo Ka Satu ialah nama asal Pulau Pinang."}, {"text": "Sungai Serak (Sabah); pisang saba (Sarawak)", "item": "dokumen", "isCorrect": false, "consequence": "Nama negeri bertukar dan ahli sejarah menggeleng."}], "aftermath": "Dokumen yang salah dipilih dan ahli sejarah tersilap menerangkan nama kepada pelawat.", "turns": [{"after": 6, "options": [{"text": "1877, tahun dokumen ''Maharajah of Sabah''.", "isCorrect": true, "reaction": "Ahli sejarah mencatat tahun itu."}, {"text": "1773, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Ahli sejarah menggeleng. 1773 ialah tahun luak Negeri Sembilan."}, {"text": "1887, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Ahli sejarah menggeleng. 1887 bukan tahun dokumen Sabah."}], "clue": "Dokumen Maharajah of Sabah ialah pada tahun 1877."}]}'),
(214, 'e2_n1_s14', 'Tiga Wilayah, Tiga Nama', 'Padankan setiap wilayah dengan asal namanya.', '4', 'Memadankan Kuala Lumpur, Labuan dan Putrajaya dengan asal nama masing-masing.', '{"pairs": [{"text": "Kuala Lumpur", "pair": 1}, {"text": "Muara berlumpur akibat melombong bijih timah", "pair": 1}, {"text": "Labuan", "pair": 2}, {"text": "Labuhan, tempat persinggahan kapal", "pair": 2}, {"text": "Putrajaya", "pair": 3}, {"text": "Tunku Abdul Rahman Putra; jaya bermaksud kemenangan atau menuju ke puncak", "pair": 3}], "aftermath": "Pelawat menyangka Putrajaya bersempena nama orang lain.", "turns": [{"after": 6, "options": [{"text": "Tunku Abdul Rahman Putra, dan jaya bermaksud kemenangan atau menuju ke puncak.", "isCorrect": true, "reaction": "Pelawat mengangguk. Putrajaya dihormati namanya."}, {"text": "Tun Abdul Razak, kerana tiada siapa yang akan peduli dan itu lebih senang.", "isCorrect": false, "reaction": "Pelawat menggeleng. Nama itu tidak disebut dalam buku."}, {"text": "Tun Mahathir, jadi cukup dibiarkan begitu sahaja dan orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Pelawat menggeleng. Nama itu tidak disebut dalam buku."}], "clue": "Putrajaya bersempena Tunku Abdul Rahman Putra."}]}'),
(215, 'e2_n1_s15', 'Pusat Pentadbiran Borneo', 'Padankan setiap negeri dengan ibu negerinya dan sebab ibu negeri berkembang.', '4', 'Memadankan Kuching, Kota Kinabalu dan sebab ibu negeri berkembang.', '{"pairs": [{"text": "Ibu negeri Sarawak", "pair": 1}, {"text": "Kuching", "pair": 1}, {"text": "Ibu negeri Sabah", "pair": 2}, {"text": "Kota Kinabalu", "pair": 2}, {"text": "Ibu negeri berkembang kerana", "pair": 3}, {"text": "Pembangunan pentadbiran, kemudahan asas dan institusi pendidikan", "pair": 3}, {"text": "Ibu negeri menjadi tempat tumpuan", "pair": 4}, {"text": "Pekerjaan", "pair": 4}], "aftermath": "Dua pegawai bertukar fail dan murid keliru.", "turns": [{"after": 7, "options": [{"text": "Memelihara dan memulihara warisan sejarah di situ.", "isCorrect": true, "reaction": "Pegawai mengangguk dan berjanji menjaga istana lama."}, {"text": "Menurut aku, membiarkan sahaja, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Warisan akan rosak."}, {"text": "Rasanya, menggantikannya dengan bangunan baharu.", "isCorrect": false, "reaction": "Pegawai menggeleng. Warisan sejarah perlu dipelihara."}], "clue": "Warisan sejarah dipelihara dan dipulihara."}]}'),
(216, 'e2_n1_s16', 'Kaset Lagu Sabah', 'Bantu pegawai radio memilih kaset lagu negeri Sabah.', '3', 'Membantu NPC memilih kaset lagu Sabah: Sabah Tanah Airku.', '{"npcName": "Pegawai Radio", "prompt": "Lagu Sabah akan dimainkan sekejap lagi. Yang mana kaset yang betul?", "options": [{"text": "Sabah Tanah Airku", "item": "kaset", "isCorrect": true}, {"text": "Ibu Pertiwiku", "item": "kaset", "isCorrect": false, "consequence": "Lagu Sarawak dimainkan di hadapan tetamu Sabah dan mereka berpandangan."}, {"text": "Maju dan Sejahtera", "item": "kaset", "isCorrect": false, "consequence": "Lagu Wilayah Persekutuan dimainkan dan majlis Sabah tersasar."}, {"text": "Melaka Maju Jaya", "item": "kaset", "isCorrect": false, "consequence": "Lagu Melaka dimainkan dan tetamu Sabah menunduk malu."}], "aftermath": "Kaset yang salah dimainkan dan tetamu Sabah tersinggung.", "turns": [{"after": 7, "options": [{"text": "Ibu Pertiwiku milik Sarawak, dan Maju dan Sejahtera milik Wilayah Persekutuan.", "isCorrect": true, "reaction": "Pegawai mengangguk dan mencatat semua tajuk."}, {"text": "Kedua-duanya milik Sabah, kerana tiada siapa yang akan peduli dan lupakan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Sabah hanya ada satu lagu negeri."}, {"text": "Kedua-duanya milik Sarawak, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Maju dan Sejahtera milik Wilayah Persekutuan."}], "clue": "Ibu Pertiwiku ialah Sarawak. Maju dan Sejahtera ialah Wilayah Persekutuan."}]}'),
(217, 'e2_n1_s17', 'Kad Gelaran Ketua Negeri', 'Padankan gelaran dengan negeri yang menggunakannya.', '4', 'Memadankan Raja, Sultan, Yang di-Pertuan Besar dan Yang di-Pertua Negeri dengan negeri masing-masing.', '{"pairs": [{"text": "Raja", "pair": 1}, {"text": "Perlis", "pair": 1}, {"text": "Sultan", "pair": 2}, {"text": "Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan", "pair": 2}, {"text": "Yang di-Pertuan Besar", "pair": 3}, {"text": "Negeri Sembilan", "pair": 3}, {"text": "Yang di-Pertua Negeri", "pair": 4}, {"text": "Pulau Pinang, Melaka, Sarawak dan Sabah", "pair": 4}], "aftermath": "Kad dipasang salah dan tetamu berasa tersinggung.", "turns": [{"after": 7, "options": [{"text": "Sikap menghormati dan taat setia kepada raja dapat dipupuk dengan mengenali ketua negeri. Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Pegawai mengangguk. Semua tetamu dihormati."}, {"text": "Aku fikir supaya kita dapat mengundi mereka dan tidak payah difikirkan panjang dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}, {"text": "Rasanya, supaya kita dapat bergelar Sultan dan tiada siapa yang akan peduli dan kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Pegawai menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}], "clue": "Kenali ketua negeri untuk memupuk hormat dan taat setia."}]}'),
(218, 'e2_n1_s18', 'Lambang di Pentas Pesta', 'Cari tiga lambang negeri di pentas, iaitu jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan negeri.', '{"bgImage": "../assets/gameAsset/background/wilayah_persekutuan.png", "hotspots": [{"name": "Jata: lambang kedaulatan negeri", "top": "40.4%", "left": "70%"}, {"name": "Bendera: lambang identiti negeri", "top": "20.9%", "left": "72.7%"}, {"name": "Radio: lagu Maju dan Sejahtera", "top": "86.4%", "left": "74.1%"}], "aftermath": "Lambang tidak ditemui dan penonton bertanya adakah Tok benar-benar mengenali negeri.", "turns": [{"after": 6, "options": [{"text": "Kerana bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri.", "isCorrect": true, "reaction": "Penonton bertepuk tangan. Buku ditutup dengan bangga."}, {"text": "Kerana ia hiasan sahaja, kerana tiada siapa yang akan peduli dan itu lebih senang.", "isCorrect": false, "reaction": "Penonton menggeleng. Lambang ialah identiti negeri."}, {"text": "Supaya negeri lain takut, jadi cukup dibiarkan begitu sahaja dan lupakan sahaja.", "isCorrect": false, "reaction": "Penonton menggeleng. Ia bukan untuk menakutkan."}], "clue": "Lambang negeri ialah identiti dan kemegahan."}]}'),
(219, 'e2_n2_s1', 'Nota Sisa dalam Fail', 'Nyahkod nota fail dan tentukan ketua Wilayah Persekutuan.', '5', 'Mengenal pasti ketua Wilayah Persekutuan: Yang di-Pertuan Agong.', '{"clueText": "Nota fail: Wilayah Persekutuan terdiri daripada Kuala Lumpur, Labuan dan Putrajaya. Ketuanya bukan sultan, bukan raja.", "options": [{"text": "Yang di-Pertuan Agong", "isCorrect": true}, {"text": "Sultan", "isCorrect": false, "consequence": "Kad dipasang salah dan Encik Zahar tersenyum."}, {"text": "Yang di-Pertua Negeri", "isCorrect": false, "consequence": "Kad dipasang salah dan Encik Zahar tersenyum."}, {"text": "Yang di-Pertuan Besar", "isCorrect": false, "consequence": "Kad dipasang salah dan Encik Zahar tersenyum."}], "aftermath": "Kad ketua dipasang salah dan Encik Zahar tersenyum puas.", "turns": [{"after": 7, "options": [{"text": "Tiada. Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja.", "isCorrect": true, "reaction": "Encik Zahar terdiam. Jawapan itu tepat."}, {"text": "Bagi aku, putrajaya ialah ibu negeri, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Encik Zahar tersenyum. Wilayah Persekutuan tiada ibu negeri."}, {"text": "Kuala Lumpur ialah bandar diraja, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Tok berbisik, itu salah. Tiada bandar diraja di sana."}], "clue": "Wilayah Persekutuan tiada ibu negeri dan bandar diraja."}]}'),
(220, 'e2_n2_s2', 'Tiga Papan Nama', 'Padankan setiap wilayah dengan asal namanya.', '4', 'Memadankan Kuala Lumpur, Labuan dan Putrajaya dengan asal nama masing-masing.', '{"pairs": [{"text": "Kuala Lumpur", "pair": 1}, {"text": "Muara berlumpur akibat melombong bijih timah", "pair": 1}, {"text": "Labuan", "pair": 2}, {"text": "Labuhan, tempat persinggahan kapal", "pair": 2}, {"text": "Putrajaya", "pair": 3}, {"text": "Tunku Abdul Rahman Putra; jaya bermaksud kemenangan atau menuju ke puncak", "pair": 3}], "aftermath": "Tetamu bertanya kenapa istiadat salah menyebut nama.", "turns": [{"after": 7, "options": [{"text": "Ya, bersempena Tunku Abdul Rahman Putra.", "isCorrect": true, "reaction": "Juruteknik mengangguk dan memasang papan itu."}, {"text": "Sebenarnya, tidak, ia nama sebuah sungai.", "isCorrect": false, "reaction": "Juruteknik menggeleng. Nama itu bukan sungai."}, {"text": "Tidak, ia nama sebuah pulau.", "isCorrect": false, "reaction": "Juruteknik menggeleng. Nama itu bukan pulau."}], "clue": "Putrajaya bersempena Tunku Abdul Rahman Putra."}]}'),
(221, 'e2_n2_s3', 'Kad Gelaran Ketua Negeri', 'Padankan gelaran dengan negeri yang menggunakannya.', '4', 'Memadankan Raja, Sultan, Yang di-Pertuan Besar dan Yang di-Pertua Negeri dengan negeri masing-masing.', '{"pairs": [{"text": "Raja", "pair": 1}, {"text": "Perlis", "pair": 1}, {"text": "Sultan", "pair": 2}, {"text": "Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan", "pair": 2}, {"text": "Yang di-Pertuan Besar", "pair": 3}, {"text": "Negeri Sembilan", "pair": 3}, {"text": "Yang di-Pertua Negeri", "pair": 4}, {"text": "Pulau Pinang, Melaka, Sarawak dan Sabah", "pair": 4}], "aftermath": "Encik Zahar mengambil kad itu dan menyusunnya dengan salah.", "turns": [{"after": 6, "options": [{"text": "Menurut aku, ia menunjukkan keunikan negara dan menanam sikap hormat serta taat setia kepada raja.", "isCorrect": true, "reaction": "Encik Zahar terdiam dan menarik tangannya."}, {"text": "Rasanya, supaya kad nampak cantik dan tiada siapa yang akan peduli dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tok menggeleng. Gelaran bukan hiasan."}, {"text": "Supaya semua ketua sama gelaran, jadi cukup dibiarkan begitu sahaja dan itu bukan urusan kita.", "isCorrect": false, "reaction": "Tok menggeleng. Gelaran berbeza menunjukkan keunikan."}], "clue": "Gelaran berbeza menanam hormat dan taat setia kepada raja."}]}'),
(222, 'e2_n2_s4', 'Dokumen Yang di-Pertua Negeri', 'Bantu pembantu memilih dokumen negeri yang menggunakan gelaran Yang di-Pertua Negeri.', '3', 'Membantu NPC memilih dokumen: Pulau Pinang, Melaka, Sarawak dan Sabah.', '{"npcName": "Pembantu Yang di-Pertua Negeri", "prompt": "Dokumen mana yang menyenaraikan negeri bergelar Yang di-Pertua Negeri?", "options": [{"text": "Pulau Pinang, Melaka, Sarawak dan Sabah", "item": "dokumen", "isCorrect": true}, {"text": "Pulau Pinang, Melaka dan Perlis", "item": "dokumen", "isCorrect": false, "consequence": "Perlis bergelar Raja, jadi tuan dibawa ke majlis yang salah."}, {"text": "Sabah, Sarawak dan Johor", "item": "dokumen", "isCorrect": false, "consequence": "Johor bergelar Sultan, jadi tuan dibawa ke majlis yang salah."}, {"text": "Negeri Sembilan, Pahang dan Sabah", "item": "dokumen", "isCorrect": false, "consequence": "Negeri Sembilan bergelar Yang di-Pertuan Besar dan Pahang Sultan."}], "aftermath": "Pembantu membawa tuannya ke majlis yang salah.", "turns": [{"after": 7, "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Pembantu mengangguk dan mencatat jawapan itu."}, {"text": "Sultan Selangor.", "isCorrect": false, "reaction": "Pembantu menggeleng. Ketua Wilayah Persekutuan bukan sultan negeri."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Pembantu menggeleng. Gelaran itu untuk empat negeri sahaja."}], "clue": "Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong."}]}'),
(223, 'e2_n2_s5', 'Piagam Sembilan Luak', 'Nyahkod piagam dan tentukan tahun sembilan luak asal Negeri Sembilan.', '5', 'Mengenal pasti tahun 1773 bagi sembilan luak asal Negeri Sembilan.', '{"clueText": "Piagam: Negeri Sembilan bermula daripada sembilan luak. Nagari bermaksud wilayah dalam dialek Minangkabau. Tahun piagam ini ialah tahun gabungan itu dicatat.", "options": [{"text": "1773", "isCorrect": true}, {"text": "1877", "isCorrect": false, "consequence": "Itu tahun dokumen Sabah, bukan Negeri Sembilan."}, {"text": "1887", "isCorrect": false, "consequence": "Tahun itu tiada dalam piagam Negeri Sembilan."}, {"text": "1673", "isCorrect": false, "consequence": "Tarikh itu terlalu awal dan penghulu menggeleng."}], "aftermath": "Penghulu menegur Pegawai kerana kad pengacara tersilap.", "turns": [{"after": 6, "options": [{"text": "Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.", "isCorrect": true, "reaction": "Penghulu mengangguk. Sembilan luak dicatat."}, {"text": "Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.", "isCorrect": false, "reaction": "Penghulu menggeleng. Itu negeri, bukan luak."}, {"text": "Sembilan pulau di Selat Melaka, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Penghulu ketawa. Itu bukan luak."}], "clue": "Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(224, 'e2_n2_s6', 'Nota di Akar Pokok', 'Nyahkod nota dan tentukan nama Johor dalam Sulalatus Salatin.', '5', 'Mengenal pasti Ujong Tanah sebagai nama Johor dalam Sulalatus Salatin.', '{"clueText": "Nota: Dalam naskhah Sulalatus Salatin, Johor disebut dengan nama hujung sebuah daratan.", "options": [{"text": "Ujong Tanah", "isCorrect": true}, {"text": "Inderapura", "isCorrect": false, "consequence": "Itu nama Pahang dalam naskhah yang sama."}, {"text": "Malakat", "isCorrect": false, "consequence": "Itu perhimpunan pedagang bagi Melaka."}, {"text": "Kadaram", "isCorrect": false, "consequence": "Itu nama Kedah dalam tulisan Tamil."}], "aftermath": "Encik Zahar mengubah nota supaya nama Johor tersalah.", "turns": [{"after": 7, "options": [{"text": "Perkataan Arab ''Jauhar'' bermaksud batu permata bernilai, cerita kedua Johor. Malakat pula perhimpunan pedagang.", "isCorrect": true, "reaction": "Peniaga mengangguk. Dua negeri dicatat."}, {"text": "Pada pendapat aku, jauhar ialah nama pokok di Melaka, kerana tiada siapa yang akan peduli dan lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Peniaga menggeleng. Jauhar ialah batu permata."}, {"text": "Jauhar ialah nama sungai di Johor, jadi cukup dibiarkan begitu sahaja dan tidak perlu dipedulikan lagi.", "isCorrect": false, "reaction": "Peniaga menggeleng. Jauhar ialah batu permata."}], "clue": "Jauhar bermaksud batu permata. Malakat perhimpunan pedagang."}]}'),
(225, 'e2_n2_s7', 'Fail yang Dicuri', 'Padankan ibu negeri dengan bandar dirajanya.', '4', 'Memadankan Shah Alam-Klang, Seremban-Seri Menanti, Johor Bahru-Bandar Maharani dan Bandar Melaka dengan tiada bandar diraja.', '{"pairs": [{"text": "Shah Alam (Selangor)", "pair": 1}, {"text": "Klang", "pair": 1}, {"text": "Seremban (Negeri Sembilan)", "pair": 2}, {"text": "Seri Menanti", "pair": 2}, {"text": "Johor Bahru (Johor)", "pair": 3}, {"text": "Bandar Maharani", "pair": 3}, {"text": "Bandar Melaka (Melaka)", "pair": 4}, {"text": "Tiada bandar diraja ditanda pada peta", "pair": 4}], "aftermath": "Surat jemputan dihantar ke bandar yang salah.", "turns": [{"after": 7, "options": [{"text": "Kerana pembangunan pentadbiran, kemudahan asas, institusi pendidikan dan tumpuan pekerjaan.", "isCorrect": true, "reaction": "Setiausaha mengangguk dan mencatat empat sebab itu."}, {"text": "Menurut aku, kerana ia dekat dengan pantai dan tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Setiausaha menggeleng. Hmm, bukan begitu. Fikir semula, ya."}, {"text": "Bagi aku, kerana ia mempunyai istana dan tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Setiausaha menggeleng. Istana ada di bandar diraja."}], "clue": "Ibu negeri berkembang kerana pentadbiran, kemudahan, pendidikan dan pekerjaan."}]}'),
(226, 'e2_n2_s8', 'Empat Kaset Tanpa Label', 'Padankan setiap lagu dengan negerinya.', '4', 'Memadankan Duli Yang Maha Mulia, Berkatlah Yang di-Pertuan Besar, Melaka Maju Jaya dan Lagu Bangsa Johor.', '{"pairs": [{"text": "Duli Yang Maha Mulia", "pair": 1}, {"text": "Selangor", "pair": 1}, {"text": "Berkatlah Yang di-Pertuan Besar", "pair": 2}, {"text": "Negeri Sembilan", "pair": 2}, {"text": "Melaka Maju Jaya", "pair": 3}, {"text": "Melaka", "pair": 3}, {"text": "Lagu Bangsa Johor", "pair": 4}, {"text": "Johor", "pair": 4}], "aftermath": "Lagu yang salah dimainkan dan tetamu menunduk malu.", "turns": [{"after": 7, "options": [{"text": "Ia lambang kemegahan dan kedaulatan negeri.", "isCorrect": true, "reaction": "Jururadio mengangguk dan menyusun kaset itu."}, {"text": "Bagi aku, ia hanya hiburan, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Jururadio menggeleng. Lagu negeri lambang kedaulatan."}, {"text": "Pada pendapat aku, ia untuk mengiklankan negeri.", "isCorrect": false, "reaction": "Jururadio menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}], "clue": "Lagu negeri ialah lambang kemegahan dan kedaulatan."}]}'),
(227, 'e2_n2_s9', 'Empat Kad di Peti Pos', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan prow-lowy, peroleh, kilatan ikan dan bijih timah putih dengan Perlis atau Perak.', '{"pairs": [{"text": "Prow-lowy", "pair": 1}, {"text": "Kelapa hanyut (Perlis)", "pair": 1}, {"text": "Peroleh", "pair": 2}, {"text": "Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail", "pair": 2}, {"text": "Kilatan ikan", "pair": 3}, {"text": "Ikan berkilau seperti perak (Perak)", "pair": 3}, {"text": "Bijih timah putih berkilat", "pair": 4}, {"text": "Pandangan lain tentang nama Perak", "pair": 4}], "aftermath": "Pesawah dan pelombong menegur kekeliruan Pegawai.", "turns": [{"after": 7, "options": [{"text": "Aku fikir yang menerima mandat kerana membantu Perlis menentang Siam.", "isCorrect": true, "reaction": "Pesawah mengangguk dan tersenyum."}, {"text": "Seorang pedagang Arab di Perlis, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pesawah menggeleng. Dia pembesar yang menerima mandat."}, {"text": "Seorang pelombong di Perak, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pesawah menggeleng. Dia berkait dengan Perlis."}], "clue": "Raja Syed Hussin menerima mandat kerana membantu Perlis menentang Siam."}]}'),
(228, 'e2_n2_s10', 'Nama di Jeti', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan Pulo Ka Satu, Tanjong Penaga, pinang, qadah dan kadaram.', '{"pairs": [{"text": "Pulo Ka Satu", "pair": 1}, {"text": "Nama asal Pulau Pinang", "pair": 1}, {"text": "Tanjong Penaga", "pair": 2}, {"text": "Gelaran orang Melayu Kedah kerana banyak pokok penaga", "pair": 2}, {"text": "Buah pinang", "pair": 3}, {"text": "Bahan dagangan penting yang dikaitkan dengan Pulau Pinang", "pair": 3}, {"text": "Qadah", "pair": 4}, {"text": "Cawan atau gelas berkaki yang dijual pedagang Arab", "pair": 4}, {"text": "Kadaram", "pair": 5}, {"text": "Nama Kedah dalam tulisan Tamil", "pair": 5}], "aftermath": "Sampul tidak ditemui dan Zahar berpeluang menukar dokumen.", "turns": [{"after": 7, "options": [{"text": "Rasanya, buah pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang.", "isCorrect": true, "reaction": "Nelayan mengangguk dan menunjuk karung pinang."}, {"text": "Pada pendapat aku, kerana pulau itu berbentuk pinang dan orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Nelayan menggeleng. Hmm, bukan begitu. Fikir semula, ya."}, {"text": "Kerana pinang ditanam di Kedah sahaja, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Nelayan menggeleng. Pinang barang dagangan di sini."}], "clue": "Pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang."}]}'),
(229, 'e2_n2_s11', 'Dokumen Ibu Negeri Utara', 'Bantu pegawai daerah memilih dokumen ibu negeri dan bandar diraja yang betul.', '3', 'Membantu NPC memilih dokumen: Kangar-Arau, Alor Setar-Anak Bukit, Ipoh-Kuala Kangsar, George Town.', '{"npcName": "Pegawai Daerah", "prompt": "Dokumen mana yang betul untuk Perlis, Kedah, Perak dan Pulau Pinang?", "options": [{"text": "Kangar dan Arau; Alor Setar dan Anak Bukit; Ipoh dan Kuala Kangsar; George Town", "item": "dokumen", "isCorrect": true}, {"text": "Arau ibu negeri Perlis; Kangar bandar diraja", "item": "dokumen", "isCorrect": false, "consequence": "Jemputan dihantar ke Arau dan Kangar ditinggalkan."}, {"text": "Anak Bukit ibu negeri Kedah; Alor Setar bandar diraja", "item": "dokumen", "isCorrect": false, "consequence": "Jemputan dihantar ke bandar yang salah."}, {"text": "Kuala Kangsar ibu negeri Perak; Ipoh bandar diraja", "item": "dokumen", "isCorrect": false, "consequence": "Jemputan Perak sampai ke tempat yang salah."}], "aftermath": "Jemputan dihantar ke bandar yang salah.", "turns": [{"after": 7, "options": [{"text": "Rasanya, ia menyimpan warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.", "isCorrect": true, "reaction": "Pegawai Daerah mengangguk dan menyimpan fail itu."}, {"text": "Rasanya, ia tempat membuat jemputan, jadi tidak payah difikirkan panjang dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pegawai Daerah menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}, {"text": "Bagi aku, ia hanya untuk pelancong, kerana tiada siapa yang akan peduli dan orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Pegawai Daerah menggeleng. Ia menyimpan warisan sejarah."}], "clue": "Bandar diraja menyimpan warisan sejarah."}]}'),
(230, 'e2_n2_s12', 'Nota Aamiin-Aamiin', 'Nyahkod nota dan tentukan negeri pemilik lagu Aamiin-Aamiin.', '5', 'Mengenal pasti Perlis sebagai pemilik lagu Aamiin-Aamiin.', '{"clueText": "Nota: Lagu Aamiin-Aamiin dimainkan apabila Raja negeri ini hadir.", "options": [{"text": "Perlis", "isCorrect": true}, {"text": "Perak", "isCorrect": false, "consequence": "Perak bergelar Sultan, bukan Raja."}, {"text": "Kedah", "isCorrect": false, "consequence": "Kedah bergelar Sultan, bukan Raja."}, {"text": "Pulau Pinang", "isCorrect": false, "consequence": "Pulau Pinang bergelar Yang di-Pertua Negeri."}], "aftermath": "Raja Perlis tidak disambut dengan lagu negerinya.", "turns": [{"after": 6, "options": [{"text": "Allah Lanjutkan Usia Sultan (Perak), Allah Selamatkan Sultan Mahkota (Kedah) dan Untuk Negeri Kita (Pulau Pinang).", "isCorrect": true, "reaction": "Jururadio mengangguk dan mencatat semua tajuk."}, {"text": "Semua bertajuk Aamiin-Aamiin, jadi tidak payah difikirkan panjang dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Jururadio menggeleng. Setiap negeri ada tajuk sendiri."}, {"text": "Sebenarnya, tiada lagu untuk tiga negeri itu, kerana tiada siapa yang akan peduli dan lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Jururadio menunjuk senarai lagu negeri dalam buku teks."}], "clue": "Perak, Kedah dan Pulau Pinang masing-masing ada lagu tersendiri."}]}'),
(231, 'e2_n2_s13', 'Enam Cerita Pantai Timur', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan mahang, Inderapura, taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs": [{"text": "Mahang", "pair": 1}, {"text": "Pokok yang melahirkan nama Pahang", "pair": 1}, {"text": "Inderapura atau Pura", "pair": 2}, {"text": "Nama Pahang dalam Sulalatus Salatin; pura ialah bandar", "pair": 2}, {"text": "Taring anu", "pair": 3}, {"text": "Taring besar seperti gading gajah di Pulau Duyong", "pair": 3}, {"text": "Terangnya ganu", "pair": 4}, {"text": "Pelangi", "pair": 4}, {"text": "Kilatan", "pair": 5}, {"text": "Cahaya terang yang dilihat orang Melayu Patani", "pair": 5}, {"text": "Gelam hutan atau kelam hutan", "pair": 6}, {"text": "Pokok di pesisir pantai Kelantan", "pair": 6}], "aftermath": "Peta Zahar tidak ditemui dan Pegawai tersilap nama di hadapan penduduk.", "turns": [{"after": 7, "options": [{"text": "Masyarakat Melayu Patani.", "isCorrect": true, "reaction": "Pencerita mengangguk. Cerita Patani dicatat."}, {"text": "Orang Minangkabau.", "isCorrect": false, "reaction": "Pencerita menggeleng. Minangkabau berkait dengan nagari."}, {"text": "Pedagang Arab, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Pencerita menggeleng. Arab berkait dengan Malakat dan Jauhar."}], "clue": "Kilatan dilihat oleh masyarakat Melayu Patani."}]}'),
(232, 'e2_n2_s14', 'Kad Bilik Peta', 'Padankan kad dengan ibu negeri atau bandar diraja yang betul.', '4', 'Memadankan ibu negeri Pahang Kuantan, bandar diraja Pahang Pekan, ibu negeri Terengganu Kuala Terengganu dan ibu negeri Kelantan Kota Bharu.', '{"pairs": [{"text": "Ibu negeri Pahang", "pair": 1}, {"text": "Kuantan", "pair": 1}, {"text": "Bandar diraja Pahang", "pair": 2}, {"text": "Pekan", "pair": 2}, {"text": "Ibu negeri Terengganu", "pair": 3}, {"text": "Kuala Terengganu", "pair": 3}, {"text": "Ibu negeri Kelantan", "pair": 4}, {"text": "Kota Bharu", "pair": 4}], "aftermath": "Surat jemputan istiadat ke Pekan dihantar ke Kuantan.", "turns": [{"after": 6, "options": [{"text": "Bagi aku, memelihara dan memulihara serta menghargai warisan sejarah di situ.", "isCorrect": true, "reaction": "Pegawai mengangguk dan berjanji menjaga istana lama."}, {"text": "Bagi aku, meruntuhkan bangunan lama, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Warisan perlu dijaga."}, {"text": "Menurut aku, membiarkan sahaja, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Warisan akan rosak jika dibiarkan."}], "clue": "Warisan sejarah perlu dipelihara dan dipulihara."}]}'),
(233, 'e2_n2_s15', 'Kaset Lagu Pahang', 'Bantu jururadio memilih kaset lagu negeri Pahang.', '3', 'Membantu NPC memilih kaset lagu Pahang: Allah Selamatkan Sultan Kami.', '{"npcName": "Jururadio", "prompt": "Kaset mana ialah lagu negeri Pahang?", "options": [{"text": "Allah Selamatkan Sultan Kami", "item": "kaset", "isCorrect": true}, {"text": "Sabah Tanah Airku", "item": "kaset", "isCorrect": false, "consequence": "Lagu Sabah dimainkan di hadapan Sultan Pahang."}, {"text": "Allah Lanjutkan Usia Sultan", "item": "kaset", "isCorrect": false, "consequence": "Lagu Perak dimainkan di hadapan Sultan Pahang."}, {"text": "Melaka Maju Jaya", "item": "kaset", "isCorrect": false, "consequence": "Lagu Melaka dimainkan di hadapan Sultan Pahang."}], "aftermath": "Lagu negeri lain dimainkan di hadapan Sultan Pahang.", "turns": [{"after": 7, "options": [{"text": "Lagu Terengganu dan lagu Kelantan, dua negeri berkongsi tajuk yang sama.", "isCorrect": true, "reaction": "Jururadio mengangguk dan mencatat dua negeri itu."}, {"text": "Lagu Pahang dan Perak, kerana tiada siapa yang akan peduli dan biarkan sahaja.", "isCorrect": false, "reaction": "Jururadio menggeleng. Tajuk itu bukan milik mereka."}, {"text": "Lagu Sabah dan Sarawak, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Jururadio menggeleng. Tajuk itu dikongsi dua negeri pantai timur."}], "clue": "Selamat Sultan ialah lagu Terengganu dan Kelantan."}]}'),
(234, 'e2_n2_s16', 'Surat dari Sabah', 'Nyahkod surat dan tentukan tahun dokumen Maharajah of Sabah serta buah yang dikaitkan dengan Sabah.', '5', 'Mengenal pasti 1877 dan pisang saba.', '{"clueText": "Surat: Nama Sabah tercatat dalam dokumen sejarah bertajuk Maharajah of Sabah pada tahun ini, dan dikaitkan dengan sejenis buah yang ditanam di pantai barat.", "options": [{"text": "1877 dan pisang saba", "isCorrect": true}, {"text": "1773 dan mahang", "isCorrect": false, "consequence": "1773 ialah tahun luak Negeri Sembilan dan mahang berkait dengan Pahang."}, {"text": "1887 dan penaga", "isCorrect": false, "consequence": "Tahun itu tiada dalam dokumen dan penaga berkait dengan Pulau Pinang."}, {"text": "1877 dan pinang", "isCorrect": false, "consequence": "Tahun betul tetapi buahnya pisang saba, bukan pinang."}], "aftermath": "Pengacara menyebut tahun salah di hadapan tetamu Sabah.", "turns": [{"after": 7, "options": [{"text": "Sungai Serak menjadi Sungai Sarawak, bersempena bijih galian bernama sarawak; juga cerava, antimoni, panggilan Portugis.", "isCorrect": true, "reaction": "Pesawah mengangguk. Dua cerita dicatat."}, {"text": "Pada pendapat aku, sarawak dari pokok mentagau, kerana tiada siapa yang akan peduli dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pesawah menggeleng. Mentagau berkait dengan Selangor."}, {"text": "Sarawak dari kelapa hanyut, jadi tidak perlu dipedulikan lagi dan kita tidak perlu ambil kisah.", "isCorrect": false, "reaction": "Pesawah menggeleng. Itu cerita Perlis."}], "clue": "Sarawak: Sungai Serak, bijih sarawak atau cerava."}]}'),
(235, 'e2_n2_s17', 'Borneo di Talian', 'Padankan setiap kad dengan jawapannya.', '4', 'Memadankan Kuching, Kota Kinabalu, Sabah Tanah Airku, Ibu Pertiwiku dan Maju dan Sejahtera.', '{"pairs": [{"text": "Kuching", "pair": 1}, {"text": "Ibu negeri Sarawak", "pair": 1}, {"text": "Kota Kinabalu", "pair": 2}, {"text": "Ibu negeri Sabah", "pair": 2}, {"text": "Sabah Tanah Airku", "pair": 3}, {"text": "Lagu Sabah", "pair": 3}, {"text": "Ibu Pertiwiku", "pair": 4}, {"text": "Lagu Sarawak", "pair": 4}, {"text": "Maju dan Sejahtera", "pair": 5}, {"text": "Lagu Wilayah Persekutuan", "pair": 5}], "aftermath": "Lagu Sarawak dimainkan untuk Sabah.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, ia identiti dan lambang kemegahan negeri.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menamatkan panggilan."}, {"text": "Ia hanya hiasan, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pegawai menggeleng. Lambang ialah identiti negeri."}, {"text": "Ia supaya negeri lain takut dan itu lebih senang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Ia bukan untuk menakutkan."}], "clue": "Lambang negeri ialah identiti dan kemegahan."}]}'),
(236, 'e2_n2_s18', 'Bukti di Dewan', 'Cari tiga lambang negeri di dewan, iaitu jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan.', '{"bgImage": "../assets/gameAsset/background/wilayah_persekutuan.png", "hotspots": [{"name": "Jata: lambang kedaulatan negeri", "top": "40.4%", "left": "70%"}, {"name": "Bendera: lambang identiti negeri", "top": "20.9%", "left": "72.7%"}, {"name": "Radio: lagu Maju dan Sejahtera", "top": "86.4%", "left": "74.1%"}], "aftermath": "Zahar menukar kad dan majlis tersasar.", "turns": [{"after": 5, "options": [{"text": "Bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri; mengenalinya menaikkan rasa cinta akan negara.", "isCorrect": true, "reaction": "Tetamu bertepuk tangan. Zahar menunduk dan pergi."}, {"text": "Kerana ia hiasan sahaja, kerana tiada siapa yang akan peduli dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pengacara menggeleng. Lambang ialah identiti negeri."}, {"text": "Supaya negeri lain takut, jadi tidak perlu dipedulikan lagi dan lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Pengacara menggeleng. Ia bukan untuk menakutkan."}], "clue": "Lambang negeri ialah identiti dan kemegahan."}]}'),
(237, 'e2_n3_s1', 'Cop Pertama: Sabah', 'Padankan setiap petunjuk nama Sabah dengan maksudnya.', '4', 'Memadankan pisang saba, Maharajah of Sabah dan 1877.', '{"pairs": [{"text": "Pisang saba", "pair": 1}, {"text": "Pisang yang banyak ditanam di pantai barat Sabah sebagai sumber makanan", "pair": 1}, {"text": "Maharajah of Sabah", "pair": 2}, {"text": "Dokumen sejarah yang mencatat nama Sabah", "pair": 2}, {"text": "1877", "pair": 3}, {"text": "Tahun dokumen itu", "pair": 3}], "aftermath": "Penjaga menolak cop dan Pengembara terpaksa mengulang.", "turns": [{"after": 6, "options": [{"text": "Menurut aku, pisang yang banyak ditanam di pantai barat Sabah sebagai sumber makanan.", "isCorrect": true, "reaction": "Penjaga mengangguk dan menekan cop."}, {"text": "Pisang yang hanya untuk hiasan, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ia sumber makanan."}, {"text": "Pisang yang ditanam di Perlis, kerana tiada siapa yang akan peduli dan itu lebih senang.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ia ditanam di pantai barat Sabah."}], "clue": "Pisang saba ditanam di pantai barat Sabah sebagai makanan."}]}'),
(238, 'e2_n3_s2', 'Surat Berlogam', 'Nyahkod surat dan tentukan asal nama Sarawak.', '5', 'Mengenal pasti Sungai Serak menjadi Sungai Sarawak.', '{"clueText": "Surat: Nama Sarawak berubah daripada nama sungai kecil kepada nama sungai besar, bersempena sejenis galian bijih.", "options": [{"text": "Sungai Serak menjadi Sungai Sarawak", "isCorrect": true}, {"text": "Sungai Gombak menjadi Sungai Klang", "isCorrect": false, "consequence": "Itu sungai berkait dengan Kuala Lumpur."}, {"text": "Pulo Ka Satu menjadi Pulau Pinang", "isCorrect": false, "consequence": "Itu nama asal Pulau Pinang."}, {"text": "Ujong Tanah menjadi Johor", "isCorrect": false, "consequence": "Itu nama Johor dalam naskhah klasik."}], "aftermath": "Penjaga menggeleng dan menutup pondok.", "turns": [{"after": 6, "options": [{"text": "Panggilan Portugis dikaitkan dengan ''cerava'', sejenis logam antimoni.", "isCorrect": true, "reaction": "Penjaga mengangguk dan menekan cop."}, {"text": "Cerava ialah sejenis pokok, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ia logam antimoni."}, {"text": "Cerava ialah nama sungai, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ia logam antimoni."}], "clue": "Cerava ialah antimoni, panggilan Portugis."}]}'),
(239, 'e2_n3_s3', 'Kad Borneo', 'Padankan setiap kad dengan jawapannya.', '4', 'Memadankan Kuching, Kota Kinabalu, Sabah Tanah Airku, Ibu Pertiwiku dan Yang di-Pertua Negeri.', '{"pairs": [{"text": "Kuching", "pair": 1}, {"text": "Ibu negeri Sarawak", "pair": 1}, {"text": "Kota Kinabalu", "pair": 2}, {"text": "Ibu negeri Sabah", "pair": 2}, {"text": "Sabah Tanah Airku", "pair": 3}, {"text": "Lagu Sabah", "pair": 3}, {"text": "Ibu Pertiwiku", "pair": 4}, {"text": "Lagu Sarawak", "pair": 4}, {"text": "Yang di-Pertua Negeri", "pair": 5}, {"text": "Gelaran ketua Sabah dan Sarawak", "pair": 5}], "aftermath": "Cop ditahan sehingga padanan betul.", "turns": [{"after": 6, "options": [{"text": "Yang di-Pertuan Agong.", "isCorrect": true, "reaction": "Pegawai Sabah mengangguk dan menandatangani kad."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu untuk Sabah dan Sarawak."}, {"text": "Pada pendapat aku, sultan.", "isCorrect": false, "reaction": "Pegawai menggeleng. Wilayah Persekutuan bukan negeri bersultan."}], "clue": "Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong."}]}'),
(240, 'e2_n3_s4', 'Dokumen Tiga Nama', 'Bantu pemandu pelancong memilih dokumen yang betul tentang nama tiga wilayah.', '3', 'Membantu NPC memilih dokumen: lumpur, labuhan dan Putra + jaya.', '{"npcName": "Pemandu Pelancong", "prompt": "Dokumen mana yang menerangkan asal nama Kuala Lumpur, Labuan dan Putrajaya dengan betul?", "options": [{"text": "Kuala Lumpur: muara berlumpur; Labuan: labuhan kapal; Putrajaya: Tunku Abdul Rahman Putra", "item": "dokumen", "isCorrect": true}, {"text": "Kuala Lumpur: pelangi; Labuan: labuhan kapal; Putrajaya: Tunku Abdul Rahman Putra", "item": "dokumen", "isCorrect": false, "consequence": "Pelancong menyalin nama yang salah tentang pelangi."}, {"text": "Kuala Lumpur: muara berlumpur; Labuan: pokok penaga; Putrajaya: Tunku Abdul Rahman Putra", "item": "dokumen", "isCorrect": false, "consequence": "Penaga ialah cerita Pulau Pinang, bukan Labuan."}, {"text": "Kuala Lumpur: muara berlumpur; Labuan: labuhan kapal; Putrajaya: pisang saba", "item": "dokumen", "isCorrect": false, "consequence": "Pisang saba ialah cerita Sabah, bukan Putrajaya."}], "aftermath": "Pelancong menyalin nama yang salah.", "turns": [{"after": 6, "options": [{"text": "Kuala Lumpur, Labuan dan Putrajaya.", "isCorrect": true, "reaction": "Pemandu mengangguk dan membawa pelancong ke pentas."}, {"text": "Kuala Lumpur, Johor dan Sabah.", "isCorrect": false, "reaction": "Pemandu menggeleng. Johor dan Sabah ialah negeri."}, {"text": "Putrajaya, Melaka dan Pulau Pinang.", "isCorrect": false, "reaction": "Pemandu menggeleng. Melaka dan Pulau Pinang ialah negeri."}], "clue": "Wilayah Persekutuan: Kuala Lumpur, Labuan dan Putrajaya."}]}'),
(241, 'e2_n3_s5', 'Nota di Bawah Kad', 'Nyahkod nota dan tentukan wilayah yang dimaksudkan.', '5', 'Mengenal pasti Wilayah Persekutuan.', '{"clueText": "Nota: Lagu Maju dan Sejahtera dimainkan untuk wilayah yang ketuanya ialah Yang di-Pertuan Agong, dan wilayah ini tidak mempunyai ibu negeri dan bandar diraja.", "options": [{"text": "Wilayah Persekutuan", "isCorrect": true}, {"text": "Negeri Sembilan", "isCorrect": false, "consequence": "Negeri Sembilan ketuanya Yang di-Pertuan Besar."}, {"text": "Melaka", "isCorrect": false, "consequence": "Melaka ketuanya Yang di-Pertua Negeri."}, {"text": "Sabah", "isCorrect": false, "consequence": "Sabah ketuanya Yang di-Pertua Negeri."}], "aftermath": "Penjaga memadam nota dan Pengembara terpaksa mengulang.", "turns": [{"after": 6, "options": [{"text": "Ketuanya Yang di-Pertuan Agong dan ibu negerinya tiada.", "isCorrect": true, "reaction": "Penjaga mengangguk dan menekan cop."}, {"text": "Ketuanya Sultan dan ibu negerinya Putrajaya, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Penjaga menggeleng. Wilayah Persekutuan tiada ibu negeri."}, {"text": "Ketuanya Raja dan ibu negerinya Kuala Lumpur.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ketuanya bukan Raja."}], "clue": "Ketua Yang di-Pertuan Agong; tiada ibu negeri."}]}'),
(242, 'e2_n3_s6', 'Nota Batu Permata', 'Nyahkod nota dan tentukan perkataan yang melahirkan nama Johor.', '5', 'Mengenal pasti Jauhar sebagai asal nama Johor.', '{"clueText": "Nota: Nama Johor dikatakan berasal daripada perkataan Arab bagi batu permata yang bernilai.", "options": [{"text": "Jauhar", "isCorrect": true}, {"text": "Malakat", "isCorrect": false, "consequence": "Itu perhimpunan pedagang bagi Melaka."}, {"text": "Mahang", "isCorrect": false, "consequence": "Itu pokok yang melahirkan nama Pahang."}, {"text": "Kheddah", "isCorrect": false, "consequence": "Itu perangkap gajah bagi nama Kedah."}], "aftermath": "Penjaga tidak memberi cop kerana nota tidak dinyahkod.", "turns": [{"after": 6, "options": [{"text": "Bahasa Arab, bermaksud batu permata yang bernilai.", "isCorrect": true, "reaction": "Peniaga mengangguk dan tersenyum."}, {"text": "Bahasa Siam, bermaksud kelapa hanyut, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Peniaga menggeleng. Itu cerita Perlis."}, {"text": "Bahasa Tamil, bermaksud cawan, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Peniaga menggeleng. Itu cerita lain."}], "clue": "Jauhar ialah bahasa Arab, batu permata bernilai."}]}'),
(243, 'e2_n3_s7', 'Pusat dan Istana Johor', 'Padankan setiap kad dengan jawapan untuk Johor.', '4', 'Memadankan Johor Bahru, Bandar Maharani, Lagu Bangsa Johor dan Sultan.', '{"pairs": [{"text": "Johor Bahru", "pair": 1}, {"text": "Ibu negeri Johor", "pair": 1}, {"text": "Bandar Maharani", "pair": 2}, {"text": "Bandar diraja Johor", "pair": 2}, {"text": "Lagu Bangsa Johor", "pair": 3}, {"text": "Lagu Johor", "pair": 3}, {"text": "Sultan", "pair": 4}, {"text": "Gelaran ketua Johor", "pair": 4}], "aftermath": "Cop ditahan dan Pengembara diminta mencuba lagi.", "turns": [{"after": 6, "options": [{"text": "Rasanya, ia menyimpan warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Bagi aku, ia tempat membeli barang, jadi tidak payah difikirkan panjang dan cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Ia menyimpan warisan."}, {"text": "Rasanya, ia pusat pentadbiran sahaja, lagipun perkara itu tidak penting dan ramai orang buat begitu.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu ibu negeri."}], "clue": "Bandar diraja menyimpan warisan sejarah."}]}'),
(244, 'e2_n3_s8', 'Nota di Akar Pokok', 'Nyahkod nota dan tentukan binatang yang menendang anjing.', '5', 'Mengenal pasti pelanduk putih.', '{"clueText": "Nota: Parameswara berehat di bawah pokok ini ketika seekor binatang kecil putih menendang anjing pemburuannya.", "options": [{"text": "Pelanduk putih", "isCorrect": true}, {"text": "Gajah putih", "isCorrect": false, "consequence": "Gajah terlalu besar untuk binatang kecil."}, {"text": "Harimau putih", "isCorrect": false, "consequence": "Harimau bukan binatang kecil."}, {"text": "Kijang", "isCorrect": false, "consequence": "Kijang tidak putih dan nota menyebut binatang kecil."}], "aftermath": "Orang tua menyindir kerana Pengembara tersilap binatang.", "turns": [{"after": 6, "options": [{"text": "Sumber Arab menyebut Malakat, perhimpunan para pedagang.", "isCorrect": true, "reaction": "Peniaga mengangguk dan tersenyum."}, {"text": "Malakat ialah nama pokok, lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Peniaga menggeleng. Ia perhimpunan pedagang."}, {"text": "Malakat ialah nama anjing, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Peniaga ketawa dan menggeleng."}], "clue": "Malakat bermaksud perhimpunan para pedagang."}]}'),
(245, 'e2_n3_s9', 'Kaset Lagu Melaka', 'Bantu pegawai radio memilih kaset lagu negeri Melaka.', '3', 'Membantu NPC memilih kaset Melaka Maju Jaya.', '{"npcName": "Pegawai Radio", "prompt": "Kaset mana ialah lagu negeri Melaka?", "options": [{"text": "Melaka Maju Jaya", "item": "kaset", "isCorrect": true}, {"text": "Lagu Bangsa Johor", "item": "kaset", "isCorrect": false, "consequence": "Lagu Johor dimainkan di hadapan ketua Melaka."}, {"text": "Duli Yang Maha Mulia", "item": "kaset", "isCorrect": false, "consequence": "Lagu Selangor dimainkan di hadapan ketua Melaka."}, {"text": "Untuk Negeri Kita", "item": "kaset", "isCorrect": false, "consequence": "Lagu Pulau Pinang dimainkan di hadapan ketua Melaka."}], "aftermath": "Lagu negeri lain dimainkan.", "turns": [{"after": 7, "options": [{"text": "Bandar Melaka. Peta tidak menandakan bandar diraja di sana.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Bandar Maharani, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu bandar diraja Johor."}, {"text": "Rasanya, seremban, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu ibu negeri Negeri Sembilan."}], "clue": "Ibu negeri Melaka ialah Bandar Melaka."}]}'),
(246, 'e2_n3_s10', 'Sembilan Kerusi', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan nagari, 1773 dan luak asal.', '{"pairs": [{"text": "Nagari", "pair": 1}, {"text": "Wilayah dalam dialek Minangkabau", "pair": 1}, {"text": "1773", "pair": 2}, {"text": "Tahun luak asal Negeri Sembilan", "pair": 2}, {"text": "Sungai Ujong dan Jelebu", "pair": 3}, {"text": "Antara luak asal Negeri Sembilan", "pair": 3}, {"text": "Segamat dan Klang", "pair": 4}, {"text": "Antara luak asal juga", "pair": 4}], "aftermath": "Penghulu menegur dan cop ditahan.", "turns": [{"after": 6, "options": [{"text": "Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.", "isCorrect": true, "reaction": "Penghulu mengangguk dan menekan cop."}, {"text": "Kedah, Perak, Perlis, Johor, Pahang, Melaka, Kelantan, Terengganu dan Sabah.", "isCorrect": false, "reaction": "Penghulu menggeleng. Itu negeri, bukan luak."}, {"text": "Rasanya, sembilan pulau di selat, jadi tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Penghulu ketawa. Itu bukan luak."}], "clue": "Luak asal ialah Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang."}]}'),
(247, 'e2_n3_s11', 'Istana Negeri Sembilan', 'Padankan setiap kad dengan jawapan untuk Negeri Sembilan.', '4', 'Memadankan Seremban, Seri Menanti, Berkatlah Yang di-Pertuan Besar dan Yang di-Pertuan Besar.', '{"pairs": [{"text": "Seremban", "pair": 1}, {"text": "Ibu negeri Negeri Sembilan", "pair": 1}, {"text": "Seri Menanti", "pair": 2}, {"text": "Bandar diraja Negeri Sembilan", "pair": 2}, {"text": "Berkatlah Yang di-Pertuan Besar", "pair": 3}, {"text": "Lagu Negeri Sembilan", "pair": 3}, {"text": "Yang di-Pertuan Besar", "pair": 4}, {"text": "Gelaran ketua Negeri Sembilan", "pair": 4}], "aftermath": "Cop ditahan.", "turns": [{"after": 6, "options": [{"text": "Sikap menghormati dan taat setia kepada raja dapat dipupuk.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Pada pendapat aku, supaya kita dapat bergelar raja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}, {"text": "Aku fikir supaya kita dapat mengundi mereka dan biarkan sahaja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}], "clue": "Mengenali ketua negeri memupuk hormat dan taat setia."}]}'),
(248, 'e2_n3_s12', 'Kuala dan Pura', 'Padankan setiap istilah dengan maksudnya.', '4', 'Memadankan mentagau, selangur, mahang dan Inderapura.', '{"pairs": [{"text": "Mentagau", "pair": 1}, {"text": "Pokok di kuala sungai Selangor", "pair": 1}, {"text": "Selangur atau sangur", "pair": 2}, {"text": "Serangga banyak di sungai", "pair": 2}, {"text": "Mahang", "pair": 3}, {"text": "Pokok yang melahirkan nama Pahang", "pair": 3}, {"text": "Inderapura atau Pura", "pair": 4}, {"text": "Nama Pahang dalam Sulalatus Salatin", "pair": 4}], "aftermath": "Kedua-dua penjaga menolak cop.", "turns": [{"after": 6, "options": [{"text": "Bandar atau pekan.", "isCorrect": true, "reaction": "Penjaga Pahang mengangguk dan menekan cop."}, {"text": "Pokok besar.", "isCorrect": false, "reaction": "Penjaga menggeleng. Pura bermaksud bandar."}, {"text": "Sungai kecil.", "isCorrect": false, "reaction": "Penjaga menggeleng. Pura bermaksud bandar."}], "clue": "Pura bermaksud bandar atau pekan."}]}'),
(249, 'e2_n3_s13', 'Dua Peta Pusat', 'Padankan setiap kad dengan negeri dan jawapannya.', '4', 'Memadankan Shah Alam, Klang, Duli Yang Maha Mulia, Kuantan, Pekan dan Allah Selamatkan Sultan Kami.', '{"pairs": [{"text": "Shah Alam", "pair": 1}, {"text": "Ibu negeri Selangor", "pair": 1}, {"text": "Klang", "pair": 2}, {"text": "Bandar diraja Selangor", "pair": 2}, {"text": "Duli Yang Maha Mulia", "pair": 3}, {"text": "Lagu Selangor", "pair": 3}, {"text": "Kuantan", "pair": 4}, {"text": "Ibu negeri Pahang", "pair": 4}, {"text": "Pekan", "pair": 5}, {"text": "Bandar diraja Pahang", "pair": 5}, {"text": "Allah Selamatkan Sultan Kami", "pair": 6}, {"text": "Lagu Pahang", "pair": 6}], "aftermath": "Cop ditahan.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, sultan.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Sebenarnya, raja.", "isCorrect": false, "reaction": "Pegawai menggeleng. Raja hanya di Perlis."}, {"text": "Yang di-Pertua Negeri.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu untuk empat negeri lain."}], "clue": "Ketua Selangor dan Pahang bergelar Sultan."}]}'),
(250, 'e2_n3_s14', 'Pelangi dan Kilat', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan taring anu, terangnya ganu, kilatan dan gelam hutan.', '{"pairs": [{"text": "Taring anu", "pair": 1}, {"text": "Taring besar di Pulau Duyong", "pair": 1}, {"text": "Terangnya ganu", "pair": 2}, {"text": "Pelangi", "pair": 2}, {"text": "Kilatan", "pair": 3}, {"text": "Cahaya terang yang dilihat orang Patani", "pair": 3}, {"text": "Gelam hutan", "pair": 4}, {"text": "Pokok di pesisir pantai Kelantan", "pair": 4}], "aftermath": "Penjaga menolak cop kerana padanan tidak lengkap.", "turns": [{"after": 7, "options": [{"text": "Bagi aku, taring besar seperti gading gajah atau binatang liar lain.", "isCorrect": true, "reaction": "Nelayan mengangguk dan menekan cop."}, {"text": "Gading daripada ikan paus, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Nelayan menggeleng. Ia seperti gading gajah."}, {"text": "Aku fikir gading daripada kayu, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Nelayan menggeleng. Ia taring besar."}], "clue": "Taring anu ialah taring besar seperti gading gajah."}]}'),
(251, 'e2_n3_s15', 'Nota di Bawah Radio', 'Nyahkod nota dan tentukan dua negeri yang berkongsi tajuk lagu Selamat Sultan.', '5', 'Mengenal pasti Terengganu dan Kelantan.', '{"clueText": "Nota: Dua negeri di pantai timur menggunakan lagu bertajuk Selamat Sultan. Ibu negeri mereka ialah Kuala Terengganu dan Kota Bharu.", "options": [{"text": "Terengganu dan Kelantan", "isCorrect": true}, {"text": "Pahang dan Terengganu", "isCorrect": false, "consequence": "Pahang mempunyai lagu lain, iaitu Allah Selamatkan Sultan Kami."}, {"text": "Pahang dan Kelantan", "isCorrect": false, "consequence": "Pahang mempunyai lagu lain, iaitu Allah Selamatkan Sultan Kami."}, {"text": "Kedah dan Perak", "isCorrect": false, "consequence": "Dua negeri itu di utara dan lagu mereka lain."}], "aftermath": "Penjaga menolak cop.", "turns": [{"after": 6, "options": [{"text": "Kuala Terengganu dan Kota Bharu.", "isCorrect": true, "reaction": "Penjaga mengangguk dan menekan cop."}, {"text": "Kuantan dan Pekan, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Penjaga menggeleng. Itu milik Pahang."}, {"text": "Ipoh dan Alor Setar.", "isCorrect": false, "reaction": "Penjaga menggeleng. Itu ibu negeri utara."}], "clue": "Ibu negeri Terengganu: Kuala Terengganu; Kelantan: Kota Bharu."}]}'),
(252, 'e2_n3_s16', 'Jeti Perak dan Pulau Pinang', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan kilatan ikan, bijih timah putih, Pulo Ka Satu, Tanjong Penaga dan pinang.', '{"pairs": [{"text": "Kilatan ikan", "pair": 1}, {"text": "Ikan berkilau di dalam air (Perak)", "pair": 1}, {"text": "Bijih timah putih berkilat", "pair": 2}, {"text": "Pandangan lain tentang nama Perak", "pair": 2}, {"text": "Pulo Ka Satu", "pair": 3}, {"text": "Nama asal Pulau Pinang", "pair": 3}, {"text": "Tanjong Penaga", "pair": 4}, {"text": "Gelaran orang Kedah kerana banyak pokok penaga", "pair": 4}, {"text": "Buah pinang", "pair": 5}, {"text": "Bahan dagangan penting", "pair": 5}], "aftermath": "Penjaga menyindir kerana padanan tersilap.", "turns": [{"after": 6, "options": [{"text": "Bahan dagangan penting.", "isCorrect": true, "reaction": "Pedagang mengangguk dan menekan cop."}, {"text": "Pada pendapat aku, kerana pulau itu berbentuk pinang.", "isCorrect": false, "reaction": "Pedagang menggeleng. Hampir, tetapi belum tepat. Cuba sekali lagi."}, {"text": "Kerana ia bukan barang dagangan.", "isCorrect": false, "reaction": "Pedagang menggeleng. Pinang bahan dagangan penting."}], "clue": "Pinang bahan dagangan penting yang dikaitkan dengan nama Pulau Pinang."}]}'),
(253, 'e2_n3_s17', 'Dokumen Perak dan Pulau Pinang', 'Bantu pegawai daerah memilih dokumen yang betul.', '3', 'Membantu NPC memilih dokumen: Ipoh, Kuala Kangsar, George Town, lagu dan ketua.', '{"npcName": "Pegawai Daerah", "prompt": "Dokumen mana yang betul untuk Perak dan Pulau Pinang?", "options": [{"text": "Perak: Ipoh, Kuala Kangsar, Sultan; Pulau Pinang: George Town, Yang di-Pertua Negeri", "item": "dokumen", "isCorrect": true}, {"text": "Perak: Kuala Kangsar ibu negeri, Ipoh bandar diraja", "item": "dokumen", "isCorrect": false, "consequence": "Jemputan dihantar ke bandar yang salah."}, {"text": "Perak bergelar Yang di-Pertua Negeri", "item": "dokumen", "isCorrect": false, "consequence": "Ketua Perak ialah Sultan dan jemputan tersalah."}, {"text": "Pulau Pinang bergelar Raja", "item": "dokumen", "isCorrect": false, "consequence": "Raja hanya di Perlis dan jemputan tersalah."}], "aftermath": "Jemputan salah dihantar.", "turns": [{"after": 6, "options": [{"text": "Untuk Negeri Kita.", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Allah Lanjutkan Usia Sultan.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu lagu Perak."}, {"text": "Aamiin-Aamiin.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu lagu Perlis."}], "clue": "Lagu Pulau Pinang ialah Untuk Negeri Kita."}]}'),
(254, 'e2_n3_s18', 'Gajah dan Kelapa', 'Padankan setiap sebutan dengan maksudnya.', '4', 'Memadankan kheddah, qadah, kadaram, prow-lowy dan peroleh.', '{"pairs": [{"text": "Kheddah", "pair": 1}, {"text": "Perangkap gajah", "pair": 1}, {"text": "Qadah", "pair": 2}, {"text": "Cawan atau gelas berkaki", "pair": 2}, {"text": "Kadaram atau kalagam", "pair": 3}, {"text": "Nama Kedah dalam tulisan Tamil", "pair": 3}, {"text": "Prow-lowy", "pair": 4}, {"text": "Kelapa hanyut", "pair": 4}, {"text": "Peroleh", "pair": 5}, {"text": "Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail", "pair": 5}], "aftermath": "Cop ditahan.", "turns": [{"after": 7, "options": [{"text": "Aku fikir yang menerima mandat kerana membantu Perlis menentang Siam.", "isCorrect": true, "reaction": "Pesawah mengangguk dan menekan cop."}, {"text": "Seorang pedagang Arab, jadi tidak payah difikirkan panjang dan lupakan sahaja.", "isCorrect": false, "reaction": "Pesawah menggeleng. Dia menerima mandat."}, {"text": "Seorang pemburu gajah, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pesawah menggeleng. Dia berkait dengan Perlis."}], "clue": "Raja Syed Hussin menerima mandat kerana membantu Perlis menentang Siam."}]}'),
(255, 'e2_n3_s19', 'Kaset Lagu Kedah', 'Bantu pegawai radio memilih kaset lagu negeri Kedah.', '3', 'Membantu NPC memilih kaset Allah Selamatkan Sultan Mahkota.', '{"npcName": "Pegawai Radio", "prompt": "Kaset mana ialah lagu negeri Kedah?", "options": [{"text": "Allah Selamatkan Sultan Mahkota", "item": "kaset", "isCorrect": true}, {"text": "Aamiin-Aamiin", "item": "kaset", "isCorrect": false, "consequence": "Lagu Perlis dimainkan di hadapan tetamu Kedah."}, {"text": "Allah Lanjutkan Usia Sultan", "item": "kaset", "isCorrect": false, "consequence": "Lagu Perak dimainkan di hadapan tetamu Kedah."}, {"text": "Untuk Negeri Kita", "item": "kaset", "isCorrect": false, "consequence": "Lagu Pulau Pinang dimainkan di hadapan tetamu Kedah."}], "aftermath": "Lagu negeri lain dimainkan.", "turns": [{"after": 6, "options": [{"text": "Aamiin-Aamiin. Kangar dan Arau (Perlis); Alor Setar dan Anak Bukit (Kedah).", "isCorrect": true, "reaction": "Pegawai mengangguk dan menekan cop."}, {"text": "Allah Lanjutkan Usia Sultan; Ipoh dan Kuala Kangsar, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu milik Perak."}, {"text": "Untuk Negeri Kita; George Town, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Pegawai menggeleng. Itu milik Pulau Pinang."}], "clue": "Lagu Perlis ialah Aamiin-Aamiin. Kangar-Arau; Alor Setar-Anak Bukit."}]}'),
(256, 'e2_n3_s20', 'Cop Terakhir', 'Cari tiga lambang negeri di pentas, iaitu jata, bendera dan radio lagu.', '2', 'Mencari bukti lambang negeri: jata, bendera dan lagu sebagai identiti dan kemegahan.', '{"bgImage": "../assets/gameAsset/background/wilayah_persekutuan.png", "hotspots": [{"name": "Jata: lambang kedaulatan negeri", "top": "40.4%", "left": "70%"}, {"name": "Bendera: lambang identiti negeri", "top": "20.9%", "left": "72.7%"}, {"name": "Radio: lagu Maju dan Sejahtera", "top": "86.4%", "left": "74.1%"}], "aftermath": "Cop terakhir tidak diberikan.", "turns": [{"after": 6, "options": [{"text": "Bendera, lagu dan jata ialah identiti dan lambang kemegahan setiap negeri; mengenalinya menaikkan rasa cinta akan negara.", "isCorrect": true, "reaction": "Penjaga mengangguk. Pasport lengkap."}, {"text": "Kerana ia hiasan sahaja, kerana tiada siapa yang akan peduli dan tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penjaga menggeleng. Lambang ialah identiti negeri."}, {"text": "Supaya negeri lain takut, jadi tidak perlu dipedulikan lagi dan lagipun perkara itu tidak penting.", "isCorrect": false, "reaction": "Penjaga menggeleng. Ia bukan untuk menakutkan."}], "clue": "Lambang negeri ialah identiti dan kemegahan."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e2_n1_s1', 'hint', 'Tok memulakan halaman pertama di Perlis. Perhatikan kelapa di dalam parit dan baca perkataan Siam itu.', NULL, NULL),
(201, NULL, 'hint', 'Catatan menyebut sesuatu yang HANYUT di AIR dan ditemui di PARIT. Pilih benda yang boleh terapung dan berhanyut, bukan sifat air atau pokok.', 'Perlis dikaitkan dengan prow-lowy yang bermaksud kelapa hanyut, atau perkataan peroleh daripada mandat Raja Syed Hussin. Dua cerita itu sama-sama dicatat dalam sejarah negeri.', 'Tepat! Pesawah mengangguk dan Tok menulis halaman pertama Buku Asal Usul.'),
(NULL, 'e2_n1_s2', 'hint', 'Halaman kedua ialah Kedah. Satu benda untuk menangkap gajah, satu untuk minum, satu lagi tulisan India Selatan.', NULL, NULL),
(202, NULL, 'hint', 'Tiga nama, iaitu satu ialah alat menangkap binatang besar, satu ialah bekas untuk minum, dan satu ialah nama dalam tulisan India Selatan. Tulisan itu bukan benda.', 'Nama Kedah ada tiga cerita. Ia datang daripada kheddah, alat menangkap binatang besar, atau qadah, bekas untuk minum, atau kadaram dan kalagam. Tiga bahasa, satu nama.', 'Hebat! Tiga catatan dipadankan dan kedua-dua lelaki itu senyap.'),
(NULL, 'e2_n1_s3', 'hint', 'Dua negeri sekali gus. Pulau Pinang dan Perak. Pisahkan cerita setiap negeri.', NULL, NULL),
(203, NULL, 'hint', 'Cari ''pinang'' dan ''penaga'' untuk satu negeri, dan ''berkilau'' atau ''perak'' untuk negeri yang satu lagi. Baca kad kanan hingga habis sebelum memadankan.', 'Pulau Pinang bermula daripada Pulo Ka Satu, Tanjong Penaga dan buah pinang. Perak pula daripada kilatan ikan dan bijih timah. Nama kedua-dua negeri mengingatkan kita kepada alam dan perdagangan.', 'Betul! Nelayan dan pelombong akur dan halaman ketiga siap.'),
(NULL, 'e2_n1_s4', 'hint', 'Tok memadankan ibu negeri dan bandar diraja di utara. Lihat titik merah dan kuning di peta.', NULL, NULL),
(204, NULL, 'hint', 'Satu ibu negeri tiada bandar diraja ditanda pada peta. Itulah negeri yang ketuanya bukan Sultan atau Raja. Padankan tiga yang lain dahulu.', 'Di utara, ibu negeri ialah pusat pentadbiran dan bandar diraja menyimpan warisan. Warisan itulah yang perlu kita jaga.', 'Cemerlang! Titik merah dan kuning dipadankan dengan betul.'),
(NULL, 'e2_n1_s5', 'hint', 'Lagu negeri ialah lambang kemegahan. Tajuk lagu Kedah menyebut ''Sultan'' dan ''Mahkota''.', NULL, NULL),
(205, NULL, 'hint', 'Cari tajuk yang menyebut ''Sultan'' dan sesuatu yang dipakai di kepala raja. Tajuk yang menyebut ''Usia'' ialah lagu negeri lain.', 'Lagu negeri menjadi lambang kemegahan dan kedaulatan. Apabila lagu yang betul dimainkan, kita menghormati negeri itu.', 'Betul! Lagu Kedah berkumandang dan majlis bermula dengan lancar.'),
(NULL, 'e2_n1_s6', 'hint', 'Dua negeri, iaitu Selangor dan Negeri Sembilan. Satu daripadanya mempunyai angka 1773.', NULL, NULL),
(206, NULL, 'hint', '''Mentagau'' ialah pokok dan ''selangur'' ialah serangga, iaitu kedua-duanya berkait dengan satu negeri. ''Nagari'' dan tahun 1773 berkait dengan negeri yang bermula daripada sembilan luak.', 'Negeri Sembilan bermula pada 1773 daripada sembilan luak, dan perkataan negeri datang daripada nagari. Selangor pula dikaitkan dengan pokok mentagau atau sungai Selangur.', 'Tepat! Nelayan dan penghulu bersalaman.'),
(NULL, 'e2_n1_s7', 'hint', 'Dua negeri, iaitu Melaka dan Johor. Tok memadankan perdagangan, legenda dan naskhah lama.', NULL, NULL),
(207, NULL, 'hint', 'Cari kata kunci, iaitu perhimpunan pedagang dan pokok tempat Parameswara berehat berkait dengan satu pelabuhan. Batu permata dan ''hujung daratan'' berkait dengan negeri di selatan.', 'Melaka diambil daripada Malakat, pokok tempat Parameswara berehat. Johor pula daripada Jauhar, batu permata, atau Ujong Tanah. Nama kedua-duanya lahir daripada perdagangan, legenda dan naskhah lama.', 'Betul! Empat cerita dipadankan dan pembaca naskhah mengangguk.'),
(NULL, 'e2_n1_s8', 'hint', 'Tok memadankan ibu negeri dan bandar diraja di tengah semenanjung. Seri Menanti dan Bandar Maharani ialah bandar diraja.', NULL, NULL),
(208, NULL, 'hint', 'Satu ibu negeri tiada bandar diraja ditanda pada peta. Itulah negeri yang ketuanya Yang di-Pertua Negeri. Padankan tiga yang lain dahulu.', 'Di selatan, ibu negeri ialah pusat pentadbiran dan bandar diraja menyimpan warisan. Pembangunan berjalan dan warisan tetap dijaga.', 'Betul! Fail dipadankan dan pegawai menarik nafas lega.'),
(NULL, 'e2_n1_s9', 'hint', 'Empat lagu dari empat negeri tengah dan selatan. Tajuk yang betul menyebut nama negerinya sendiri.', NULL, NULL),
(209, NULL, 'hint', 'Cari tajuk yang menyebut ''Bangsa'' dan ''Johor''. Tajuk yang menyebut ''Melaka'', ''Yang di-Pertuan Besar'' atau ''Duli'' milik negeri lain.', 'Setiap negeri di selatan mempunyai lagu tersendiri. Lagu yang betul menunjukkan kita menghormati negeri itu.', 'Betul! Lagu Johor berkumandang dengan megah.'),
(NULL, 'e2_n1_s10', 'hint', 'Pantai timur ada tiga negeri dan enam cerita. Pelangi dan taring milik negeri yang sama.', NULL, NULL),
(210, NULL, 'hint', 'Enam sebutan, tiga negeri. Pokok dan tempat lama berkait dengan Pahang, taring dan pelangi dengan Terengganu, cahaya dan pokok pantai dengan Kelantan.', 'Pahang diambil daripada pokok mahang atau Inderapura. Terengganu berasal daripada taring anu atau terangnya ganu, manakala Kelantan daripada kilatan atau gelam hutan. Semuanya lahir daripada alam dan sejarah.', 'Hebat! Enam cerita dipadankan dan pantai senyap.'),
(NULL, 'e2_n1_s11', 'hint', 'Hanya satu negeri di pantai timur mempunyai titik kuning pada peta, iaitu Pahang.', NULL, NULL),
(211, NULL, 'hint', 'Hanya satu negeri di sini mempunyai dua kad, iaitu ibu negeri dan bandar diraja. Dua negeri lagi hanya ada ibu negeri.', 'Di pantai timur, ibu negeri ialah pusat pentadbiran, dan Pekan ialah bandar diraja Pahang. Warisan pantai timur wajar dihargai.', 'Betul! Peta dipadankan dan pegawai mengangguk.'),
(NULL, 'e2_n1_s12', 'hint', 'Lagu negeri ialah lambang kedaulatan. Dua negeri pantai timur berkongsi tajuk yang sama.', NULL, NULL),
(212, NULL, 'hint', 'Dua negeri berkongsi tajuk yang sama. Negeri ketiga di pantai timur ialah Pahang, yang tajuknya berlainan. Singkirkan pasangan yang mengandungi Pahang, Kedah atau Perak.', 'Terengganu dan Kelantan sama-sama bertajuk Selamat Sultan, manakala Pahang bertajuk Allah Selamatkan Sultan Kami. Tajuk yang sama tidak bermakna negeri yang sama.', 'Tepat! Dua orang tua tersenyum dan akur.'),
(NULL, 'e2_n1_s13', 'hint', 'Tok menyeberang ke Borneo mencatat nama Sarawak dan Sabah. Cari galian, makanan dan tarikh.', NULL, NULL),
(213, NULL, 'hint', 'Cari dokumen yang betul bagi KEDUA-DUA negeri. Sarawak berkait dengan sungai dan galian, Sabah berkait dengan pisang dan tahun 1877. Singkirkan dokumen yang menukar negeri.', 'Sabah dan Sarawak ada kisah nama yang unik. Sarawak daripada Sungai Serak atau cerava, iaitu antimoni, manakala Sabah daripada pisang saba dalam dokumen 1877. Satu nama dari galian, satu lagi dari makanan.', 'Betul! Dokumen yang tepat ditemui.'),
(NULL, 'e2_n1_s14', 'hint', 'Wilayah Persekutuan terdiri daripada tiga wilayah. Satu nama dari lumpur, satu dari kapal berlabuh, satu dari seorang pemimpin.', NULL, NULL),
(214, NULL, 'hint', 'Tiga wilayah, iaitu satu daripada lumpur di muara, satu daripada tempat kapal berlabuh, satu daripada nama seorang tokoh. Cari kata ''lumpur'', ''labuh'' dan nama tokoh.', 'Kuala Lumpur bermaksud muara berlumpur, Labuan daripada labuhan, dan Putrajaya daripada Putra dan jaya. Tiga wilayah, tiga kisah perlombongan, pelayaran dan kepimpinan.', 'Betul! Tiga pelawat tersenyum puas.'),
(NULL, 'e2_n1_s15', 'hint', 'Tok memadankan ibu negeri Borneo. Satu bandar di tepi sungai, satu lagi di pantai dengan gunung.', NULL, NULL),
(215, NULL, 'hint', 'Padankan nama bandar dengan negeri dahulu, kemudian sebab ibu negeri berkembang dengan sebab yang menyebut pentadbiran. Kad ''pekerjaan'' berpasangan dengan tempat tumpuan.', 'Kuching dan Kota Kinabalu ialah ibu negeri yang menjadi pusat pentadbiran dan pekerjaan. Pembangunan pentadbiran membuatkan ibu negeri berkembang pesat.', 'Betul! Dua fail dipadankan dan pegawai tersenyum.'),
(NULL, 'e2_n1_s16', 'hint', 'Tok memadankan lagu Borneo dan Wilayah Persekutuan. Tajuk lagu Sabah menyebut ''Sabah'' secara terus.', NULL, NULL),
(216, NULL, 'hint', 'Cari tajuk yang menyebut ''Sabah''. Tajuk yang menyebut ''Ibu Pertiwiku'', ''Maju dan Sejahtera'' atau ''Melaka'' bukan lagu Sabah.', 'Lagu negeri membentuk identiti dan menjadi lambang kemegahan. Memainkannya dengan betul menunjukkan hormat kepada negeri itu.', 'Betul! Lagu Sabah berkumandang dan tetamu bangun berdiri.'),
(NULL, 'e2_n1_s17', 'hint', 'Pegawai istiadat mahu Tok menyusun gelaran ketua negeri. Tujuh Sultan, satu Raja, satu Yang di-Pertuan Besar, empat Yang di-Pertua Negeri.', NULL, NULL),
(217, NULL, 'hint', 'Raja digunakan di satu negeri sahaja. Sultan digunakan di paling banyak negeri. Yang di-Pertua Negeri ada empat negeri, termasuk dua di Borneo. Mulakan dengan yang paling mudah.', 'Ketua negeri ialah tonggak pemerintahan, dan gelarannya berbeza mengikut negeri. Apabila kita mengenalinya, kita belajar menghormati dan taat setia kepada raja.', 'Hebat! Semua kad dipasang dengan betul.'),
(NULL, 'e2_n1_s18', 'hint', 'Pesta Warisan. Buku Asal Usul dilengkapkan dengan lambang negeri. Cari sesuatu yang berkibar, tergantung dan berbunyi.', NULL, NULL),
(218, NULL, 'hint', 'Tiga lambang di pentas, iaitu bendera berkibar di sudut atas kanan tengah gambar, jata di kanan tengah, dan radio lagu di bahagian paling bawah sebelah kanan.', 'Setiap negeri ada bendera, lagu dan jata sebagai identiti. Apabila kita mengenali lambang negeri, rasa cinta akan negara pun tumbuh.', 'Berjaya! Ketiga-tiga lambang ditemui dan Buku Asal Usul dilengkapkan.'),
(NULL, 'e2_n2_s1', 'hint', 'Hari pertama kiraan detik. Kad ketua Wilayah Persekutuan hilang dan dicari melalui nota fail.', NULL, NULL),
(219, NULL, 'hint', 'Nota menyebut ketuanya ''bukan sultan, bukan raja''. Pilih gelaran yang bermaksud ketua seluruh negara, bukan ketua sebuah negeri.', 'Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong. Sebab itu Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja.', 'Betul! Kad ketua dipasang dan Encik Zahar mengetap bibir.'),
(NULL, 'e2_n2_s2', 'hint', 'Tiga wilayah mempunyai tiga kisah nama. Pegawai Istiadat memadankan papan nama.', NULL, NULL),
(220, NULL, 'hint', 'Tiga wilayah, tiga asal nama, satu daripada lumpur di muara, satu daripada tempat kapal berlabuh, satu daripada nama seorang tokoh. Cari kata ''lumpur'', ''labuh'' dan nama tokoh.', 'Kuala Lumpur, Labuan dan Putrajaya masing-masing mempunyai kisah nama sendiri. Tiga wilayah, tiga sejarah yang berbeza.', 'Betul! Papan nama dipasang semula.'),
(NULL, 'e2_n2_s3', 'hint', 'Pegawai Istiadat menyusun gelaran ketua negeri sambil dicurigai.', NULL, NULL),
(221, NULL, 'hint', 'Sultan ialah gelaran yang paling banyak negeri. Raja hanya di satu negeri di utara semenanjung. Yang di-Pertua Negeri ada empat negeri, termasuk dua di Borneo.', 'Ketua negeri ialah tonggak pemerintahan. Dengan mengenalinya, kita memupuk sikap hormat dan taat setia.', 'Betul! Semua kad disusun dengan teliti.'),
(NULL, 'e2_n2_s4', 'hint', 'Pembantu Yang di-Pertua Negeri memerlukan dokumen yang betul.', NULL, NULL),
(222, NULL, 'hint', 'Cari dokumen yang menyenaraikan empat negeri bergelar Yang di-Pertua Negeri, iaitu dua di Semenanjung dan dua di Borneo. Singkirkan dokumen yang memasukkan negeri bersultan atau berraja.', 'Gelaran ketua negeri berbeza di Pulau Pinang, Melaka, Sarawak dan Sabah. Istiadat yang betul menunjukkan kita menghormati ketua negeri itu.', 'Betul! Dokumen yang tepat diserahkan.'),
(NULL, 'e2_n2_s5', 'hint', 'Hari kedua bermula di Selangor dan Negeri Sembilan. Satu nama membawa angka 1773.', NULL, NULL),
(223, NULL, 'hint', 'Piagam menyebut gabungan sembilan luak. Tahun itu pada abad ke-18. Pilihan abad ke-17 dan abad ke-19 bukan jawapannya.', 'Negeri Sembilan bermula pada 1773 daripada sembilan luak, dan perkataan negeri berasal daripada nagari. Namanya menyimpan sejarah gabungan dan alam.', 'Betul! Tahun piagam dicatat dalam kad pengacara.'),
(NULL, 'e2_n2_s6', 'hint', 'Pegawai Istiadat menemui nota Zahar di Melaka.', NULL, NULL),
(224, NULL, 'hint', 'Kata kunci ialah ''hujung''. Pilihan lain ialah nama lama bagi Pahang, Melaka dan Kedah.', 'Melaka berasal daripada Malakat dan pokok tempat Parameswara berehat, manakala Johor daripada Jauhar dan Ujong Tanah. Nama kedua-duanya dari perdagangan, legenda dan naskhah lama.', 'Betul! Nota Zahar berjaya dinyahkod.'),
(NULL, 'e2_n2_s7', 'hint', 'Fail ibu negeri dan bandar diraja di tengah dan selatan semenanjung dibetulkan.', NULL, NULL),
(225, NULL, 'hint', 'Satu ibu negeri tiada bandar diraja ditanda pada peta. Itulah negeri yang ketuanya Yang di-Pertua Negeri. Padankan tiga yang lain dahulu.', 'Ibu negeri ialah pusat pentadbiran, dan bandar diraja menyimpan warisan. Warisan itu perlu dipelihara.', 'Betul! Fail dipadankan semula.'),
(NULL, 'e2_n2_s8', 'hint', 'Zahar menukar label kaset empat lagu negeri.', NULL, NULL),
(226, NULL, 'hint', 'Padankan tajuk yang menyebut nama negeri dahulu, ''Melaka'' dan ''Johor''. Dua lagi menyebut ''Duli'' dan ''Yang di-Pertuan Besar''.', 'Lagu negeri ialah lambang kedaulatan. Lagu yang betul menunjukkan kita menghormati negeri itu.', 'Betul! Label dipasang semula.'),
(NULL, 'e2_n2_s9', 'hint', 'Perlis dan Perak memerlukan padanan dua cerita setiap satu.', NULL, NULL),
(227, NULL, 'hint', 'Dua kad berkait dengan Perlis (kelapa hanyut dan mandat Sultan) dan dua kad dengan Perak (berkilau dan timah). Baca kad kanan hingga habis.', 'Perlis dikaitkan dengan kelapa hanyut atau peroleh, dan Perak dengan kilatan ikan dan bijih timah. Nama itu datang daripada bahasa Siam, peristiwa dan alam.', 'Betul! Empat kad dipadankan.'),
(NULL, 'e2_n2_s10', 'hint', 'Dua negeri sekali gus. Kedah dan Pulau Pinang. Satu sampul tersembunyi dicari.', NULL, NULL),
(228, NULL, 'hint', 'Baca maksud pada kad kanan, ''Pulo Ka Satu'' dan ''Tanjong Penaga'' berkait dengan pulau, ''qadah'' dan ''kadaram'' berkait dengan Kedah. Buah pinang ialah dagangan.', 'Pulau Pinang bermula daripada Pulo Ka Satu, Tanjong Penaga dan pinang, manakala Kedah daripada kheddah, qadah atau kadaram. Nama datang daripada alam, perdagangan dan bahasa.', 'Betul! Sampul ditemui di bawah karung pinang.'),
(NULL, 'e2_n2_s11', 'hint', 'Dokumen ibu negeri dan bandar diraja utara dipilih dengan teliti.', NULL, NULL),
(229, NULL, 'hint', 'Cari dokumen yang betul untuk SEMUA empat negeri. Singkirkan dokumen yang menukar ibu negeri dengan bandar diraja atau menyilang antara negeri.', 'Di utara, ibu negeri ialah pusat pentadbiran dan bandar diraja menyimpan warisan sejarah. Kita jaga warisan itu.', 'Betul! Dokumen utara diserahkan.'),
(NULL, 'e2_n2_s12', 'hint', 'Lagu utara ditentukan melalui nota. Perlis dan ''Raja'' berkait.', NULL, NULL),
(230, NULL, 'hint', 'Nota menyebut ''Raja''. Hanya satu negeri di utara semenanjung bergelar Raja. Cari negeri itu antara pilihan.', 'Lagu negeri utara ialah lambang kemegahan. Tetamu dihormati apabila lagu yang betul dimainkan.', 'Betul! Lagu Perlis dimainkan untuk Raja.'),
(NULL, 'e2_n2_s13', 'hint', 'Hari terakhir sebelum istiadat. Pantai timur mempunyai tiga negeri dan enam cerita.', NULL, NULL),
(231, NULL, 'hint', 'Enam sebutan, tiga negeri. Pokok dan nama lama berkait dengan Pahang, taring dan pelangi dengan Terengganu, cahaya dan pokok pantai dengan Kelantan.', 'Pahang daripada mahang atau Inderapura, Terengganu daripada taring anu atau terangnya ganu, dan Kelantan daripada kilatan atau gelam hutan. Semuanya lahir daripada alam dan sejarah.', 'Betul! Peta Zahar ditemui di bawah batu.'),
(NULL, 'e2_n2_s14', 'hint', 'Ibu negeri dan bandar diraja pantai timur dipadankan melalui peta.', NULL, NULL),
(232, NULL, 'hint', 'Hanya satu negeri mempunyai dua kad, iaitu ibu negeri dan bandar diraja. Dua negeri lagi hanya mempunyai ibu negeri.', 'Ibu negeri ialah pusat pentadbiran, dan Pekan ialah bandar diraja Pahang. Warisan pantai timur dipelihara.', 'Betul! Kad dipadankan pada peta.'),
(NULL, 'e2_n2_s15', 'hint', 'Lagu pantai timur, iaitu satu tajuk dikongsi dua negeri, satu lagi milik Pahang.', NULL, NULL),
(233, NULL, 'hint', 'Cari tajuk yang menyebut ''Sultan'' dan ''Kami''. Tajuk yang menyebut ''Sabah'', ''Usia'' atau ''Melaka'' ialah lagu negeri lain.', 'Lagu negeri ialah lambang kemegahan. Terengganu dan Kelantan sama-sama bertajuk Selamat Sultan, tetapi tajuk yang sama tidak bermakna negeri yang sama.', 'Betul! Lagu Pahang berkumandang.'),
(NULL, 'e2_n2_s16', 'hint', 'Sabah dan Sarawak, iaitu dua negeri, dua nama, satu tahun penting.', NULL, NULL),
(234, NULL, 'hint', 'Surat menyebut tahun dokumen dan buah yang ditanam di pantai barat. Cari buah yang namanya hampir sama dengan nama negeri itu, dan tahun 1877.', 'Sarawak diambil daripada Sungai Serak atau cerava, iaitu antimoni, dan Sabah daripada pisang saba dalam dokumen 1877. Nama dikaitkan dengan galian dan makanan.', 'Betul! Surat berjaya dinyahkod.'),
(NULL, 'e2_n2_s17', 'hint', 'Borneo dan Wilayah Persekutuan, iaitu pusat pentadbiran dan lagu dipadankan malam sebelum istiadat.', NULL, NULL),
(235, NULL, 'hint', 'Baca setiap kad dengan teliti, iaitu dua kad ialah lagu, dua kad ialah ibu negeri, dan satu kad ialah lagu bagi Wilayah Persekutuan yang menyebut ''Maju''.', 'Ibu negeri ialah pusat pentadbiran, dan lagu negeri ialah lambang kemegahan. Identiti negeri patut dihormati.', 'Betul! Semua kad dan kaset dipadankan.'),
(NULL, 'e2_n2_s18', 'hint', 'Hari-H. Pegawai Istiadat menunjukkan bukti lambang negeri yang betul dan mendedahkan Zahar.', NULL, NULL),
(236, NULL, 'hint', 'Tiga lambang di pentas, iaitu bendera di sudut atas kanan gambar, jata di bahagian kanan tengah, dan radio yang bernyanyi di bahagian bawah sebelah kanan.', 'Setiap negeri ada bendera, lagu dan jata sebagai identiti. Mengenali lambang negeri menambah rasa cinta akan negara.', 'Berjaya! Zahar didedahkan dan majlis bermula dengan kad yang betul.'),
(NULL, 'e2_n3_s1', 'hint', 'Pengembaraan bermula di Sabah. Cop pertama bergantung pada nama negeri.', NULL, NULL),
(237, NULL, 'hint', 'Cari buah di kebun dan kertas yang ada angka tahun. Tiga kad, iaitu satu buah, satu dokumen dan satu tahun.', 'Sabah dikaitkan dengan pisang saba dan dokumen Maharajah of Sabah pada 1877. Cop Sabah berada di tanganku.', 'Betul! Cop Sabah pertama dalam pasport.'),
(NULL, 'e2_n3_s2', 'hint', 'Cop kedua di Sarawak. Surat berkait dengan sungai dan galian.', NULL, NULL),
(238, NULL, 'hint', 'Surat menyebut perubahan nama sungai kerana sejenis bijih. Cari pilihan yang menyebut sebatang sungai kecil menjadi sungai besar, dan bukan nama negeri lain.', 'Sarawak diambil daripada Sungai Serak dan cerava, iaitu antimoni. Cop Sarawak berada di tanganku.', 'Betul! Cop Sarawak ditekan.'),
(NULL, 'e2_n3_s3', 'hint', 'Cop Borneo bergantung pada ibu negeri, lagu dan ketua. Pasport dipenuhi.', NULL, NULL),
(239, NULL, 'hint', 'Satu gelaran bermula dengan ''Yang di-Pertua''. Dua bandar ialah ibu negeri. Dua tajuk ialah lagu negeri.', 'Di Sarawak dan Sabah, ibu negeri ialah pusat pentadbiran, lagu negeri ialah lambang kemegahan, dan ketua negeri ialah Yang di-Pertua Negeri. Dua cop Borneo sudah lengkap.', 'Betul! Dua cop Borneo lengkap.'),
(NULL, 'e2_n3_s4', 'hint', 'Cop ketiga, iaitu Wilayah Persekutuan. Tiga nama, tiga kisah.', NULL, NULL),
(240, NULL, 'hint', 'Cari dokumen yang betul bagi SEMUA tiga wilayah. Satu nama datang daripada lumpur, satu daripada labuhan kapal dan satu daripada seorang tokoh.', 'Kuala Lumpur bermaksud muara berlumpur, Labuan daripada labuhan, dan Putrajaya daripada Putra dan jaya. Cop ketiga berada di tanganku.', 'Betul! Pelancong mencatat penerangan yang tepat.'),
(NULL, 'e2_n3_s5', 'hint', 'Cop Wilayah Persekutuan, iaitu ketua, lagu dan ibu negeri.', NULL, NULL),
(241, NULL, 'hint', 'Nota menyebut wilayah yang ketuanya ialah Yang di-Pertuan Agong. Cari wilayah itu antara pilihan, bukan negeri yang bersultan.', 'Ketua Wilayah Persekutuan ialah Yang di-Pertuan Agong, lagunya Maju dan Sejahtera, dan ia tidak mempunyai ibu negeri. Cop Wilayah Persekutuan sudah lengkap.', 'Betul! Cop Wilayah Persekutuan ditekan.'),
(NULL, 'e2_n3_s6', 'hint', 'Cop Johor. Dua cerita, iaitu permata dan naskhah.', NULL, NULL),
(242, NULL, 'hint', 'Nota menyebut ''batu permata'' dalam bahasa Arab. Cari perkataan Arab itu, bukan Malakat, Mahang atau Kheddah.', 'Johor berasal daripada Jauhar, batu permata, atau Ujong Tanah dalam Sulalatus Salatin. Cop Johor berada di tanganku.', 'Betul! Cop Johor ditekan.'),
(NULL, 'e2_n3_s7', 'hint', 'Pusat, istana, lagu dan ketua Johor dipadankan.', NULL, NULL),
(243, NULL, 'hint', 'Padankan kad dengan jawapan untuk Johor, iaitu dua bandar, satu lagu dan satu gelaran. Johor Bahru ialah ibu negeri.', 'Johor Bahru ialah ibu negeri dan pusat pentadbiran, Bandar Maharani ialah bandar diraja, dan ketuanya Sultan. Cop Johor sudah lengkap.', 'Betul! Cop Johor lengkap.'),
(NULL, 'e2_n3_s8', 'hint', 'Cop Melaka. Pengembara menyiasat nama melalui nota.', NULL, NULL),
(244, NULL, 'hint', 'Nota menyebut binatang kecil putih yang menendang anjing. Cari binatang yang kecil, bukan gajah, harimau atau kijang.', 'Melaka berasal daripada Malakat, pokok tempat Parameswara berehat. Cop Melaka berada di tanganku.', 'Betul! Cop Melaka ditekan.'),
(NULL, 'e2_n3_s9', 'hint', 'Lagu Melaka. Ketua bergelar Yang di-Pertua Negeri.', NULL, NULL),
(245, NULL, 'hint', 'Cari tajuk yang menyebut ''Melaka'' dan ''Maju''. Tajuk lain ialah lagu Johor, Selangor atau Pulau Pinang.', 'Ibu negeri Melaka ialah Bandar Melaka, lagunya Melaka Maju Jaya, dan ketuanya Yang di-Pertua Negeri. Cop Melaka sudah lengkap.', 'Betul! Lagu Melaka berkumandang.'),
(NULL, 'e2_n3_s10', 'hint', 'Cop Negeri Sembilan. Nama berkait dengan angka sembilan.', NULL, NULL),
(246, NULL, 'hint', 'Empat kad, ''nagari'', 1773, dan dua luak. Satu bermaksud wilayah, satu ialah tahun, dua ialah nama luak.', 'Negeri Sembilan bermula daripada sembilan luak, dan perkataan negeri datang daripada nagari. Cop Negeri Sembilan berada di tanganku.', 'Betul! Cop Negeri Sembilan ditekan.'),
(NULL, 'e2_n3_s11', 'hint', 'Pusat, istana, lagu dan gelaran ketua Negeri Sembilan.', NULL, NULL),
(247, NULL, 'hint', 'Padankan kad dengan jawapan untuk Negeri Sembilan, iaitu ibu negeri, bandar diraja, lagu dan gelaran. Seremban ialah ibu negeri.', 'Seremban ialah pusat pentadbiran, Seri Menanti ialah bandar diraja dan ketuanya Yang di-Pertuan Besar. Cop Negeri Sembilan sudah lengkap.', 'Betul! Cop Negeri Sembilan lengkap.'),
(NULL, 'e2_n3_s12', 'hint', 'Dua negeri sekali gus. Selangor dan Pahang. Satu pokok dan satu serangga, satu pokok dan satu nama lama.', NULL, NULL),
(248, NULL, 'hint', 'Dua istilah berkait dengan Selangor (pokok kuala dan serangga). Dua istilah berkait dengan Pahang (pokok dan ''pura'').', 'Selangor dikaitkan dengan mentagau atau Selangur, manakala Pahang dengan mahang atau Inderapura. Dua cop sudah ada.', 'Betul! Dua cop ditekan.'),
(NULL, 'e2_n3_s13', 'hint', 'Selangor dan Pahang, iaitu dua ibu negeri, dua bandar diraja, dua lagu.', NULL, NULL),
(249, NULL, 'hint', 'Dua negeri sekali gus. Shah Alam dan Klang untuk Selangor, Kuantan dan Pekan untuk Pahang. Lagu, ''Duli'' untuk Selangor, ''Kami'' untuk Pahang.', 'Ibu negeri ialah pusat pentadbiran, bandar diraja menyimpan warisan, dan ketuanya Sultan. Cop Selangor dan Pahang sudah lengkap.', 'Betul! Dua cop lengkap.'),
(NULL, 'e2_n3_s14', 'hint', 'Pantai timur, iaitu dua negeri, empat petunjuk nama.', NULL, NULL),
(250, NULL, 'hint', 'Empat petunjuk nama dua negeri pantai timur, iaitu taring dan pelangi, cahaya dan pokok pantai. Baca maksud pada kad kanan.', 'Terengganu daripada taring anu atau terangnya ganu, dan Kelantan daripada kilatan atau gelam hutan. Nama kedua-duanya lahir daripada alam.', 'Betul! Cop pantai timur ditekan.'),
(NULL, 'e2_n3_s15', 'hint', 'Dua negeri berkongsi tajuk lagu ''Selamat Sultan''.', NULL, NULL),
(251, NULL, 'hint', 'Nota menyebut dua ibu negeri. Kuala Terengganu dan Kota Bharu. Dua negeri itu berkongsi tajuk lagu ''Selamat Sultan''. Singkirkan pilihan yang ada Pahang.', 'Terengganu dan Kelantan berkongsi tajuk lagu Selamat Sultan. Ibu negerinya Kuala Terengganu dan Kota Bharu, dan ketuanya Sultan. Cop pantai timur sudah lengkap.', 'Betul! Cop pantai timur lengkap.'),
(NULL, 'e2_n3_s16', 'hint', 'Dua negeri, iaitu Perak dan Pulau Pinang. Lima petunjuk.', NULL, NULL),
(252, NULL, 'hint', 'Lima petunjuk dua negeri. ''Kilatan'' dan ''timah'' berkait dengan Perak. ''Pulo Ka Satu'', ''Tanjong Penaga'' dan ''pinang'' berkait dengan Pulau Pinang.', 'Perak dikaitkan dengan kilatan ikan dan bijih timah putih, Pulau Pinang dengan Pulo Ka Satu, Tanjong Penaga dan pinang. Nama menunjukkan alam dan perdagangan.', 'Betul! Cop Perak dan Pulau Pinang ditekan.'),
(NULL, 'e2_n3_s17', 'hint', 'Perak dan Pulau Pinang, iaitu pusat, istana, lagu dan ketua.', NULL, NULL),
(253, NULL, 'hint', 'Cari dokumen yang betul bagi KEDUA-DUA negeri. Perak, iaitu Ipoh, Kuala Kangsar, Sultan, Pulau Pinang, George Town, bukan Sultan. Singkirkan pilihan yang bertukar gelaran.', 'Ipoh dan George Town ialah ibu negeri, manakala Kuala Kangsar ialah bandar diraja Perak. Cop Perak dan Pulau Pinang sudah lengkap.', 'Betul! Dokumen diserahkan.'),
(NULL, 'e2_n3_s18', 'hint', 'Dua negeri terakhir, iaitu Kedah dan Perlis. Lima padanan.', NULL, NULL),
(254, NULL, 'hint', 'Lima padanan untuk dua negeri. ''Kheddah'' dan ''qadah'' berkait dengan Kedah. ''Prow-lowy'' dan ''peroleh'' berkait dengan Perlis.', 'Kedah daripada kheddah, qadah atau kadaram, manakala Perlis daripada prow-lowy atau peroleh. Dua cop sudah ada.', 'Betul! Dua cop terakhir ditekan.'),
(NULL, 'e2_n3_s19', 'hint', 'Lagu Kedah dan Perlis. Ibu negeri dan bandar diraja disebut dalam Giliran Anda.', NULL, NULL),
(255, NULL, 'hint', 'Cari tajuk yang menyebut ''Sultan'' dan ''Mahkota''. Tajuk lain menyebut ''Aamiin'', ''Usia'' atau ''Negeri Kita''.', 'Alor Setar dan Anak Bukit, Kangar dan Arau, Sultan dan Raja. Cop utara sudah lengkap.', 'Betul! Lagu Kedah berkumandang.'),
(NULL, 'e2_n3_s20', 'hint', 'Cop terakhir. Pengembara menunjukkan bukti lambang negeri dan menemui halaman koyak.', NULL, NULL),
(256, NULL, 'hint', 'Tiga lambang di pentas, iaitu bendera di sudut atas kanan gambar, jata di bahagian kanan tengah, dan radio di bahagian bawah sebelah kanan.', 'Setiap negeri ada bendera, lagu dan jata sebagai identiti. Mengenali lambang negeri menambah rasa cinta akan negara.', 'Berjaya! Halaman koyak ditemui dan cop terakhir ditekan.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(21, 201, NULL, 'Aku Tok Penglipur Lara. Tugasku mencatat dan menurunkan cerita negeri, dan setiap negeri ada lebih daripada satu cerita yang mesti aku sebut dengan jujur, {nama}.', 1),
(21, 201, NULL, 'Aku belajar bahawa nama negeri, ketuanya, pusatnya dan lagunya menyimpan sejarah dan kemegahan. Mengenalinya menjadikan kita bangga akan warisan negeri.', 2),
(21, 201, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pencerita tua yang membawa sebuah buku kosong. Setiap negeri akan berbalah tentang ceritanya. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(28, 201, 'e2_n1_s1', 'Tok, datuk saya kata Perlis dari perkataan Siam. Orang sebelah kata dari peristiwa Raja Syed Hussin. Siapakah benar?', 1),
(18, 201, 'e2_n1_s1', 'Tok, kelapa itu hanyut dari hulu parit. Tulisan di catatan ini pun pudar.', 2),
(NULL, 201, 'e2_n1_s1', 'Kedua-duanya ada dalam catatan. Baca dahulu, usah teka.', 3),
(28, 201, 'e2_n1_s1', 'Jikalau Tok salah tulis, satu kampung akan menghafal yang salah.', 4),
(18, 201, 'e2_n1_s1', 'Selepas ini kita ke selatan, Tok. Di sana orang pernah memasang perangkap besar.', 5),
(28, 201, 'e2_n1_s1', 'Tok, apa lagi cerita tentang nama Perlis selain perkataan Siam itu?', 6),
(29, 201, 'e2_n1_s2', 'Kedah dari ''kheddah'', perangkap gajah! Datuk saya memburu gajah di sini.', 1),
(30, 201, 'e2_n1_s2', 'Salah! Dari ''qadah'', cawan berkaki yang pedagang Arab jual di Alam Melayu!', 2),
(18, 201, 'e2_n1_s2', 'Tok, di dinding itu ada tulisan Tamil. Nama dalam tulisan itu lain pula.', 3),
(NULL, 201, 'e2_n1_s2', 'Tiga catatan, tiga bahasa. Kita padankan agar tiada yang tersisih.', 4),
(18, 201, 'e2_n1_s2', 'Selepas ini kita ke pulau yang banyak pokok dan pinang, Tok.', 5),
(29, 201, 'e2_n1_s2', 'Tok, apa nama Kedah dalam tulisan Tamil itu?', 6),
(27, 201, 'e2_n1_s3', 'Orang Kedah panggil pulau ini Tanjong Penaga kerana banyak pokok penaga. Nama asalnya Pulo Ka Satu!', 1),
(30, 201, 'e2_n1_s3', 'Salah! Pulau pinang, buah pinang itu barang dagangan kami!', 2),
(56, 201, 'e2_n1_s3', 'Di Perak, nama negeri dari kilat ikan dalam air. Atau dari bijih timah putih berkilat!', 3),
(18, 201, 'e2_n1_s3', 'Tok, ada dua negeri di jeti ini. Usah bercampur.', 4),
(NULL, 201, 'e2_n1_s3', 'Padankan, agar tiada negeri bercampur.', 5),
(27, 201, 'e2_n1_s3', 'Tok, peribahasa apa untuk kenal negeri sendiri?', 6),
(40, 201, 'e2_n1_s4', 'Tok, murid-murid keliru. Mana ibu negeri dan mana bandar diraja?', 1),
(18, 201, 'e2_n1_s4', 'Tok, titik merah ialah ibu negeri dan titik kuning bandar diraja, kata legenda peta ini.', 2),
(NULL, 201, 'e2_n1_s4', 'Ibu negeri pusat pentadbiran. Bandar diraja ada warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.', 3),
(40, 201, 'e2_n1_s4', 'Jikalau tersilap, anak murid akan menghafal yang salah.', 4),
(18, 201, 'e2_n1_s4', 'Esok kita dengar radio kampung, Tok. Ada lagu yang dimainkan setiap pagi.', 5),
(18, 201, 'e2_n1_s4', 'Seingat saya, Kangar (Perlis) berpasangan dengan Arau, Alor Setar (Kedah) berpasangan dengan Anak Bukit, Ipoh (Perak) berpasangan dengan Kuala Kangsar.', 6),
(40, 201, 'e2_n1_s4', 'Tok, bagaimanakah kita memelihara istana atau bangunan pentadbiran lama?', 7),
(39, 201, 'e2_n1_s5', 'Tok, majlis bermula sekejap lagi. Lagu Kedah mesti dimainkan dahulu.', 1),
(18, 201, 'e2_n1_s5', 'Tok, ada kaset bertulis empat tajuk di atas rak.', 2),
(NULL, 201, 'e2_n1_s5', 'Tajuk lagu negeri tidak boleh ditukar. Itu lambang kemegahan.', 3),
(39, 201, 'e2_n1_s5', 'Jikalau saya main lagu negeri lain, tetamu akan rasa dihina.', 4),
(18, 201, 'e2_n1_s5', 'Selepas ini kita ke kuala sungai. Di sana ada bunyi pedagang lama, Tok.', 5),
(39, 201, 'e2_n1_s5', 'Tok, lagu Perak, Perlis dan Pulau Pinang pula, apa tajuknya?', 6),
(27, 201, 'e2_n1_s6', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau, lalu jadi Kuala Selangor.', 1),
(8, 201, 'e2_n1_s6', 'Bukan, dari serangga selangur yang banyak di sungai!', 2),
(54, 201, 'e2_n1_s6', 'Negeri kami dari sembilan luak. Kata ''negeri'' pun dari ''nagari''.', 3),
(18, 201, 'e2_n1_s6', 'Tok, ada tahun tertulis di piagam penghulu itu.', 4),
(NULL, 201, 'e2_n1_s6', 'Padankan, usah tinggalkan satu pun.', 5),
(8, 201, 'e2_n1_s6', 'Seingat saya, Nagari berpasangan dengan Wilayah dalam dialek Minangkabau.', 6),
(54, 201, 'e2_n1_s6', 'Tok, sebut luak-luak asal Negeri Sembilan itu.', 7),
(30, 201, 'e2_n1_s7', 'Melaka dari ''Malakat'', tempat pedagang berhimpun!', 1),
(8, 201, 'e2_n1_s7', 'Dari pokok tempat Parameswara berehat, ketika pelanduk putih kecil menendang anjing pemburuannya!', 2),
(55, 201, 'e2_n1_s7', 'Dan Johor dari ''jauhar'', batu permata. Dalam Sulalatus Salatin pula Ujong Tanah!', 3),
(18, 201, 'e2_n1_s7', 'Tok, empat cerita, dua negeri.', 4),
(NULL, 201, 'e2_n1_s7', 'Padankan, agar halaman buku tidak salah.', 5),
(55, 201, 'e2_n1_s7', 'Tok, ''Malakat'' itu daripada bahasa apa?', 6),
(40, 201, 'e2_n1_s8', 'Tok, fail ini habis bercampur. Saya hampir menghantar Klang sebagai ibu negeri.', 1),
(18, 201, 'e2_n1_s8', 'Tok, Klang ada istana dan bangunan lama. Ibu negerinya pusat pentadbiran.', 2),
(NULL, 201, 'e2_n1_s8', 'Bandar Melaka ialah ibu negeri. Peta tidak menandakan bandar diraja di sana.', 3),
(40, 201, 'e2_n1_s8', 'Jikalau tersilap, majlis tersasar.', 4),
(18, 201, 'e2_n1_s8', 'Esok kita dengar kaset lagi, Tok. Empat lagu dari empat negeri.', 5),
(18, 201, 'e2_n1_s8', 'Seingat saya, Shah Alam (Selangor) berpasangan dengan Klang.', 6),
(40, 201, 'e2_n1_s8', 'Tok, mengapakah ibu negeri berkembang?', 7),
(39, 201, 'e2_n1_s9', 'Tok, saya perlukan lagu Johor. Dua kaset ini kelihatan serupa.', 1),
(18, 201, 'e2_n1_s9', 'Tok, satu kaset ada nama pengganti. Pandang tajuknya betul-betul.', 2),
(NULL, 201, 'e2_n1_s9', 'Tajuk lagu Johor menyebut nama negerinya.', 3),
(39, 201, 'e2_n1_s9', 'Jikalau tersilap, Sultan Johor tersinggung.', 4),
(18, 201, 'e2_n1_s9', 'Sesungguhnya, kita ke pantai timur selepas ini. Di sana ada pelangi dan taring besar, kata orang.', 5),
(39, 201, 'e2_n1_s9', 'Tok, tiga lagu lain itu milik negeri mana?', 6),
(8, 201, 'e2_n1_s10', 'Pahang dari pokok mahang! Dalam Sulalatus Salatin ia Inderapura atau Pura, dan pura itu bandar.', 1),
(27, 201, 'e2_n1_s10', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong! Atau ''terangnya ganu'', pelangi!', 2),
(55, 201, 'e2_n1_s10', 'Kelantan dari ''kilatan'', cahaya terang yang orang Patani nampak. Orang pantai kata gelam hutan!', 3),
(18, 201, 'e2_n1_s10', 'Tok, enam cerita dalam satu pantai.', 4),
(NULL, 201, 'e2_n1_s10', 'Padankan satu persatu.', 5),
(27, 201, 'e2_n1_s10', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(55, 201, 'e2_n1_s10', 'Tok, ''kilatan'' itu cahaya yang dilihat oleh siapakah?', 7),
(40, 201, 'e2_n1_s11', 'Tok, empat kad ini bercampur. Pekan bukan pusat pentadbiran.', 1),
(18, 201, 'e2_n1_s11', 'Tok, Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(NULL, 201, 'e2_n1_s11', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(40, 201, 'e2_n1_s11', 'Jadi hanya Pahang ada kedua-duanya?', 4),
(18, 201, 'e2_n1_s11', 'Selepas ini lagu, Tok. Kata orang, dua negeri berkongsi tajuk yang sama.', 5),
(40, 201, 'e2_n1_s11', 'Tok, apa yang ada di bandar diraja?', 6),
(27, 201, 'e2_n1_s12', 'Lagu ini lagu negeri saya, ''Selamat Sultan''!', 1),
(8, 201, 'e2_n1_s12', 'Salah! Lagu negeri saya juga ''Selamat Sultan''!', 2),
(18, 201, 'e2_n1_s12', 'Tok, Pahang pun ada lagu, ''Allah Selamatkan Sultan Kami''.', 3),
(NULL, 201, 'e2_n1_s12', 'Semua benar. Ini nota yang mesti dinyahkod.', 4),
(18, 201, 'e2_n1_s12', 'Kita menyeberang laut selepas ini, Tok. Ke Borneo, ke tanah yang ada gunung.', 5),
(27, 201, 'e2_n1_s12', 'Tok, lagu Pahang itu tajuknya apa?', 6),
(55, 201, 'e2_n1_s13', 'Tok, orang tanya nama Sarawak dan Sabah. Dokumen lama bercampur.', 1),
(34, 201, 'e2_n1_s13', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian!', 2),
(18, 201, 'e2_n1_s13', 'Tok, ada logam ''cerava'' juga, panggilan Portugis.', 3),
(NULL, 201, 'e2_n1_s13', 'Pilih dokumen yang betul.', 4),
(55, 201, 'e2_n1_s13', 'Sabah tercatat dalam dokumen ''Maharajah of Sabah'' pada tahun tertentu, dan dikaitkan dengan sejenis buah.', 5),
(55, 201, 'e2_n1_s13', 'Tok, yang mana dokumen yang betul?', 6),
(8, 201, 'e2_n1_s14', 'Mengapakah ''Kuala Lumpur''? Bukankah bunyinya pelik?', 1),
(30, 201, 'e2_n1_s14', 'Dan mengapakah ''Labuan''?', 2),
(18, 201, 'e2_n1_s14', 'Tok, ada kotak ''Tahukah anda'' di buku. Tiga nama, tiga cerita.', 3),
(NULL, 201, 'e2_n1_s14', 'Padankan dahulu. Dan ingat, Wilayah Persekutuan tiada ibu negeri dan bandar diraja.', 4),
(30, 201, 'e2_n1_s14', 'Seingat saya, Kuala Lumpur berpasangan dengan Muara berlumpur akibat melombong bijih timah.', 5),
(34, 201, 'e2_n1_s14', 'Tok, siapakah yang bernama Putra pada Putrajaya itu?', 6),
(40, 201, 'e2_n1_s15', 'Ibu negeri kami Kuching. Pusat pentadbiran.', 1),
(53, 201, 'e2_n1_s15', 'Kami Kota Kinabalu, pusat pekerjaan dan pendidikan.', 2),
(18, 201, 'e2_n1_s15', 'Tok, di peta ada titik merah di Kuching dan Kota Kinabalu, namun tiada titik kuning.', 3),
(NULL, 201, 'e2_n1_s15', 'Peta hanya menanda ibu negeri bagi kedua-duanya.', 4),
(18, 201, 'e2_n1_s15', 'Selepas ini lagu terakhir, Tok. Satu tentang tanah air, satu tentang ibu pertiwi.', 5),
(53, 201, 'e2_n1_s15', 'Seingat saya, Ibu negeri berkembang kerana berpasangan dengan Pembangunan pentadbiran, kemudahan asas dan institusi pendidikan.', 6),
(40, 201, 'e2_n1_s15', 'Tok, bagaimanakah kita menghargai pusat pentadbiran dan kota warisan?', 7),
(39, 201, 'e2_n1_s16', 'Tok, saya perlukan lagu Sabah. Tiga kaset lagi bercampur.', 1),
(18, 201, 'e2_n1_s16', 'Tok, satu tajuk menyebut ''Tanah Airku''. Satu lagi ''Ibu Pertiwiku''.', 2),
(NULL, 201, 'e2_n1_s16', 'Satu daripada itu milik Sarawak. Satu lagi milik Sabah.', 3),
(39, 201, 'e2_n1_s16', 'Dan Wilayah Persekutuan?', 4),
(18, 201, 'e2_n1_s16', 'Selepas ini kita ke istana. Para ketua negeri telah tiba.', 5),
(18, 201, 'e2_n1_s16', 'Seingat saya, jawapannya ialah Sabah Tanah Airku.', 6),
(39, 201, 'e2_n1_s16', 'Tok, Ibu Pertiwiku dan Maju dan Sejahtera itu milik siapakah?', 7),
(40, 201, 'e2_n1_s17', 'Tok, ketua-ketua negeri akan tiba. Kad gelaran bercampur. Satu kesilapan dan kita memalukan negara.', 1),
(18, 201, 'e2_n1_s17', 'Tok, ada gambar upacara pertabalan di dinding. Setiap ketua negeri ada gelaran tersendiri.', 2),
(NULL, 201, 'e2_n1_s17', 'Ketua negeri tonggak utama pemerintahan. Gelaran yang berbeza menunjukkan keunikan negara kita.', 3),
(40, 201, 'e2_n1_s17', 'Dan ketua Wilayah Persekutuan? Siapakah dia?', 4),
(18, 201, 'e2_n1_s17', 'Selepas ini kita ke pentas pesta, Tok. Buku mesti dilengkapkan.', 5),
(18, 201, 'e2_n1_s17', 'Seingat saya, Sultan berpasangan dengan Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan, Yang di-Pertua Negeri berpasangan dengan Pulau Pinang, Melaka, Sarawak dan Sabah.', 6),
(40, 201, 'e2_n1_s17', 'Tok, mengapakah kita perlu mengenali ketua negeri?', 7),
(17, 201, 'e2_n1_s18', 'Tok, buku ini mencatat dua cerita bagi setiap negeri. Mengapakah?', 1),
(NULL, 201, 'e2_n1_s18', 'Kerana nama negeri dicatat secara lisan dan tulisan.', 2),
(18, 201, 'e2_n1_s18', 'Tok, ada tiga petunjuk di pentas, jata, bendera dan radio lagu negeri.', 3),
(17, 201, 'e2_n1_s18', 'Tok perlu tunjukkan kepada penonton. Ini lambang kemegahan dan kedaulatan negeri.', 4),
(NULL, 201, 'e2_n1_s18', '''Tak kenal maka tak cinta.'' Mengenali nama, bendera dan jata menyuburkan rasa sayang akan negara.', 5),
(17, 201, 'e2_n1_s18', 'Tok, mengapakah kita perlu menghormati lambang negeri?', 6),
(58, 202, NULL, 'Aku Pegawai Istiadat Negara. Tiga hari lagi majlis bermula dan seseorang cuba memalukan aku, {nama}. Setiap kad dan kaset mesti betul.', 1),
(58, 202, NULL, 'Aku belajar bahawa nama negeri, ketua, ibu negeri, lagu dan lambangnya ialah identiti. Satu kesilapan boleh memalukan sebuah negeri.', 2),
(58, 202, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang diburu waktu. Ada orang menyabot istiadat. Teliti setiap kad dan dengar bisikan Tok.', 3),
(57, 202, 'e2_n2_s1', 'Pegawai Istiadat, kad ketua Wilayah Persekutuan hilang. Tiga hari lagi istiadat. Tuan hamba sanggup?', 1),
(21, 202, 'e2_n2_s1', 'Dia tersenyum terlalu lebar. Perhatikan jarinya.', 2),
(NULL, 202, 'e2_n2_s1', 'Saya akan nyahkod nota sisa dalam fail ini.', 3),
(57, 202, 'e2_n2_s1', 'Jikalau tersilap, tuan hamba yang malu.', 4),
(21, 202, 'e2_n2_s1', 'Esok kita ke bilik penyusun gelaran. Banyak kad bakal bercampur.', 5),
(21, 202, 'e2_n2_s1', 'Seingat saya, jawapannya ialah Yang di-Pertuan Agong.', 6),
(57, 202, 'e2_n2_s1', 'Dan ibu negeri Wilayah Persekutuan pula, apa nama bandarnya?', 7),
(59, 202, 'e2_n2_s2', 'Pegawai, papan nama Kuala Lumpur, Labuan dan Putrajaya tercabut dan bercampur.', 1),
(21, 202, 'e2_n2_s2', 'Setiap nama ada kisahnya. Padankan, usah tebak.', 2),
(NULL, 202, 'e2_n2_s2', 'Siapakah yang membuka papan ini?', 3),
(59, 202, 'e2_n2_s2', 'Seseorang dengan kunci pejabat.', 4),
(21, 202, 'e2_n2_s2', 'Kunci itu bukan kunci biasa. Jejaknya ke selatan.', 5),
(21, 202, 'e2_n2_s2', 'Seingat saya, Kuala Lumpur berpasangan dengan Muara berlumpur akibat melombong bijih timah, Putrajaya berpasangan dengan Tunku Abdul Rahman Putra, jaya bermaksud kemenangan atau menuju ke puncak.', 6),
(59, 202, 'e2_n2_s2', 'Jadi Putrajaya diambil daripada seorang pemimpin?', 7),
(40, 202, 'e2_n2_s3', 'Gelaran ketua negeri bercampur. Sultan, Raja, Yang di-Pertuan Besar, Yang di-Pertua Negeri.', 1),
(21, 202, 'e2_n2_s3', 'Ketua negeri ialah tonggak pemerintahan. Gelaran berbeza menunjukkan keunikan negara kita.', 2),
(NULL, 202, 'e2_n2_s3', 'Satu kad salah dan satu negeri tersinggung.', 3),
(21, 202, 'e2_n2_s3', 'Usah serahkan kad kepadanya. Esok kita mohon pertolongan seorang pembantu Yang di-Pertua Negeri.', 4),
(21, 202, 'e2_n2_s3', 'Seingat saya, Sultan berpasangan dengan Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan, Yang di-Pertua Negeri berpasangan dengan Pulau Pinang, Melaka, Sarawak dan Sabah.', 5),
(57, 202, 'e2_n2_s3', 'Mengapakah gelaran itu penting? Saya boleh tolong susun.', 6),
(40, 202, 'e2_n2_s4', 'Tuan Pegawai, tuan saya ialah Yang di-Pertua Negeri. Saya perlukan dokumen senarai negeri yang menggunakan gelaran itu.', 1),
(21, 202, 'e2_n2_s4', 'Hati-hati. Dokumen palsu pun ada di atas meja.', 2),
(NULL, 202, 'e2_n2_s4', 'Saya semak sendiri.', 3),
(40, 202, 'e2_n2_s4', 'Jikalau salah, tuan saya tidak dijemput ke tempat yang benar.', 4),
(21, 202, 'e2_n2_s4', 'Esok kita ke Selangor. Seseorang meninggalkan jejak di kuala sungai.', 5),
(21, 202, 'e2_n2_s4', 'Seingat saya, jawapannya ialah Pulau Pinang, Melaka, Sarawak dan Sabah.', 6),
(40, 202, 'e2_n2_s4', 'Wilayah Persekutuan pula, siapakah ketuanya?', 7),
(27, 202, 'e2_n2_s5', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau.', 1),
(54, 202, 'e2_n2_s5', 'Negeri kami sembilan luak, dan ''negeri'' dari ''nagari''.', 2),
(21, 202, 'e2_n2_s5', 'Jejak Zahar berhenti di sini. Nyahkod piagam itu, mungkin dia meninggalkan sesuatu.', 3),
(NULL, 202, 'e2_n2_s5', 'Saya perlu nama yang tepat untuk kad pengacara.', 4),
(21, 202, 'e2_n2_s5', 'Selepas ini kita ke Melaka. Seseorang meninggalkan tanda di bawah sebatang pokok.', 5),
(54, 202, 'e2_n2_s5', 'Sebut luak asal Negeri Sembilan!', 6),
(30, 202, 'e2_n2_s6', 'Melaka dari Malakat, tempat pedagang berhimpun.', 1),
(8, 202, 'e2_n2_s6', 'Dari pokok tempat Parameswara berehat melihat pelanduk putih.', 2),
(21, 202, 'e2_n2_s6', 'Nota di akar ini milik Zahar. Nyahkod sebelum dia kembali.', 3),
(NULL, 202, 'e2_n2_s6', 'Ia menyebut Johor.', 4),
(21, 202, 'e2_n2_s6', 'Kita ke bilik pejabat daerah. Ada fail yang dicuri.', 5),
(8, 202, 'e2_n2_s6', 'Seingat saya, jawapannya ialah Ujong Tanah.', 6),
(30, 202, 'e2_n2_s6', 'Dan Jauhar? Apa maksudnya?', 7),
(40, 202, 'e2_n2_s7', 'Pegawai, fail ibu negeri dan bandar diraja bercampur selepas Zahar datang.', 1),
(21, 202, 'e2_n2_s7', 'Ibu negeri pusat pentadbiran. Bandar diraja ada istana, bangunan pembesar, kedai lama, muzium dan monumen.', 2),
(NULL, 202, 'e2_n2_s7', 'Saya padankan semula.', 3),
(40, 202, 'e2_n2_s7', 'Dan Bandar Melaka tiada bandar diraja pada peta.', 4),
(21, 202, 'e2_n2_s7', 'Lalu kaset lagu di bilik radio. Tolong periksa suis.', 5),
(21, 202, 'e2_n2_s7', 'Seingat saya, Shah Alam (Selangor) berpasangan dengan Klang, Seremban (Negeri Sembilan) berpasangan dengan Seri Menanti, Johor Bahru (Johor) berpasangan dengan Bandar Maharani.', 6),
(40, 202, 'e2_n2_s7', 'Mengapakah ibu negeri berkembang?', 7),
(39, 202, 'e2_n2_s8', 'Pegawai, kaset ini tiada label. Zahar baru keluar dari bilik ini.', 1),
(21, 202, 'e2_n2_s8', 'Lagu negeri lambang kemegahan. Padankan label dengan negeri.', 2),
(NULL, 202, 'e2_n2_s8', 'Tengah dan selatan, iaitu Selangor, Negeri Sembilan, Melaka, Johor.', 3),
(39, 202, 'e2_n2_s8', 'Jikalau tersilap, tetamu terhina.', 4),
(21, 202, 'e2_n2_s8', 'Esok kita ke utara. Ada sebuah peti pos yang menyimpan nota.', 5),
(21, 202, 'e2_n2_s8', 'Seingat saya, Duli Yang Maha Mulia berpasangan dengan Selangor, Melaka Maju Jaya berpasangan dengan Melaka.', 6),
(39, 202, 'e2_n2_s8', 'Mengapakah lagu negeri penting?', 7),
(28, 202, 'e2_n2_s9', 'Perlis dari ''prow-lowy'', kelapa hanyut. Ada juga cerita ''peroleh''.', 1),
(56, 202, 'e2_n2_s9', 'Perak dari kilatan ikan atau bijih timah putih berkilat.', 2),
(21, 202, 'e2_n2_s9', 'Nota di peti pos itu mempunyai empat kad. Padankan.', 3),
(NULL, 202, 'e2_n2_s9', 'Zahar hendak saya tersilap di hadapan tetamu.', 4),
(21, 202, 'e2_n2_s9', 'Jam hampir tengah hari. Sebuah jeti menanti.', 5),
(56, 202, 'e2_n2_s9', 'Seingat saya, Peroleh berpasangan dengan Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.', 6),
(28, 202, 'e2_n2_s9', 'Siapakah Raja Syed Hussin itu?', 7),
(30, 202, 'e2_n2_s10', 'Kedah dari ''qadah'', cawan dagang Arab. Orang kata juga dari ''kheddah'', perangkap gajah.', 1),
(27, 202, 'e2_n2_s10', 'Pulau ini dahulu Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga.', 2),
(21, 202, 'e2_n2_s10', 'Seseorang menyembunyikan sampul di jeti ini. Padankan nama-nama itu, pasti sampul itu berdekatan.', 3),
(NULL, 202, 'e2_n2_s10', 'Pinang juga barang dagangan penting.', 4),
(21, 202, 'e2_n2_s10', 'Maka selepas ini kita ke pejabat daerah. Pegawai itu mengesyaki Zahar.', 5),
(27, 202, 'e2_n2_s10', 'Seingat saya, Qadah berpasangan dengan Cawan atau gelas berkaki yang dijual pedagang Arab.', 6),
(27, 202, 'e2_n2_s10', 'Mengapakah pinang penting pada nama pulau?', 7),
(40, 202, 'e2_n2_s11', 'Pegawai Istiadat, saya perlukan dokumen ibu negeri dan bandar diraja Perlis, Kedah, Perak dan Pulau Pinang.', 1),
(21, 202, 'e2_n2_s11', 'Salah satu fail mempunyai cop Zahar. Berhati-hati.', 2),
(NULL, 202, 'e2_n2_s11', 'Saya semak setiap baris.', 3),
(40, 202, 'e2_n2_s11', 'Jikalau salah, kami menghantar jemputan ke bandar yang salah.', 4),
(21, 202, 'e2_n2_s11', 'Selepas ini kita periksa kaset lagu utara. Zahar belum selesai.', 5),
(21, 202, 'e2_n2_s11', 'Seingat saya, jawapannya ialah Kangar dan Arau, Alor Setar dan Anak Bukit, Ipoh dan Kuala Kangsar, George Town.', 6),
(40, 202, 'e2_n2_s11', 'Mengapakah bandar diraja penting?', 7),
(39, 202, 'e2_n2_s12', 'Kaset ini bertajuk ''Aamiin-Aamiin''. Tidak ada label negeri.', 1),
(21, 202, 'e2_n2_s12', 'Nyahkod nota ini. Satu negeri di utara sahaja memiliki lagu itu.', 2),
(NULL, 202, 'e2_n2_s12', 'Di negeri itu ketuanya bergelar Raja.', 3),
(39, 202, 'e2_n2_s12', 'Dan Perak, Kedah, Pulau Pinang?', 4),
(21, 202, 'e2_n2_s12', 'Kita ke pantai timur esok. Zahar telah ke sana awal.', 5),
(39, 202, 'e2_n2_s12', 'Lagu Perak, Kedah dan Pulau Pinang itu tajuknya apa?', 6),
(27, 202, 'e2_n2_s13', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong. Ada juga ''terangnya ganu'', pelangi.', 1),
(8, 202, 'e2_n2_s13', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura, bandar.', 2),
(55, 202, 'e2_n2_s13', 'Kelantan dari ''kilatan'', cahaya terang. Orang pantai kata gelam hutan.', 3),
(21, 202, 'e2_n2_s13', 'Padankan setiap cerita. Peta Zahar tentu menyembunyikan sesuatu di sana.', 4),
(21, 202, 'e2_n2_s13', 'Selepas ini kita ke bilik peta. Empat nama bandar akan bercampur.', 5),
(55, 202, 'e2_n2_s13', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(55, 202, 'e2_n2_s13', 'Kilatan itu cahaya yang dilihat oleh siapakah?', 7),
(40, 202, 'e2_n2_s14', 'Pegawai Istiadat, empat kad bercampur. Pekan bukan pusat pentadbiran.', 1),
(21, 202, 'e2_n2_s14', 'Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(NULL, 202, 'e2_n2_s14', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(40, 202, 'e2_n2_s14', 'Siapakah yang mengusik kad ini?', 4),
(21, 202, 'e2_n2_s14', 'Esok pagi kita ke radio terakhir. Zahar tidak akan berhenti.', 5),
(40, 202, 'e2_n2_s14', 'Bagaimanakah kita memelihara istana lama?', 6),
(39, 202, 'e2_n2_s15', 'Pegawai Istiadat, dua negeri kongsi tajuk ''Selamat Sultan''. Saya tidak hendak tersilap, jadi saya perlukan lagu Pahang.', 1),
(21, 202, 'e2_n2_s15', 'Ketua Pahang bergelar Sultan, dan lagunya menyebut ''Kami''.', 2),
(NULL, 202, 'e2_n2_s15', 'Saya pilih dengan teliti.', 3),
(39, 202, 'e2_n2_s15', 'Jikalau tersilap, Sultan Pahang tersinggung.', 4),
(21, 202, 'e2_n2_s15', 'Esok pagi kita ke Borneo, ke dua negeri yang jauh. Zahar menanti di sana.', 5),
(21, 202, 'e2_n2_s15', 'Seingat saya, jawapannya ialah Allah Selamatkan Sultan Kami.', 6),
(39, 202, 'e2_n2_s15', 'Dan ''Selamat Sultan'' itu lagu negeri mana?', 7),
(28, 202, 'e2_n2_s16', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian.', 1),
(27, 202, 'e2_n2_s16', 'Atau ''cerava'', logam antimoni, panggilan Portugis.', 2),
(21, 202, 'e2_n2_s16', 'Surat ini dari Sabah. Nyahkod, kerana tarikh di dalamnya penting.', 3),
(NULL, 202, 'e2_n2_s16', 'Ada dokumen bertajuk ''Maharajah of Sabah''.', 4),
(21, 202, 'e2_n2_s16', 'Esok pagi Hari-H. Zahar akan membuat langkah terakhir.', 5),
(27, 202, 'e2_n2_s16', 'Seingat saya, jawapannya ialah 1877 dan pisang saba.', 6),
(28, 202, 'e2_n2_s16', 'Dan nama Sarawak itu bagaimanakah?', 7),
(40, 202, 'e2_n2_s17', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(53, 202, 'e2_n2_s17', 'Kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(21, 202, 'e2_n2_s17', 'Wilayah Persekutuan pun ada lagu. Maju dan Sejahtera. Padankan semuanya.', 3),
(NULL, 202, 'e2_n2_s17', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(21, 202, 'e2_n2_s17', 'Esok pagi Hari-H. Dalam gelap, Zahar menuju dewan istiadat.', 5),
(40, 202, 'e2_n2_s17', 'Mengapakah kami wajar menghormati lambang negeri?', 6),
(60, 202, 'e2_n2_s18', 'Pegawai Istiadat, majlis bermula. Tetamu menunggu.', 1),
(57, 202, 'e2_n2_s18', 'Saya telah menukar semua kad tuan hamba. Tuan hamba akan memalukan negara.', 2),
(21, 202, 'e2_n2_s18', 'Dia mengaku sendiri. Tunjukkan bukti bahawa semuanya benar, iaitu jata, bendera dan radio lagu.', 3),
(NULL, 202, 'e2_n2_s18', 'Maka setiap negeri ada bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(60, 202, 'e2_n2_s18', 'Mengapakah kita wajar menghormati lambang negeri?', 5),
(26, 203, NULL, 'Aku Pengembara Warisan. Pasportku kosong dan setiap penjaga cop hanya memberi cop jika aku tahu fakta yang betul, {nama}.', 1),
(26, 203, NULL, 'Aku belajar bahawa setiap negeri ada nama, ketua, pusat, lagu dan lambang yang menjadi kebanggaannya. Kenangan perjalanan lebih berharga daripada cop.', 2),
(26, 203, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengembara yang membawa pasport kosong. Di setiap wilayah ada penjaga cop yang berbalah dengan penduduk. Hanya fakta betul membuka cop.', 3),
(17, 203, 'e2_n3_s1', 'Pengembara, pasport tuan hamba kosong. Penjaga cop Sabah di pondok itu.', 1),
(31, 203, 'e2_n3_s1', 'Cop Sabah hanya untuk yang tahu mengapakah negeri ini bernama Sabah.', 2),
(NULL, 203, 'e2_n3_s1', 'Saya akan padankan fakta dahulu agar tidak bercakap kosong.', 3),
(17, 203, 'e2_n3_s1', 'Pondok ini ada pisang dan satu dokumen tua. Teliti.', 4),
(17, 203, 'e2_n3_s1', 'Selepas ini kita ke tebing sungai di tanah jiran. Ada logam dan bijih menanti.', 5),
(31, 203, 'e2_n3_s1', 'Apa itu pisang saba?', 6),
(31, 203, 'e2_n3_s2', 'Surat ini bakal membuka cop Sarawak. Baca.', 1),
(17, 203, 'e2_n3_s2', 'Dua cerita bersaing di sini, iaitu sungai dan logam.', 2),
(NULL, 203, 'e2_n3_s2', 'Saya nyahkod ayat demi ayat.', 3),
(31, 203, 'e2_n3_s2', 'Nama Sarawak ada hubungan dengan Sungai Serak.', 4),
(17, 203, 'e2_n3_s2', 'Esok kita bertemu pusat-pusat pentadbiran Borneo.', 5),
(31, 203, 'e2_n3_s2', 'Dan cerita Portugis? Apa maksudnya?', 6),
(40, 203, 'e2_n3_s3', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(53, 203, 'e2_n3_s3', 'Ibu negeri kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(17, 203, 'e2_n3_s3', 'Ketua mereka bergelar Yang di-Pertua Negeri.', 3),
(NULL, 203, 'e2_n3_s3', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(17, 203, 'e2_n3_s3', 'Kita menyeberang ke Labuan, wilayah yang bermula dengan perkataan ''labuh''.', 5),
(53, 203, 'e2_n3_s3', 'Siapakah ketua Wilayah Persekutuan?', 6),
(148, 203, 'e2_n3_s4', 'Tiga wilayah, tiga nama. Pelancong sedang menunggu penerangan saya.', 1),
(17, 203, 'e2_n3_s4', 'Nama Putrajaya ada Putra dan jaya. Dengar baik-baik.', 2),
(NULL, 203, 'e2_n3_s4', 'Saya pilih dokumen yang betul.', 3),
(148, 203, 'e2_n3_s4', 'Jikalau tersalah, pelancong menyangka kami tidak mengenali negara sendiri.', 4),
(17, 203, 'e2_n3_s4', 'Maka selepas ini kita periksa kad ketua dan lagu wilayah.', 5),
(148, 203, 'e2_n3_s4', 'Wilayah Persekutuan terdiri daripada apa?', 6),
(31, 203, 'e2_n3_s5', 'Cop ini mahukan tiga fakta, iaitu ketua, lagu dan ibu negeri.', 1),
(17, 203, 'e2_n3_s5', 'Wilayah Persekutuan bukan negeri biasa. Ketuanya lebih tinggi daripada Sultan.', 2),
(NULL, 203, 'e2_n3_s5', 'Nota ini ada petunjuk.', 3),
(31, 203, 'e2_n3_s5', 'Baca dengan teliti.', 4),
(17, 203, 'e2_n3_s5', 'Kita menuju selatan ke sebuah negeri yang bermula dengan perkataan batu permata.', 5),
(31, 203, 'e2_n3_s5', 'Apa ketua Wilayah Persekutuan dan ibu negerinya?', 6),
(30, 203, 'e2_n3_s6', 'Johor dari ''jauhar'', batu permata bernilai!', 1),
(55, 203, 'e2_n3_s6', 'Dalam Sulalatus Salatin ia Ujong Tanah!', 2),
(31, 203, 'e2_n3_s6', 'Cop Johor untuk yang menyelesaikan nota ini.', 3),
(17, 203, 'e2_n3_s6', 'Perhatikan batu berkilau dan naskhah di atas meja.', 4),
(17, 203, 'e2_n3_s6', 'Selepas ini kita padankan pusat dan istana Johor.', 5),
(30, 203, 'e2_n3_s6', 'Jauhar itu bahasa apa?', 6),
(40, 203, 'e2_n3_s7', 'Ibu negeri Johor Bahru, bandar diraja Bandar Maharani.', 1),
(17, 203, 'e2_n3_s7', 'Titik merah pusat pentadbiran, titik kuning istana dan warisan.', 2),
(40, 203, 'e2_n3_s7', 'Lagu kami Lagu Bangsa Johor. Ketua kami bergelar Sultan.', 3),
(NULL, 203, 'e2_n3_s7', 'Saya padankan semuanya.', 4),
(17, 203, 'e2_n3_s7', 'Esok kita ke Melaka. Ada sebatang pokok dan seekor pelanduk.', 5),
(40, 203, 'e2_n3_s7', 'Mengapakah bandar diraja penting?', 6),
(8, 203, 'e2_n3_s8', 'Melaka dari pokok tempat Parameswara berehat!', 1),
(30, 203, 'e2_n3_s8', 'Dari ''Malakat'', perhimpunan pedagang!', 2),
(31, 203, 'e2_n3_s8', 'Baca nota di akar pokok ini.', 3),
(17, 203, 'e2_n3_s8', 'Nota ini menyebut seekor binatang kecil dan seekor anjing.', 4),
(17, 203, 'e2_n3_s8', 'Selepas ini kita dengar kaset di bilik radio.', 5),
(30, 203, 'e2_n3_s8', 'Dan Malakat itu apa maksudnya?', 6),
(39, 203, 'e2_n3_s9', 'Lagu Melaka mesti dimainkan sebelum Yang di-Pertua Negeri tiba.', 1),
(17, 203, 'e2_n3_s9', 'Ketua Melaka bergelar Yang di-Pertua Negeri. Ibu negerinya Bandar Melaka.', 2),
(NULL, 203, 'e2_n3_s9', 'Saya pilih kaset yang benar.', 3),
(39, 203, 'e2_n3_s9', 'Jikalau salah, ketua kami tersinggung.', 4),
(17, 203, 'e2_n3_s9', 'Ketahuilah, selepas ini ke negeri yang bernama dari ''nagari''.', 5),
(17, 203, 'e2_n3_s9', 'Seingat saya, jawapannya ialah Melaka Maju Jaya.', 6),
(39, 203, 'e2_n3_s9', 'Ibu negeri Melaka di mana?', 7),
(54, 203, 'e2_n3_s10', 'Negeri kami terbentuk daripada sembilan luak.', 1),
(31, 203, 'e2_n3_s10', 'Padankan fakta, usah teka.', 2),
(17, 203, 'e2_n3_s10', 'Ada satu tahun dan satu perkataan Minangkabau.', 3),
(NULL, 203, 'e2_n3_s10', 'Saya cuba.', 4),
(17, 203, 'e2_n3_s10', 'Lalu kita cari pusat dan istana Negeri Sembilan.', 5),
(54, 203, 'e2_n3_s10', 'Sebut sembilan luak itu!', 6),
(58, 203, 'e2_n3_s11', 'Ibu negeri Seremban, bandar diraja Seri Menanti.', 1),
(17, 203, 'e2_n3_s11', 'Ketua Negeri Sembilan bergelar Yang di-Pertuan Besar.', 2),
(NULL, 203, 'e2_n3_s11', 'Lagu mereka Berkatlah Yang di-Pertuan Besar.', 3),
(58, 203, 'e2_n3_s11', 'Padankan semuanya.', 4),
(17, 203, 'e2_n3_s11', 'Sesungguhnya, selepas ini kita ke Selangor dan Pahang, dua negeri berjiran dengan kisah nama masing-masing.', 5),
(58, 203, 'e2_n3_s11', 'Mengapakah menghormati ketua negeri penting?', 6),
(27, 203, 'e2_n3_s12', 'Selangor dari pokok mentagau. Pedagang menyebut kuala selangau.', 1),
(8, 203, 'e2_n3_s12', 'Atau dari serangga selangur.', 2),
(31, 203, 'e2_n3_s12', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura.', 3),
(17, 203, 'e2_n3_s12', 'Pura bermaksud bandar atau pekan.', 4),
(17, 203, 'e2_n3_s12', 'Lalu kita menuju pusat dan istana kedua-dua negeri.', 5),
(31, 203, 'e2_n3_s12', 'Apa maksud pura?', 6),
(40, 203, 'e2_n3_s13', 'Ibu negeri Shah Alam, bandar diraja Klang. Lagu kami Duli Yang Maha Mulia.', 1),
(53, 203, 'e2_n3_s13', 'Ibu negeri Kuantan, bandar diraja Pekan. Lagu kami Allah Selamatkan Sultan Kami.', 2),
(17, 203, 'e2_n3_s13', 'Kedua-dua ketua bergelar Sultan.', 3),
(NULL, 203, 'e2_n3_s13', 'Saya padankan satu per satu.', 4),
(17, 203, 'e2_n3_s13', 'Kita ke pantai timur. Pelangi menunggu selepas hujan.', 5),
(40, 203, 'e2_n3_s13', 'Apa gelaran ketua kedua-dua negeri?', 6),
(27, 203, 'e2_n3_s14', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong, atau ''terangnya ganu'', pelangi.', 1),
(55, 203, 'e2_n3_s14', 'Kelantan dari ''kilatan'', cahaya terang yang dilihat orang Patani, atau dari gelam hutan.', 2),
(17, 203, 'e2_n3_s14', 'Padankan kesemuanya, satu per satu.', 3),
(NULL, 203, 'e2_n3_s14', 'Saya bergerak.', 4),
(17, 203, 'e2_n3_s14', 'Selepas ini kita periksa lagu dan pusat pantai timur.', 5),
(55, 203, 'e2_n3_s14', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(27, 203, 'e2_n3_s14', 'Gading apa itu sebenarnya?', 7),
(31, 203, 'e2_n3_s15', 'Dua negeri di sini kongsi tajuk lagu yang sama. Nota ini menjelaskannya.', 1),
(17, 203, 'e2_n3_s15', 'Ibu negeri satu ialah Kuala Terengganu, satu lagi Kota Bharu. Tiada bandar diraja ditanda pada peta.', 2),
(NULL, 203, 'e2_n3_s15', 'Saya nyahkod.', 3),
(31, 203, 'e2_n3_s15', 'Ketua kedua-dua negeri bergelar Sultan.', 4),
(17, 203, 'e2_n3_s15', 'Kita ke barat. Sebuah lombong menunggu.', 5),
(31, 203, 'e2_n3_s15', 'Ibu negeri Terengganu dan Kelantan?', 6),
(56, 203, 'e2_n3_s16', 'Perak dari kilatan ikan, atau bijih timah putih berkilat!', 1),
(27, 203, 'e2_n3_s16', 'Pulau ini Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga, bersempena pokok penaga.', 2),
(30, 203, 'e2_n3_s16', 'Pinang juga bahan dagangan penting.', 3),
(17, 203, 'e2_n3_s16', 'Padankan kesemuanya. Penjaga cop menunggu.', 4),
(17, 203, 'e2_n3_s16', 'Selepas ini kita periksa dokumen pusat utara.', 5),
(30, 203, 'e2_n3_s16', 'Mengapakah pinang penting pada nama pulau?', 6),
(40, 203, 'e2_n3_s17', 'Pengembara, saya perlukan dokumen ibu negeri, bandar diraja, lagu dan ketua bagi Perak dan Pulau Pinang.', 1),
(17, 203, 'e2_n3_s17', 'Ketua Perak bergelar Sultan. Ketua Pulau Pinang bergelar Yang di-Pertua Negeri.', 2),
(NULL, 203, 'e2_n3_s17', 'Saya pilih yang betul.', 3),
(40, 203, 'e2_n3_s17', 'Dokumen lain bercampur.', 4),
(17, 203, 'e2_n3_s17', 'Kita ke dua negeri terakhir di utara.', 5),
(40, 203, 'e2_n3_s17', 'Apa lagu Pulau Pinang?', 6),
(29, 203, 'e2_n3_s18', 'Kedah dari ''kheddah'', perangkap gajah.', 1),
(30, 203, 'e2_n3_s18', 'Dari ''qadah'', cawan berkaki. Ada juga ''kadaram'' atau ''kalagam'' dalam tulisan Tamil.', 2),
(28, 203, 'e2_n3_s18', 'Perlis dari ''prow-lowy'', kelapa hanyut, atau dari ''peroleh''.', 3),
(17, 203, 'e2_n3_s18', 'Padankan semuanya.', 4),
(17, 203, 'e2_n3_s18', 'Cop terakhir. Perlis ialah negeri paling hujung utara.', 5),
(28, 203, 'e2_n3_s18', 'Seingat saya, Peroleh berpasangan dengan Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.', 6),
(28, 203, 'e2_n3_s18', 'Siapakah Raja Syed Hussin itu?', 7),
(39, 203, 'e2_n3_s19', 'Lagu Kedah atau lagu Perlis, Pengembara? Saya perlukan Kedah dahulu.', 1),
(17, 203, 'e2_n3_s19', 'Ketua Kedah bergelar Sultan, ketua Perlis bergelar Raja. Kangar dan Arau, Alor Setar dan Anak Bukit.', 2),
(NULL, 203, 'e2_n3_s19', 'Saya pilih kaset Kedah.', 3),
(39, 203, 'e2_n3_s19', 'Jikalau tersilap, Raja Perlis tersinggung.', 4),
(17, 203, 'e2_n3_s19', 'Pasport hampir penuh. Satu cop lagi menanti di Wilayah Persekutuan.', 5),
(39, 203, 'e2_n3_s19', 'Lagu Perlis dan ibu negeri serta bandar diraja?', 6),
(31, 203, 'e2_n3_s20', 'Cop ini bukan untuk satu negeri. Ia untuk bendera, jata dan lagu semua negeri.', 1),
(17, 203, 'e2_n3_s20', 'Halaman yang koyak bukan hilang. Ia tersembunyi di pentas.', 2),
(NULL, 203, 'e2_n3_s20', 'Saya cari bukti lambang negeri dahulu.', 3),
(31, 203, 'e2_n3_s20', 'Setiap negeri mempunyai bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(17, 203, 'e2_n3_s20', 'Kita sampai. Sahabat sebenar bukan cop, namun kenangan.', 5),
(31, 203, 'e2_n3_s20', 'Mengapakah kita wajar menghormati lambang negeri?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (2, 2)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(201, 2, 'Apakah maksud perkataan Siam prow-lowy yang dikaitkan dengan asal nama Perlis?', 'Air jernih', 'Kelapa hanyut', 'Pokok tinggi', 'Sungai besar', 'B', 'Ia berkaitan dengan buah di laut.', 'Prow-lowy dalam bahasa Siam bermaksud kelapa hanyut.'),
(202, 2, 'Nama Kedah dikatakan berasal daripada perkataan Kheddah yang bermaksud...', 'perangkap gajah', 'cawan berkaki', 'batu permata', 'kilatan ikan', 'A', 'Haiwan besar di hutan.', 'Kheddah bermaksud perangkap gajah. Perkataan Arab Qadah pula bermaksud cawan atau gelas berkaki.'),
(203, 2, 'Apakah nama asal Pulau Pinang?', 'Tanjong Pinang', 'Pulau Pinang Lama', 'Pulo Pinang Besar', 'Pulo Ka Satu', 'D', 'Nama asalnya bermula dengan Pulo.', 'Nama asal Pulau Pinang ialah Pulo Ka Satu. Orang Melayu Kedah menggelarnya Tanjong Penaga.'),
(204, 2, 'Nama Perak dikatakan bersempena dengan...', 'pokok mahang', 'sembilan luak', 'kilatan ikan di dalam air', 'pelanduk putih', 'C', 'Ia berkilau seperti logam.', 'Perak dikaitkan dengan kilatan ikan di dalam air atau bijih timah putih yang berkilat.'),
(205, 2, 'Pokok apakah yang dikaitkan dengan asal nama Selangor?', 'Pokok mahang', 'Pokok mentagau', 'Pokok penaga', 'Pokok Melaka', 'B', 'Ia banyak di kuala sungai.', 'Pokok mentagau di kuala sungai menjadi kuala selangau, kemudian Kuala Selangor.'),
(206, 2, 'Negeri Sembilan terbentuk daripada gabungan sembilan buah...', 'luak', 'daerah', 'pulau', 'mukim', 'A', 'Ia istilah Minangkabau.', 'Negeri Sembilan terbentuk daripada sembilan luak pada tahun 1773.'),
(207, 2, 'Manakah antara berikut ialah luak asal Negeri Sembilan?', 'Kedah', 'Terengganu', 'Kota Bharu', 'Sungai Ujong', 'D', 'Ia luak yang namanya mengandungi sungai.', 'Luak asal termasuk Sungai Ujong, Jelebu, Rembau, Johol, Jelai, Ulu Pahang, Naning, Segamat dan Klang.'),
(208, 2, 'Mengikut sumber Arab, nama Melaka disebut Malakat yang bermaksud...', 'batu permata', 'tempat kapal singgah', 'perhimpunan para pedagang', 'pelangi', 'C', 'Pedagang Arab menggunakan nama ini.', 'Malakat bermaksud perhimpunan para pedagang.'),
(209, 2, 'Apakah maksud Jauhar yang dikaitkan dengan asal nama Johor?', 'Perangkap gajah', 'Batu permata yang bernilai', 'Pokok mahang', 'Pisang saba', 'B', 'Perkataan Arab.', 'Jauhar ialah perkataan Arab bagi batu permata yang bernilai.'),
(210, 2, 'Apakah nama Pahang dalam Sulalatus Salatin?', 'Inderapura atau Pura', 'Ujong Tanah', 'Malakat', 'Kadaram', 'A', 'Pura bermaksud bandar.', 'Dalam Sulalatus Salatin, Pahang dikenali sebagai Inderapura atau Pura.'),
(211, 2, 'Nama Terengganu dikatakan berasal daripada sebutan taring anu yang dijumpai di...', 'Pulau Pinang', 'Pulau Langkawi', 'Pulau Labuan', 'Pulau Duyong', 'D', 'Ia pulau di Terengganu.', 'Taring besar seperti gading gajah dijumpai di Pulau Duyong.'),
(212, 2, 'Nama Kelantan dikatakan berasal daripada perkataan kilatan yang dilihat oleh masyarakat...', 'Minangkabau', 'Siam', 'Melayu Patani', 'Jawa', 'C', 'Mereka dari selatan Thailand.', 'Kilatan ialah cahaya terang yang dilihat oleh masyarakat Melayu Patani.'),
(213, 2, 'Sarawak dikaitkan dengan Sungai Serak dan sejenis galian bijih yang disebut...', 'timah', 'sarawak', 'emas', 'besi', 'B', 'Nama galian itu sama dengan nama negeri.', 'Sungai Serak berubah menjadi Sungai Sarawak sempena bijih sarawak.'),
(214, 2, 'Nama Sabah dikaitkan dengan...', 'pisang saba', 'pokok mahang', 'pokok penaga', 'buah pinang', 'A', 'Ia ditanam di pantai barat.', 'Pisang saba banyak ditanam di pantai barat Sabah.'),
(215, 2, 'Apakah asal nama Kuala Lumpur?', 'Pokok mentagau', 'Perhimpunan pedagang', 'Batu permata', 'Muara sungai berlumpur akibat melombong bijih timah', 'D', 'Sungai Gombak dan Klang.', 'Kuala Lumpur dikaitkan dengan muara yang berlumpur akibat melombong bijih timah.'),
(216, 2, 'Nama Putrajaya bersempena dengan nama...', 'Tun Abdul Razak', 'Tun Hussein Onn', 'Tunku Abdul Rahman Putra', 'Tun Mahathir', 'C', 'Perdana Menteri pertama.', 'Putra daripada Tunku Abdul Rahman Putra; jaya bermaksud kemenangan.'),
(217, 2, 'Labuan dikatakan berasal daripada perkataan labuhan yang bermaksud...', 'batu permata', 'tempat persinggahan kapal', 'pokok mahang', 'perangkap gajah', 'B', 'Kapal berhenti di sini.', 'Labuhan ialah tempat persinggahan kapal.'),
(218, 2, 'Apakah gelaran ketua negeri di Perlis?', 'Raja', 'Sultan', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'A', 'Hanya satu negeri menggunakannya.', 'Perlis menggunakan gelaran Raja.'),
(219, 2, 'Apakah gelaran ketua negeri bagi negeri Selangor, Johor dan Pahang?', 'Raja', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'Sultan', 'D', 'Tujuh negeri menggunakannya.', 'Sultan digunakan di Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan.'),
(220, 2, 'Negeri manakah yang ketuanya bergelar Yang di-Pertuan Besar?', 'Perlis', 'Melaka', 'Negeri Sembilan', 'Sabah', 'C', 'Negeri bersejarah dengan sembilan luak.', 'Yang di-Pertuan Besar digunakan di Negeri Sembilan.'),
(221, 2, 'Manakah empat negeri yang ketuanya bergelar Yang di-Pertua Negeri?', 'Perlis, Kedah, Perak dan Johor', 'Pulau Pinang, Melaka, Sarawak dan Sabah', 'Selangor, Pahang, Kelantan dan Terengganu', 'Negeri Sembilan, Melaka, Johor dan Sabah', 'B', 'Dua di Semenanjung dan dua di Borneo.', 'Yang di-Pertua Negeri digunakan di Pulau Pinang, Melaka, Sarawak dan Sabah.'),
(222, 2, 'Siapakah ketua negeri bagi Wilayah Persekutuan?', 'Yang di-Pertuan Agong', 'Sultan Selangor', 'Perdana Menteri', 'Yang di-Pertua Negeri', 'A', 'Pemerintah tertinggi negara.', 'Ketua negeri bagi Wilayah Persekutuan ialah Yang di-Pertuan Agong.'),
(223, 2, 'Apakah kepentingan taat setia dan menghormati ketua negeri?', 'Menambah cukai negeri', 'Mengurangkan kawalan undang-undang', 'Menghentikan sekolah', 'Memastikan kestabilan negara', 'D', 'Hubungkan dengan keamanan.', 'Menghormati ketua negeri memastikan kestabilan dan memperkukuh sistem pemerintahan.'),
(224, 2, 'Apakah ibu negeri bagi negeri Perlis dan bandar dirajanya?', 'Alor Setar dan Anak Bukit', 'Kuantan dan Pekan', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'C', 'Ibu negeri bermula huruf K.', 'Perlis: Kangar (ibu negeri) dan Arau (bandar diraja).'),
(225, 2, 'Apakah ibu negeri dan bandar diraja bagi Pahang?', 'Kangar dan Arau', 'Kuantan dan Pekan', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'B', 'Ibu negeri di pantai timur.', 'Pahang: Kuantan dan Pekan.'),
(226, 2, 'Negeri Sembilan mempunyai bandar diraja bernama...', 'Seri Menanti', 'Arau', 'Klang', 'Pekan', 'A', 'Ia terletak di kawasan istana lama.', 'Ibu negeri Seremban, bandar diraja Seri Menanti.'),
(227, 2, 'Siapakah antara berikut yang tidak mempunyai ibu negeri dan bandar diraja?', 'Perlis', 'Kedah', 'Johor', 'Wilayah Persekutuan', 'D', 'Ketuanya Yang di-Pertuan Agong.', 'Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja.'),
(228, 2, 'Apakah bandar diraja?', 'Bandar yang paling besar di negeri', 'Pusat pentadbiran negeri', 'Bandar yang terdapat warisan sejarah seperti istana dan muzium', 'Bandar pelabuhan antarabangsa', 'C', 'Fikirkan istana dan galeri.', 'Bandar diraja ialah bandar yang terdapat warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan galeri.'),
(229, 2, 'Lagu negeri Sabah ialah...', 'Ibu Pertiwiku', 'Sabah Tanah Airku', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'B', 'Nama lagu menyebut nama negeri.', 'Lagu negeri Sabah ialah Sabah Tanah Airku.'),
(230, 2, 'Lagu negeri Sarawak ialah...', 'Ibu Pertiwiku', 'Sabah Tanah Airku', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'A', 'Lagu bertema tanah air.', 'Lagu negeri Sarawak ialah Ibu Pertiwiku.'),
(231, 2, 'Negeri manakah yang lagunya ialah Duli Yang Maha Mulia?', 'Johor', 'Perak', 'Kedah', 'Selangor', 'D', 'Ia negeri di Lembah Klang.', 'Lagu negeri Selangor ialah Duli Yang Maha Mulia.'),
(232, 2, 'Apakah lagu negeri Perak?', 'Allah Selamatkan Sultan Mahkota', 'Allah Selamatkan Sultan Kami', 'Allah Lanjutkan Usia Sultan', 'Berkatlah Yang di-Pertuan Besar', 'C', 'Menyebut usia sultan.', 'Lagu negeri Perak ialah Allah Lanjutkan Usia Sultan.'),
(233, 2, 'Lagu Berkatlah Yang di-Pertuan Besar ialah lagu negeri...', 'Johor', 'Negeri Sembilan', 'Selangor', 'Perlis', 'B', 'Menyebut gelaran ketua negeri.', 'Lagu negeri Negeri Sembilan ialah Berkatlah Yang di-Pertuan Besar.'),
(234, 2, 'Mengapakah kita perlu menghormati lambang negeri?', 'Ia melambangkan kedaulatan dan memupuk perpaduan', 'Supaya mendapat wang', 'Supaya negeri lain takut', 'Kerana ia hiasan sahaja', 'A', 'Hubungkan dengan identiti dan perpaduan.', 'Menghormati lambang negeri menghargai sejarah, memupuk perpaduan dan menjaga keamanan.'),
(235, 2, 'Bagaimanakah kita menunjukkan rasa bangga terhadap warisan negeri-negeri di Malaysia?', 'Membiarkan istana lama rosak', 'Melupakan lagu negeri', 'Menolak lambang negeri lain', 'Menghargai, mencintai dan mempromosikan warisan', 'D', 'Pilih tindakan yang menjaga warisan.', 'Menghargai, mencintai dan mempromosikan warisan serta memulihara kesan tinggalan menunjukkan rasa bangga.'),
(236, 2, 'Apakah tajuk lagu negeri Perlis?', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Aamiin-Aamiin', 'Untuk Negeri Kita', 'C', 'Negeri ini ketuanya bergelar Raja.', 'Lagu negeri Perlis ialah Aamiin-Aamiin.'),
(237, 2, 'Apakah tajuk lagu negeri Kedah?', 'Aamiin-Aamiin', 'Allah Selamatkan Sultan Mahkota', 'Allah Lanjutkan Usia Sultan', 'Untuk Negeri Kita', 'B', 'Tajuknya menyebut mahkota.', 'Lagu negeri Kedah ialah Allah Selamatkan Sultan Mahkota.'),
(238, 2, 'Apakah tajuk lagu negeri Pulau Pinang?', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'Lagu Bangsa Johor', 'Ibu Pertiwiku', 'A', 'Ketuanya bergelar Yang di-Pertua Negeri.', 'Lagu negeri Pulau Pinang ialah Untuk Negeri Kita.'),
(239, 2, 'Apakah tajuk lagu negeri Melaka?', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'Untuk Negeri Kita', 'Melaka Maju Jaya', 'D', 'Tajuknya menyebut nama negeri itu.', 'Lagu negeri Melaka ialah Melaka Maju Jaya.'),
(240, 2, 'Apakah tajuk lagu negeri Johor?', 'Melaka Maju Jaya', 'Berkatlah Yang di-Pertuan Besar', 'Lagu Bangsa Johor', 'Duli Yang Maha Mulia', 'C', 'Tajuknya menyebut nama negeri itu.', 'Lagu negeri Johor ialah Lagu Bangsa Johor.'),
(241, 2, 'Apakah tajuk lagu negeri Pahang?', 'Selamat Sultan', 'Allah Selamatkan Sultan Kami', 'Allah Lanjutkan Usia Sultan', 'Sabah Tanah Airku', 'B', 'Tajuknya menyebut ''Kami''.', 'Lagu negeri Pahang ialah Allah Selamatkan Sultan Kami.'),
(242, 2, 'Dua negeri manakah yang menggunakan tajuk lagu Selamat Sultan?', 'Terengganu dan Kelantan', 'Pahang dan Terengganu', 'Pahang dan Kelantan', 'Kedah dan Perak', 'A', 'Kedua-duanya di pantai timur, tetapi bukan Pahang.', 'Terengganu dan Kelantan sama-sama menggunakan tajuk Selamat Sultan.'),
(243, 2, 'Apakah tajuk lagu Wilayah Persekutuan?', 'Sabah Tanah Airku', 'Ibu Pertiwiku', 'Untuk Negeri Kita', 'Maju dan Sejahtera', 'D', 'Tajuknya tentang kemajuan.', 'Lagu Wilayah Persekutuan ialah Maju dan Sejahtera.'),
(244, 2, 'Apakah ibu negeri bagi Sarawak dan Sabah?', 'Kangar dan Arau', 'Kuantan dan Pekan', 'Kuching dan Kota Kinabalu', 'Ipoh dan Kuala Kangsar', 'C', 'Kedua-duanya di Borneo.', 'Ibu negeri Sarawak ialah Kuching dan Sabah ialah Kota Kinabalu.'),
(245, 2, 'Apakah ibu negeri dan bandar diraja bagi Selangor?', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'Johor Bahru dan Bandar Maharani', 'Ipoh dan Kuala Kangsar', 'B', 'Bandar diraja bermula dengan huruf K.', 'Ibu negeri Selangor ialah Shah Alam dan bandar dirajanya Klang.'),
(246, 2, 'Apakah ibu negeri dan bandar diraja bagi Johor?', 'Johor Bahru dan Bandar Maharani', 'Seremban dan Seri Menanti', 'Shah Alam dan Klang', 'Kangar dan Arau', 'A', 'Bandar dirajanya bermula dengan ''Bandar''.', 'Ibu negeri Johor ialah Johor Bahru dan bandar dirajanya Bandar Maharani.'),
(247, 2, 'Apakah ibu negeri dan bandar diraja bagi Kedah?', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'Kuantan dan Pekan', 'Alor Setar dan Anak Bukit', 'D', 'Bandar dirajanya bermula dengan ''Anak''.', 'Ibu negeri Kedah ialah Alor Setar dan bandar dirajanya Anak Bukit.'),
(248, 2, 'Apakah ibu negeri dan bandar diraja bagi Perak?', 'Alor Setar dan Anak Bukit', 'Kangar dan Arau', 'Ipoh dan Kuala Kangsar', 'Shah Alam dan Klang', 'C', 'Bandar dirajanya bermula dengan ''Kuala''.', 'Ibu negeri Perak ialah Ipoh dan bandar dirajanya Kuala Kangsar.'),
(249, 2, 'Apakah ibu negeri bagi Terengganu dan Kelantan?', 'Kuantan dan Pekan', 'Kuala Terengganu dan Kota Bharu', 'Kangar dan Arau', 'Seremban dan Seri Menanti', 'B', 'Peta tidak menanda bandar diraja bagi kedua-duanya.', 'Ibu negeri Terengganu ialah Kuala Terengganu dan Kelantan ialah Kota Bharu.'),
(250, 2, 'Apakah ibu negeri Pulau Pinang dan Melaka?', 'George Town dan Bandar Melaka', 'Ipoh dan Seremban', 'Alor Setar dan Kuantan', 'Shah Alam dan Klang', 'A', 'Peta tidak menanda bandar diraja bagi kedua-duanya.', 'Ibu negeri Pulau Pinang ialah George Town dan Melaka ialah Bandar Melaka.'),
(251, 2, 'Pada tahun berapakah sembilan luak asal Negeri Sembilan dicatat?', '1877', '1887', '1673', '1773', 'D', 'Ia tahun abad ke-18.', 'Tahun sembilan luak asal Negeri Sembilan ialah 1773.'),
(252, 2, 'Dokumen ''Maharajah of Sabah'' bertarikh pada tahun...', '1773', '1887', '1877', '1963', 'C', 'Ia tahun abad ke-19.', 'Dokumen Maharajah of Sabah bertarikh 1877.'),
(253, 2, 'Binatang apakah yang menendang anjing pemburu Parameswara di bawah pokok?', 'Gajah putih', 'Pelanduk putih', 'Harimau putih', 'Kijang', 'B', 'Ia binatang kecil dan berani.', 'Pelanduk putih menendang anjing pemburu Parameswara.'),
(254, 2, 'Apakah gelaran ketua negeri Perak dan Kedah?', 'Sultan', 'Raja', 'Yang di-Pertuan Besar', 'Yang di-Pertua Negeri', 'A', 'Gelaran paling banyak digunakan.', 'Perak dan Kedah menggunakan gelaran Sultan.'),
(255, 2, 'Apakah maksud Kadaram atau kalagam dalam tulisan Tamil?', 'Nama Perlis', 'Nama Sabah', 'Nama Johor', 'Nama Kedah', 'D', 'Berkait dengan negeri di utara.', 'Kadaram atau kalagam ialah nama Kedah dalam tulisan Tamil.'),
(256, 2, 'Apakah yang dilambangkan oleh bendera, lagu dan jata sesebuah negeri?', 'Cukai negeri', 'Keluasan negeri', 'Identiti dan lambang kemegahan negeri', 'Bilangan penduduk', 'C', 'Ia berkait dengan rasa bangga.', 'Bendera, lagu dan jata ialah identiti dan lambang kemegahan negeri.'),
(257, 2, 'Asal nama Kedah dan Perlis berkait dengan bahasa Siam, Arab dan Tamil. Apakah yang ditunjukkan oleh keadaan ini?', 'Semua nama negeri dicipta pada masa yang sama oleh British', 'Negeri itu dahulu dikunjungi pelbagai bangsa', 'Bahasa Melayu tidak pernah digunakan di negeri itu', 'Nama negeri tidak mempunyai sebarang makna sejarah', 'B', 'Fikirkan Kheddah, Qadah, Kadaram dan prow-lowy.', 'Pelbagai asal bahasa menunjukkan hubungan negeri-negeri itu dengan pedagang dan bangsa lain sejak dahulu.'),
(258, 2, 'Mengapakah ketua negeri Pulau Pinang, Melaka, Sarawak dan Sabah bergelar Yang di-Pertua Negeri dan bukan Sultan?', 'Negeri itu tidak beraja', 'Negeri-negeri itu jauh lebih kecil daripada negeri lain', 'Gelaran itu hanya digunakan untuk Wilayah Persekutuan', 'Gelaran Sultan sudah dihapuskan di seluruh negara sejak 1963', 'A', 'Ingat empat negeri yang ketuanya dilantik.', 'Pulau Pinang, Melaka, Sarawak dan Sabah tidak beraja, maka ketuanya bergelar Yang di-Pertua Negeri.'),
(259, 2, 'Seorang pengacara memainkan lagu Perak ketika majlis rasmi negeri Selangor. Apakah kesannya?', 'Majlis menjadi lebih meriah dan lebih bermakna', 'Tiada kesan kerana semua lagu negeri adalah sama', 'Lagu itu menjadi lagu rasmi negeri Selangor', 'Kurang menghormati lambang negeri tuan rumah', 'D', 'Lagu negeri ialah lambang kemegahan negeri itu.', 'Lagu negeri membentuk identiti dan lambang kemegahan, jadi lagu yang salah menunjukkan kurang hormat.'),
(260, 2, 'Mengapakah istana dan bangunan lama di bandar diraja perlu dipelihara?', 'Kerana semuanya boleh dijual kepada pelabur asing', 'Kerana bangunan baharu tidak dibenarkan dibina', 'Kerana menyimpan warisan sejarah negeri', 'Kerana ia menjadi pusat pentadbiran negeri sahaja', 'C', 'Bandar diraja ada istana, galeri dan monumen.', 'Bandar diraja menyimpan warisan sejarah yang menjadi identiti dan kebanggaan negeri.'),
(261, 2, 'Sebuah negeri mempunyai ibu negeri tetapi tiada bandar diraja yang ditanda pada peta. Negeri itu paling mungkin...', 'Perlis, kerana ketuanya ialah Raja yang bersemayam di Arau', 'Pulau Pinang, kerana tidak beraja', 'Perak, kerana Sultan bersemayam di Kuala Kangsar', 'Negeri Sembilan, kerana ada istana di Seri Menanti', 'B', 'Kaitkan bandar diraja dengan raja atau sultan.', 'Bandar diraja berkait dengan negeri beraja, sedangkan Pulau Pinang tidak beraja dan ibu negerinya ialah George Town.'),
(262, 2, 'Wilayah Persekutuan tidak mempunyai ibu negeri dan bandar diraja. Mengapakah keadaan ini wajar?', 'Kerana ditadbir terus oleh kerajaan Persekutuan', 'Kerana ia tidak mempunyai penduduk tetap', 'Kerana ia tidak mempunyai lagu rasmi dan jata sendiri', 'Kerana ia terletak jauh di Borneo', 'A', 'Fikirkan siapa ketua Wilayah Persekutuan.', 'Wilayah Persekutuan ditadbir terus oleh kerajaan Persekutuan, ketuanya Yang di-Pertuan Agong, maka ia tidak mempunyai ibu negeri atau bandar diraja.'),
(263, 2, 'Bagaimanakah kita dapat menunjukkan kebanggaan terhadap warisan negeri sendiri dengan cara yang paling bermakna?', 'Mengubah lagu dan jata mengikut selera sendiri setiap tahun', 'Melupakan sejarah negeri lain dan negeri sendiri', 'Menjual warisan itu kepada pihak luar negara', 'Memelihara dan memperkenalkannya kepada orang lain', 'D', 'Ingat sikap menghargai dan mempromosikan.', 'Memelihara dan mempromosikan warisan menunjukkan rasa bangga serta memastikan ia tidak hilang.'),
(264, 2, 'Nama sesebuah negeri sering lahir daripada alam, peristiwa atau bahasa. Apakah iktibar yang boleh diambil?', 'Nama negeri tidak penting untuk dipelajari oleh murid', 'Semua nama negeri berasal daripada satu bahasa asing sahaja', 'Nama negeri menyimpan sejarah yang perlu difahami', 'Nama negeri sentiasa ditukar mengikut setiap zaman', 'C', 'Kesan pelajaran asal nama negeri.', 'Nama negeri lahir daripada alam, peristiwa dan bahasa, jadi mempelajarinya membantu kita memahami sejarah negeri.');
